window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_005"]={"n":"萨都剌","dyn":"元","poems":[{"t":"登凤凰台二首 其一","f":"七言律诗","c":["凤凰台上望长安，五色宫袍照水寒。","綵笔十年留翰墨，银河一夜卧阑干。","三山飞鸟江天暮，六代离宫草树残。","始信人生如一梦，壮怀莫使酒杯乾。"]},{"t":"登凤凰台二首 其二","f":"七言律诗","c":["梧桐叶落秋风老，人去台空凤不来。","梁武台城芳草合，吴王宫殿野花开。","石头城下春生水，燕子堂前雨长苔。","莫问人间兴废事，百年相遇且衔杯。"]},{"t":"四时宫词四首 其四","f":"七言律诗","c":["悄悄深宫不见人，倚门惟有石麒麟。","芙蓉帐冷愁长夜，翡翠帘垂隔小春。","天远难通青鸟信，瓦寒欲动白龙鳞。","夜深怕有羊车到，自起笼灯照雪尘。"]},{"t":"送王真人北上代刘宗师","f":"七言律诗","c":["玉佩丁东下界闻，天风吹动碧霞裙。","刘郎跨鹤游三岛，王子吹笙到五云。","洞府夜光传玉印，石坛月黑礼茅君。","若逢天上吴夫子，应问丹砂炼几分。"]},{"t":"上京即事 其九","f":"七言绝句","c":["紫塞风高弓力强，王孙走马猎沙场。","呼鹰腰箭归来晚，马上倒悬双白狼。"]},{"t":"秋词","f":"七言绝句","c":["清夜宫车出建章，紫衣小队两三行。","石阑干畔银灯过，照见芙蓉叶上霜。"]},{"t":"秋夜闻笛","f":"七言绝句","c":["何人吹笛秋风外，北固山前月色寒。","亦有江南未归客，徘徊终夜倚阑干。"]},{"t":"彭城杂咏呈廉公亮佥事 其三","f":"七言绝句","c":["雪白杨花拍马头，行人春尽过徐州。","夜凉一片城头月，曾照张家燕子楼。"]},{"t":"游会仙宫","f":"七言绝句","c":["霏霏凉露湿瑶台，半夜吹箫月下来。","山外春风将雨过，满庭撩乱碧桃开。"]},{"t":"道过赞善庵","f":"七言绝句","c":["夕阳欲下少行人，绿遍苔茵路不分。","修竹万竿松影乱，山风吹作满窗云。"]},{"t":"题淮安壁间","f":"七言绝句","c":["鱼虾泼泼初出网，梅杏青青已著枝。","满树嫩晴春雨歇，行人四月过淮时。"]},{"t":"赠弹筝者","f":"七言绝句","c":["银甲弹冰五十弦，海门风急雁行偏。","故人情怨知多少，扬子江头月满船。"]},{"t":"山中怀友 其四","f":"五言律诗","c":["自是麒麟种，卑栖又几年。","故庐南雪下，短褐北风前。","岁暮山林瘦，天高雨露偏。","惟应丈夫志，未受故人怜。"]},{"t":"台山怀古","f":"七言律诗","c":["越王故国四围山，云气犹屯虎豹关。","铜兽暗随秋露泣，海鸦多背夕阳还。","一时人物风尘外，千古英雄草莽间。","日暮鹧鸪啼更急，荒台丛竹雨斑斑。"]},{"t":"用韵寄龙江","f":"五言律诗","c":["之子金山去，梅天雾气沈。","海风吹浪急，江雨入楼深。","火尽无茶味，更长过烛心。","明朝好晴色，应是寄新吟。"]},{"t":"次韵登凌歊台","f":"七言律诗","c":["山势如龙去复回，閒云野望护崇台。","离宫夜有月高下，辇路日无人往来。","春色不随亡国尽，野花只作旧时开。","断碑衰草荒烟里，风雨年年上绿苔。"]},{"t":"层楼晚眺","f":"七言律诗","c":["广寒世界夜迢迢，醉拍阑干酒易消。","河汉入楼天不夜，江风吹月海初潮。","光摇翠幕金莲炬，梦断凉云碧玉箫。","休唱当时《后庭曲》，六朝宫殿草萧萧。"]},{"t":"送人之浙东","f":"五言律诗","c":["我还京口去，君入浙东游。","风雨孤舟夜，关河两鬓秋。","出江吴水尽，接岸楚山稠。","明日相思处，惟登北固楼。"]},{"t":"送南台从事刘子谦之辽东","f":"五言律诗","c":["往复一万里，嗟君已两行。","朔风吹野草，寒日下边城。","策马犯霜雪，逢人问路程。","归期在何日？","应是近新正。"]},{"t":"闽中苦雨","f":"五言律诗","c":["病客如僧懒，多寒拥毳裘。","三山一夜雨，四月满城秋。","海瘴连云起，江潮入市流。","钓竿如在手，便可上渔舟。"]},{"t":"游梅仙山和唐人韵 其三","f":"五言律诗","c":["仙人不可见，借鹤过仙家。","夜卧千峰月，朝餐五色霞。","祠空风扫叶，人去鹿衔花。","归隐知何日？","分炉学鍊砂。"]},{"t":"赠刘云江宗师","f":"七言律诗","c":["羽人推转阿香车，童子穿松拾翠华。","天上赐衣沾雨露，山中诗锦织云霞。","瑶台紫气秋横剑，石室丹光夜走砂。","拟借茅君三白鹤，乘风骑到玉皇家。"]},{"t":"白云答","f":"五言律诗","c":["使君抑何忙，宁不思故山。","茫茫天壤间，鸟倦犹知还。","石田紫芝老，茶灶碧藓斑。","胡不赋归来，分子屋半间。"]},{"t":"过嘉兴","f":"七言古诗","c":["三山云海几千里，十幅蒲帆挂烟水。","吴中过客莫思家，江南画船如屋里。","芦芽短短穿碧沙，船头鲤鱼吹浪花。","吴姬荡桨入城去，细雨小寒生绿纱。","我歌《水调》无人续，江上月凉吹紫竹。","春风一曲《鹧鸪吟》，花落莺啼满城绿。"]},{"t":"芙蓉曲","f":"七言律诗","c":["秋江渺渺芙蓉芳，秋江女儿将断肠。","绛袍春浅护云暖，翠袖日暮迎风凉。","鲤鱼吹浪江波白，霜落洞庭飞木叶。","荡舟何处采莲人，爱惜芙蓉好颜色。"]},{"t":"织女图","f":"曲","c":["兰闺织锦秦川女，大姬哑哑弄机杼。","小姬织倦何所思，帘幕无人燕双语。","成都花发江水春，门前马嘶车辚辚。","髻鬟两珥看欲堕，蛾眉八字画不伸。","良人一去无消息，冰蚕吐丝成五色。","柔肠九曲细于丝，万缕春愁正如织。","绮窗睡起闻早莺，西楼月落金盘倾。","暖霞拂地海棠晓，香雪泼户梨花晴。","日长深院机声动，梭影穿花飞小凤。","水心惊起鸳鸯飞，花底不成胡蝶梦。","纤纤玉指柔且和，香钩小袜裁春罗。","满怀心事付流水，荡日云锦生层波。","佳人自古多命薄，风里杨花随处落。","岂知丑妇嫁田家，生则同衾死同椁。","君不闻长安市上花满枝，东家胡蝶西家飞。","笼中鹦鹉唤新主，门外侍儿更故衣。","又不闻田家妇，日扫春蚕宵织布。","催租县吏夜打门，荆钗布裙夫短裤。","我题此画三嗟吁，百年丑好皆虚无。","排云便欲叫阊阖，为我献上《豳风图》。"]},{"t":"相逢行赠别旧友治将军","f":"曲","c":["一年相逢在京口，笑解吴钩换新酒。","城南桃杏花正开，白面青衫鞭马走。","一年相逢白下门，短衣窄袖呼郎君。","朝驰燕赵暮吴楚，逸气自觉凌青云。","一年相逢在阙下，东家蹇驴日相假。","有如臣甫去朝天，泥滑沙堤不敢打。","都门一别今五年，今年相逢沧海边。","千山木叶下如雨，雁声堕地秋连天。","将军毳袍腰羽箭，拥马旌旗照溪面。","小官不识将军谁，卧病孤舟强相见。","岂知此地逢故人，摩挲老眼开层云。","旧游历历似隔世，夜雨岂不思同群。","郎君别后瘦如许，无乃从前作诗苦。","溪头月落山馆深，剪烛犹疑梦中语。","人生聚散亦有时，且与将军游武夷。","弓刀挂在洞前树，洞里仙童来觅诗。","稽首武夷君，借我幔峰顶。","分我紫霞浆，与子连夜饮。","左手招子乔，右手招飞琼。","举觞星月下，听吹双凤笙。","我酌一杯酒，持劝天上月。","劝尔长照人相逢，莫向关山照离别。","凤笙换曲曲未终，天风木杪吹晨钟。","拂衣罢宴下山去，又隔云山千万重。"]},{"t":"秋日池上","f":"五言律诗","c":["顾兹林塘幽，消此閒日永。","飘风乱萍踪，落叶散鱼影。","天清晓露凉，秋深藕花冷。","有怀无与言，独立心自省。"]},{"t":"登乐陵台倚梧桐望月有怀南台李御史艺七夕后一日也","f":"七言律诗","c":["凉风吹堕梧桐叶，泻下泠泠露华白。","乐陵台上悄无人，独倚梧桐看明月。","月高当午桐阴直，不觉衣沾露华湿。","此时却忆在金陵，酒醒江楼听吹笛。"]},{"t":"燕姬曲","f":"七言古诗","c":["燕京女儿十六七，颜如花红眼如漆。","兰香满路马尘飞，翠袖笼鞭娇欲滴。","春风淡荡摇春心，锦筝银烛高堂深。","绣衾不暖锦鸳梦，紫帘垂雾天沈沈。","芳年谁惜去如水，春困著人倦梳洗。","夜来小雨润天街，满院杨花飞不起。"]},{"t":"卜算子 泊吴江夜见孤雁","f":"曲","c":["明月丽长空，水净秋宵永。","悄无鸟鹊向南飞，但见孤鸿影。","自离边塞路，偏耐江波静。","西风鸣宿梦魂单，霜落蒹葭冷。"]},{"t":"少年游","f":"曲","c":["去年人在凤凰池。","银烛夜弹丝。","沉火香消，梨云梦暖，深院绣帘垂。","今年冷落江南夜，心事有谁知。","杨柳风和，海棠月淡，独自倚阑时。"]},{"t":"木兰花慢 彭城怀古","f":"曲","c":["古徐州形胜，消磨尽、几英雄。","想铁甲重瞳，鸟骓汗血，玉帐连空。","楚歌八千兵散，料梦魂、应不到江东。","空有黄河如带，乱山起伏如龙。","汉家陵阙动秋风。","禾黍满关中。","更戏马台荒，画眉人远，燕子楼空。","人生百年如寄，且开怀、一饮尽千钟。","回首荒城斜日，倚阑目送飞鸿。"]},{"t":"水龙吟 赠友","f":"曲","c":["王郎锦带吴钩，醉骑赤鲤银河去。","绛袍弄月，银壶吸酒，锦笺挥兔。","秃鬓西风，短篷落月，东吴西楚。","怅丹阳郭里，相逢较晚，共剪烛、西窗雨。","文采风流俊伟，碧纱巾挂珊瑚树。","出门万里，掀髯一笑，青山无数。","扬子江头，冻沙寒雨，暮天飞鹭。","待明朝酒醒金山，□□过瓜洲渡。"]},{"t":"念奴娇 登石头城次东坡韵","f":"曲","c":["石头城上，望天低吴楚，眼空无物。","指点六朝形胜地，唯有青山如壁。","蔽日旌旗，连云樯橹，白骨纷如雪。","一江南北，消磨多少豪杰。","寂寞避暑离宫，东风辇路，芳草年年发。","落日无人松径里，鬼火高低明灭。","歌舞尊前，繁华镜里，暗换青青发。","伤心千古，秦淮一片明月。"]},{"t":"忆江南","f":"曲","c":["天喉舌，尚书老布衣。","向璇穹、尝扶日出，卷珠箔、闲看云飞。","成全今古稀。"]},{"t":"忆江南","f":"曲","c":["鬓未银，东风早挂冠。","侑词图、乡称人瑞，度蓬瀛、仙祝灵丹。","绕膝舞斓斑。"]},{"t":"满江红 金陵怀古","f":"曲","c":["六代繁华，春去也、更无消息。","空怅望、山川形胜，已非畴昔。","王谢堂前双燕子，乌衣巷口曾相识。","听夜深、寂寞打孤城，春潮急。","思往事，愁如织。","怀故国，空陈迹。","但荒烟衰草，乱鸦斜日。","玉树歌残秋露冷，胭脂井坏寒螀泣。","到如今、惟有蒋山青，秦淮碧。"]},{"t":"酹江月","f":"曲","c":["金陵王气，绕道人丹室，紫霞红雾。","一夜神光雷电转，江左云龙飞去。","翠辇金舆，绮窗朱户，总是神游处。","至今花草，承恩犹带风雨。","落魄野服黄冠，榻前赐号，染蔷薇香露。","归卧蒲龛春睡暖，耳畔犹闻天语。","万寿无疆，九重闲暇，应忆江东路。","遥瞻凤阙，寸心江水东注。"]},{"t":"酹江月 任御史有约不至","f":"曲","c":["秦淮晓发，挂云帆十丈，天风如箭。","一碧湖光三十里，落日水平天远。","系马维舟，买鱼沽酒，杨柳人家店。","轻寒袭袂，淮南春色犹浅。","几度暮鼓晨钟，南来北去，游子心□倦。","芳草萋萋天际绿，怅望故人应转。","翠袖偎香，锦筝弹月，何处相留恋。","有人独自，灯花深夜频剪。"]},{"t":"酹江月 过淮阴","f":"曲","c":["短衣瘦马，望楚天空阔，碧云林杪。","野水孤城斜日里，犹忆那回曾到。","古木鸦啼，纸灰风起，飞入淮阴庙。","椎牛酾酒，英雄千古谁吊。","何处漂母荒坟，清明落日，肠断王孙草。","鸟尽弓藏成底事，百事不如归好。","半夜钟声，五更鸡唱，南北行人老。","道傍杨柳，青青春又来了。"]},{"t":"酹江月 姑苏台怀古","f":"曲","c":["倚空台榭，爱朱阑飞瞰，百花洲渚。","云岭回廊香径悄，争似旧时庭户。","槛外游丝，水边垂柳，犹学宫腰舞。","繁华如梦，登临无限情古。","果见荒台落日，麋鹿来游，漫尔繁榛莽。","忠臣抉目东门上，可退越来兵伍。","空铸千将，终为池沼，掩面归何所。","遗风千载，尚听侬歌白苎。"]},{"t":"酹江月 游句曲茅山","f":"曲","c":["一壶幽绿，爱松阴满地，蕊珠宫府。","老鹤一声霜衬履，隔断人间尘土。","月户云窗，石田瑶草，丹井飞龙虎。","荼蘼花落，东风吹散红雨。","春透紫髓琼浆，玻璃杯酒，滑泻蔷薇露。","前度刘郎重到也，开尽碧桃无数。","花外琵琶，柳边莺燕，玉佩摇金缕。","三山何在，乘鸾便欲飞去。"]},{"t":"酹江月 登凤凰台怀古用前韵","f":"曲","c":["六朝形胜，想绮云楼阁，翠帘如雾。","声断玉箫明月底，台上凤凰飞去。","天外三山，洲边一鹭，李白题诗处。","锦袍安在，淋漓醉墨飞雨。","遥忆王谢功名，人间富贵，散草头朝露。","淡淡长空孤鸟没，落日招提铃语。","古往今来，人生无定，南北行人路。","浩歌一曲，莫辞别酒频注。"]},{"t":"酹江月 题清溪白云图","f":"曲","c":["周郎幽趣，占清溪一曲，小桥横渡。","溪上红尘飞不到，惟有白云来去。","出岫无心，凌江有态，水面鱼吹絮。","倚门遥望，钟山一半留住。","涵影淡荡悠扬，朝朝暮暮，是几番今古。","指点昔人行乐地，半是鹭汀鸥渚。","映水朱楼，踏歌画舫，寂寞知何处。","天涯倦客，几时归钓春雨。"]},{"t":"过池阳怀李翰林","f":"五言古诗","c":["我思李太白，有如云中龙。","垂光紫皇案，御笔生青红。","群臣不敢视，射目目尽盲。","脱靴手污袜，蹴踏将军雄。","沈香走白兔，玉环失颜容。","春风不成雨，殿阁悬妖虹。","长啸拂紫髯，手撚青芙蓉。","挂席天万里，遨游江之东。","濯足五湖水，脱巾九华峰。","放舟玉镜潭，弄月秋浦中。","羁怀正浩荡，行乐未及终。","白石烂齿齿，貂裘泪濛濛。","神光走霹雳，水底鞭雷公。","采石波浪急，青山云雾重。","我有一杯酒，和泪洒天风。"]},{"t":"题潭州刘氏姊妺二孀贞节","f":"曲","c":["双藤本同根，长大附高树。","树倒何所依，不离树根土。","刘家好姊妺，嫁作儒家妇。","儒生逝不返，姊妺何所去。","忆昔嫁夫时，各愿以偕老。","今日无所归，骨肉自相保。","一炉铸两镜，悬置东西窗。","窗前主人去，两镜复一双。","哀哉哀哉刘二孀。"]},{"t":"早发黄河即事","f":"五言古诗","c":["晨发大河上，曙色满船头。","依依树林出，惨惨烟雾收。","村墟杂鸡犬，门巷出羊牛。","炊烟绕茅屋，秋稻上陇丘。","尝新未及试，官租急徵收。","两河水平堤，夜有盗贼忧。","长安里中儿，生长不识愁。","朝驰五花马，暮脱千金裘。","斗鸡五坊市，酣歌醉高楼。","绣被夜中酒，玉人坐更筹。","岂知农家子，力穑望有秋。","短褐常不完，粝食常不周。","丑妇有子女，鸣机事耕畴。","上以充国税，下以祀松楸。","去年筑河防，驱夫如驱囚。","人家废耕织，嗷嗷齐东州。","饥饿半欲死，驱之长河流。","河源天上来，趋下性所由。","古人有善备，鄙夫无良谋。","我歌两河曲，庶达公与侯。","凄风振枯槁，短发凉飕飕。"]},{"t":"寄王伯循诸公 其五","f":"五言律诗","c":["霜高木叶空，江清水花净。","离怀江水深，楚女晚妆靓。","按拍听歌声，点箸行酒令。","白露满衣裳，迥野垂斗柄。"]},{"t":"宿乌石驿","f":"五言古诗","c":["云起乌石峰，雨洒紫溪岭。","孤馆如山深，愁人觉宵永。","灯花剪复开，风竹乱不整。","清晨渡闽关，南斗落衣领。","好写度关诗，点笔题石笋。"]},{"t":"寄铅山别驾完颜子忠","f":"五言古诗","c":["我议颜别驾，风度脩且閒。","近持五色笔，辉光动南蛮。","甘饮石井水，卧治鹅湖山。","玉峰露洒洒，风林佩珊珊。","表表台阁姿，岂久州郡间。","相思不相见，可爱不可攀。","海风夜月朗，飞度七闽关。"]},{"t":"石上晚酌天章台 其一","f":"五言古诗","c":["晚凉上乌石，置酒天章台。","夕日下山去，海风吹月来。","豪气吐千丈，朗吟动三台。","白露洒仙掌，银河泻金杯。","谁识芙蓉仙，飞身在蓬莱。"]},{"t":"石上晚酌天章台 其二","f":"五言古诗","c":["高台在层霄，肩舆上绝壁。","露下酒樽凉，月出海门白。","坐拂衣上云，醉卧林下石。","西风吹鬓毛，南斗在肘腋。","题诗向天阍，奎光射瑶席。"]},{"t":"宿台山寺绝顶","f":"五言律诗","c":["江白潮已来，山黑月未出。","树杪一灯明，云房人独宿。","近水星动摇，河汉下垂屋。","四月夜深寒，繁露在脩竹。"]},{"t":"望鼓山","f":"五言律诗","c":["鼓山起千仞，乃是东海垠。","蛟龙穴其下，霹雳翻海门。","砥柱俨不动，日夜雪浪奔。","何当临绝顶，俯视浴日盆。"]},{"t":"题汀州丁三溪知事卷","f":"五言古诗","c":["三溪会汀州，上有仙人居。","乃是丁令威，玉佩摇琼琚。","高秋下风露，水清映芙蕖。","华表惯闻鹤，小船閒钓鱼。","鉴湖风半曲，贺老意何如。"]},{"t":"夜兴","f":"五言古诗","c":["千峰走晴雷，风力吹边雨。","层云不成阴，残缺如败堵。","山深日易暝，孤馆孰宾主。","灯花翳复明，落叶声可数。","独立谁与亲，厨人夜深语。"]},{"t":"题茶阳驿飞亭","f":"五言律诗","c":["白云飞出山，怒擘苍峡裂。","幽谷湿晴云，绝壁洒飞雪。","万折入沧海，龙宫水晶阙。","簸扬弄珠人，冰帘挂寒月。"]},{"t":"将至大横驿舍舟乘舆暮行 其一","f":"五言律诗","c":["山行日已暮，肩舆度林薄。","凉飙凄以清，松子当面落。","千山月崔嵬，万叶雨萧索。","昨夕棹歌行，颇忆溪上乐。"]},{"t":"将至大横驿舍舟乘舆暮行 其二","f":"五言律诗","c":["月轮转头上，溪濑奏脚底。","人行山色中，叶落雨声里。","虚名为一官，游子在万里。","行行重行行，日夕聊复止。"]},{"t":"闻秋蛩有感","f":"五言律诗","c":["秋蛩集草树，凄然亦何繁。","行子在远道，岂不思故园。","禾稻上邱垄，鸟雀知欣喧。","田园可终老，轩冕何足言。"]},{"t":"赠白云","f":"五言律诗","c":["白云抑何閒，竟日不下山。","时从脩竹里，相伴一僧还。","悠悠覆松顶，渺渺归岫间。","奔走尘俗客，视君多厚颜。"]},{"t":"望武夷","f":"五言律诗","c":["溪行望武夷，峭壁何斩绝。","赤霞乱不收，大化元气泄。","下有万年松，上有太古雪。","秪恐月明中，铁笛吹石裂。"]},{"t":"宿武夷","f":"五言律诗","c":["舣舟山水间，借问武夷观。","月挂水晶帘，风吹紫霞幔。","鸡犬过云间，笙乐度天半。","传语武夷君，酒熟幸相唤。"]},{"t":"吴桥县古河堤","f":"五言律诗","c":["迢迢古河堤，隐隐若城势。","古来黄河流，而今作耕地。","都邑变通津，沧海化为尘。","堤长燕麦秀，不见筑堤人。"]},{"t":"溪行两岸皆芙蓉桂花余喜遂赋此诗","f":"曲","c":["芙蓉发蓓蕾，桂树花斓斑。","中秋前日过，客子未出关。","香生桂树丛，露下芙蓉叶。","花以寄远人，叶以作书帖。","何日棹船还，桂树芙蓉间。","船头听我夜吹笛，吹起月轮升东山。"]},{"t":"会杜清碧 其一","f":"五言律诗","c":["夜宿武夷山，乃是杜清叟。","清谈道人同，险路山鬼走。","出门视河汉，危梯挂星斗。","白露满芙蓉，清寒夜深久。"]},{"t":"会杜清碧 其二","f":"五言律诗","c":["我识杜清碧，深居武夷山。","采药紫芝岭，行歌白云间。","天根深可蹑，月窟高可攀。","天子召不起，道人閒往还。"]},{"t":"昼卧云际亭","f":"五言律诗","c":["红尘如海深，度水卧云际。","白云如故人，千峰走群婢。","长叹一欠伸，风叶飞满地。","一鸟没遥天，树矮浑如荠。"]},{"t":"过延平津 其一","f":"五言律诗","c":["神物在天地，变化须有时。","踊跃一入水，风云波浪随。","志士昔未遇，常人安得知。","一朝忽奋迅，儿女惊且疑。"]},{"t":"过延平津 其二","f":"五言律诗","c":["万山二水合，汇之为深渊。","剑化亦已矣，过者尤凛然。","神物岂常处，入地忽上天。","所以磊落士，岂为愚者怜。"]},{"t":"过延平津 其三","f":"五言律诗","c":["当时二龙剑，乃是山川精。","埋没于狱础，异气腾丰城。","神光射霄汉，牛斗为不明。","一入壮士手，长鸣除不平。"]},{"t":"鹦鹉曲","f":"曲","c":["水晶帘垂宫昼长，猩色屏风围绣床。","美人春睡苦不足，梦随飞燕游昭阳。","觉来粉汗湿香脸，一线柔红枕痕浅。","三十六宫在眼前，五色香云随指转。","牙床端坐杨太真，云冠霞佩绛色裙。","双成小玉各宫样，绣衣乌帽高将军。","雕笼七宝挂高树，玉案金盘看鹦鹉。","可怜鹦鹉解人言，不说渔阳动鼙鼓。","乃知禽语能戏人，不知人语能杀身。","亡家败国污天地，天生尤物天亦嗔。","一朝艳质化尘土，可恨可怜千万古。","香魂不逐马尘飞，犹托深闺绣房女。","想当盘礴欲绣时，停针想像心如丝。","绣成特自比容貌，伏枕自喜还自悲。","郎君有此从何得，怪底梅花心铁石。","偶然持赠百拙人，眉眶眼精生丑色。","少年阅此恼断肠，锦屏绣褥兰麝香。","夜深酒醒换银烛，时见杨妃在耳傍。","君不闻张丽华堕宫井，铜雀章台烟烬冷。","繁华一梦人不知，万事邯郸吕公枕。"]},{"t":"杨妃病齿图","f":"曲","c":["沈香亭北春昼长，海棠睡起扶残妆。","清歌妙舞一时静，燕语莺啼愁断肠。","朱唇半启榴房破，胭脂红注珍珠颗。","一点春寒入瓠犀，雪色鲛绡湿香唾。","九华帐里薰兰烟，玉肱曲枕珊瑚偏。","金钗半脱翠蛾敛，龙髯天子空垂涎。","妾身日侍君王侧，别有閒愁许谁测。","断肠塞上锦绷儿，万恨千愁言不得。","成都遥进新荔枝，金盘紫凤甘如饴。","红尘一骑不成笑，病中风味心自知。","君不闻延秋门，一齿作楚藏病根。","又不闻马嵬坡，一身溅血未足多。","渔阳指日鼙鼓动，始觉开元天下痛。","云台不见汉功臣，三十六牙何足用。","明眸皓齿今已矣，风流何处三郎李。"]},{"t":"王孙曲","f":"七言古诗","c":["内家楚楚诸王孙，白马金鞍耀晴日。","尊前细乐耳厌闻，世上閒愁生不识。","宫袍裁成五色云，珍珠簇就双龙纹。","衣裳光彩照暮春，红靴著地轻无尘。","翠楼珠箔玉钩挂，肠断宫腰无一把。","海棠花下昼闻莺，太液池边春洗马。","千枝万枝桃杏红，花枝飘香薰酒中。","归来月落酒未醒，有诏早入明光宫。"]},{"t":"蕊珠曲","f":"七言古诗","c":["芙蓉城里白玉楼，冰帘倒挂珊瑚钩。","玉人晏坐太清室，蛾眉不锁人间愁。","彩桥东畔杨花转，飞入三天紫清殿。","仙裳日暖藕丝香，燕语莺啼动幽怨。","天风泠泠吹佩环，霞冠不整偏云鬟。","萧郎风骨何可得，紫箫赤凤游云间。","瑶台午夜霜华瑩，罗袜生寒冰一寸。","锦屏甲帐蕊珠新，云房火鼎丹芽嫩。","天台仙子淡淡妆，桃花洞口逢刘郎。","巫山神女弄云雨，人去楚台空断肠。","步虚声断阑干外，春去秋来颜色改。","东风吹老碧桃花，深院无人夜如海。"]},{"t":"兰皋曲","f":"七言古诗","c":["溪水长涵幽草芳，春溪露滴兰叶光。","美人日暮采兰去，风吹露湿芙蓉裳。","芙蓉为裳兰结佩，玉立亭亭临水际。","天寒袖薄人不知，疏雨兰苕鸣翡翠。","幽兰日日吹古香，美人不来溪水长。"]},{"t":"威武曲","f":"曲","c":["桓桓燕将军，威武天下一。","赤面注丹砂，虬髯如插戟。","当年意气何鹰扬，手扶天子登龙床。","五年垂拱如尧汤，白日骑龙升上苍。","桓桓燕将军，威武何可量。","熹微日色出东方，早令一出照八方。","毋使三月人皇皇，毋使三月人皇皇。"]},{"t":"如梦曲哀燕将军 其一","f":"曲","c":["芙蓉花，为谁好，洞房昨夜将军老。","将军老去空铁衣，漆灯照室人不归。"]},{"t":"如梦曲哀燕将军 其二","f":"曲","c":["宫锦袍，毡帐高，将军夜酌凉蒲萄。","蒲萄力重醉不醒，美人犹在珊瑚枕。"]},{"t":"如梦曲哀燕将军 其三","f":"曲","c":["海子头，谁家楼，绣帘半捲风悠悠。","行人谓是将军府，将军不来罢歌舞。"]},{"t":"如梦曲哀燕将军 其四","f":"曲","c":["将军容，丹砂红，威风凛凛盖世雄。","出门千骑塞行路，今日萧萧去何处。"]},{"t":"如梦曲哀燕将军 其五","f":"曲","c":["平村曲，春水绿，将军猎回曾此宿。","将军一去成荒邱，依旧平村春水流。"]},{"t":"如梦曲哀燕将军 其六","f":"曲","c":["皂雕鹰，紫骝马，将军围猎平沙野。","朔风萧萧吹野寒，将军战马游不还。"]},{"t":"如梦曲哀燕将军 其七","f":"曲","c":["将军功，世莫比，皇都甲第连云起。","将军一去空锁门，上马台边无一人。"]},{"t":"如梦曲哀燕将军 其八","f":"楚辞体","c":["皓齿歌，细腰舞，绿窗朱户将军府。","将军老去无少年，为野草兮为荒田。"]},{"t":"如梦曲哀燕将军 其九","f":"曲","c":["如花人，樱桃唇，傍人近前丞相嗔。","繁华日日笙歌动，世事悠悠总如梦。"]},{"t":"如梦曲哀燕将军 其十","f":"曲","c":["朝作乐，暮作乐，朝暮杯盘金错落。","日出欲尽东方明，欢乐未已悲哀生。"]},{"t":"鞦韆谣","f":"七言古诗","c":["寒梅零落春雪洒，萧娘腰瘦无一把。","淡黄杨柳未成阴，何人已系青骢马。","画楼深处迎春归，鞦韆影里红杏肥。","濛濛花气湿人面，东风吹冷轻罗衣。","衣上粉珠流不歇，暗解翠裙花下摺。","殷勤莫遣燕子知，会向人间报风月。"]},{"t":"皂林道中","f":"七言律诗","c":["春溪野鸭肥可射，幽树阴深叫山鹧。","远人三月酒船归，柳絮飞时杏花谢。","行行水竹与云林，往往人家或僧舍。","小官便欲赋《归来》，何处买山钱可借。"]},{"t":"江南乐","f":"曲","c":["江南乐，春水红桥满城郭。","出门不用金马络，门前画船如画阁。","绿纱虚窗春雾薄，隔窗蛾眉秋水活，翡翠冠高罗袖阔。","楚舞吴歌劝郎酌，紫竹瑶丝相间作。","船头柳花如雪落，船尾彩旗风绰绰。","秉烛夜游随处泊，人生无如江南乐。"]},{"t":"江南怨","f":"曲","c":["江南怨，生男远游生女贱。","十三画得蛾眉成，十五新妆识郎面。","识郎一面思犹浅，千金买官游不转。","侬家水田跨州县，大船小船过淮甸。","买官未得不肯归，不惜韶华去如箭。","杨花扑檐飞语燕，疏雨梧桐闭深院，人生无如江南怨。"]},{"t":"登歌风台","f":"七言古诗","c":["歌风台前河水黄，歌风台前春草碧。","黄河之水日夜流，碧草年年自春色。","当时汉祖为帝王，龙泉三尺飞秋霜。","五年马上得天下，富贵乐在归故乡。","里中父老争拜跪，拄杖麻鞋见天子。","龙颜自喜还自伤，一半随龙半为鬼。","翻思向日亭长时，一身捧檄日夜驰。","只今宇宙极四海，一榻之外难撑持。","却思猛士卫神宇，安得长年在乡土。","可怜创业垂统君，却使乾机付诸吕。","淮阴年少韩将军，金戈铁马立战勋。","藏弓烹犬太急迫，解衣推食何殷勤。","倒使英雄遭妇手，血溅红裙当斩首。","萧何下狱子房归，左右功臣皆掣肘。","还乡却赋《大风歌》，向来老将今无多。","咸阳宫殿眼亲见，今日荆棘埋铜驼。","台前老人泪如雨，为言不特汉高祖。","古来此事无不然，稍稍升平忘险阻。","荒凉古庙依高台，前人已矣今人哀。","悲歌感慨下台去，断碑春雨生莓苔。"]},{"t":"过鲁港驿和贯酸斋题壁","f":"七言律诗","c":["吴姬水调新腔改，马上郎君好风采。","玉郎一去春草深，谩有狂名满江海。","歌诗呼酒江上亭，墨花飞雨江不晴。","江风吹破蛾眉月，我亦东南西北征。"]},{"t":"宣政同知燕京闾报国哀时文皇晏驾 其一","f":"曲","c":["雨倾盆，风掷瓦，白髯使者能骑马。","相逢官长马不下，马上云云泪盈把。"]},{"t":"宣政同知燕京闾报国哀时文皇晏驾 其二","f":"曲","c":["天柱倾，天不晴，白髯使者东南行。","东南山水失颜色，一夕秋风来上京。"]},{"t":"鼎湖哀","f":"七言古诗","c":["荆门一日雷电飞，平地竖起天王旗。","翠华摇摇照江汉，八表响应风云随。","千乘万骑到阙下，京师亦睹龙凤姿。","三军卵破虎北口，一矢血洗潼关尸。","五年晏然草不动，百谷䆉稏风雨时。","修文偃武法古道，天阁万丈奎光垂。","年年北狩循典礼，所有雨露天恩施。","宫官留守扫禁阙，日望照夜随金羁。","西风忽涌鼎湖浪，天下草木生号悲。","吾皇骑龙上天去，地下赤子将安依。","吾皇想亦有遗诏，国有社稷燕太师。","太师既受生死托，始终肝胆天地知。","汉家一线系九鼎，安肯半路生狐疑。","孤儿寡妇前日事，况复将军亲见之，况复将军亲见之。"]},{"t":"岁云暮矣 其一","f":"曲","c":["岁云暮矣，子将焉之。","江南木落鸿雁飞，娟娟美人淮水涯。","淮水去不止，相思日千里。"]},{"t":"岁云暮矣 其二","f":"曲","c":["岁将暮矣，子将焉往。","燕山雪花大如掌，娟娟美人淮水上。","淮水日夜流，相思人白头。"]},{"t":"岁云暮矣 其三","f":"曲","c":["岁云暮矣，子将焉行。","江南木落天雨霜，娟娟美人淮水傍。","淮水不回头，行人上小舟。"]},{"t":"京口寒夜和葛秀才床字韵","f":"七言律诗","c":["秋高马肥弓力强，山空木落天雨霜。","边庭晏然草不动，汉家将军一丈长。","江南地湿小臣病，闭户一月不下床。","愿言昭代举天网，亦有枳棘栖鸾凰。"]},{"t":"江上闻笛","f":"七言律诗","c":["江上何人吹竹笛，水浅沙寒龙夜泣。","鲛人水底织冰绡，洒泪成珠露华湿。","银河耿耿波茫茫，雁奴打更沙溆傍。","更深绣被夜寒重，明月梅花满地霜。"]},{"t":"寒夜与王记室宴集","f":"七言律诗","c":["欲雪无雪风力强，欲睡不睡寒夜长。","玉奴剪烛落燕尾，银瓶煮酒浮鹅黄。","二君豪饮不可敌，醉倒绿发参军郎。","夜深大吟且就枕，明朝万瓦看晴霜。"]},{"t":"就用韵赠铁将军","f":"七言律诗","c":["邺中健儿筋力强，豪气不减关云长。","挥戈叱咤阵云黑，酣风白昼吹日黄。","将军威武不可近，铁袍赤面黄须郎。","今年收功入将府，乌靴晓踏天街霜。"]},{"t":"夜寒独酌 其三","f":"七言律诗","c":["江风吹浪十丈强，孤舟远客愁夜长。","何如岁晚在家者，拥炉酌酒天昏黄。","蔡州鹅鸭持元济，滹沱马渡悲王郎。","杯中有物且须尽，勋业满镜生秋霜。"]},{"t":"北风行送王君实","f":"曲","c":["北风日日吹浮云，西南一星光射门。","出门见客钳口坐，打马送君收泪痕。","钳口祇自知，吞泪竟何益。","木叶下玄霜，日日北风急。","北风吹浅淮水波，坐见白日愁云多。","九关虎豹卧不动，奈尔狐狸燕雀何。"]},{"t":"留别同年索士岩经历","f":"曲","c":["欲落不落天上雪，欲去不去闽中人。","红尘香暖荔枝国，白日醉卧芙蓉茵。","功名富贵傥来物，政事文章奚足珍。","人生所贵在知己，四海相逢骨肉亲。","在知己，宁论千里与万里。","志士鸡鸣中夜起，秋雨粼粼剑光紫。"]},{"t":"走笔赠燕孟初","f":"曲","c":["别君金陵城，遇君钱塘驿。","落魄江湖懒折腰，笑傲公侯但长揖。","柳花吹香扑酒缸，酒波滟滟如春江。","西湖天镜碧堕地，吴山蛾眉春入窗。","平生豪气如虹吐，馀子纷纷何足数。","驿亭把酒歌别离，醉听江潮鸣万鼓。"]},{"t":"过桐君山","f":"七言古诗","c":["桐山峨峨桐水清，仙人不住芙蓉城。","山头笑指梧桐青，至今山水俱得名。","丹光夜照江水赤，赤浪神鱼夜飞出。","碧桃花下觅神仙，白日山中遇樵牧。","江深谷响山有灵，东山人唤西山应。","渔人误入水帘洞，石崖倒挂丹崖藤。","祠荒路断行人少，石上清风长瑶草。","月明黄鹤飞渡江，仙人一去梧桐老。"]},{"t":"武夷馆方池","f":"七言古诗","c":["武夷之境多神仙，我亦驻此临风轩。","方池清夜堕碧月，重帘白日垂洞门。","暗泉涌池紫波动，微雨在藻金鱼翻。","倚阑照影清光底，柱杖卓石寻无原。","洗头玉女去不返，遗此丈八芙蓉盆。","溪船明日泛九曲，出入紫翠听潺湲。","便从此地觅真隐，何必商山求绮园。"]},{"t":"蛾眉云谢照磨李伯贞遗白石","f":"曲","c":["仙人李太白，俊逸天下闻。","芙蓉宫锦袍，袖有蛾眉云。","蛾眉山高剑门隔，化为太古一片雪。","南州北越行相从，赤日炎风消不得。","今年东海逢故人，海波滟滟葡萄春。","酒酣拂袖堕秋水，但觉满座光嶙峋。","夜深酒醒伴狂客，玉井莲开华峰白。","海天落月挂奎娄，坐卧犹疑见颜色。","秃兔漫吐蛾眉云，何以报答双南金。","古人契义重金石，此物岁寒冰雪心。"]},{"t":"画马","f":"七言古诗","c":["汉水扬波洗龙骨，房星堕地天马出。","四蹄蹀躞若流星，两耳尖修如削笔。","天闲十二连青云，生长出入黄金门。","鼓鬃振尾恣偃仰，食粟何以酬主恩。","岂堪碌碌同凡马，长鸣喷沫奚官怕。","入为君王驾鼓车，出为将军静边野。","将军与尔同死生，要令四海无战争，千古万古歌太平。"]},{"t":"题云山图","f":"七言古诗","c":["我有将军万叠青，换得琅玕半窗绿。","月明恐有凤来栖，日暮何妨云借宿。","清时海宇无烽烟，五风十雨歌丰年。","看山爱竹了公事，焚香挂画似神仙。","城头漏箭催更鼓，将军夜寝元戎府。","怪底云山光满林，床头斜挂三珠虎。"]},{"t":"题陈所翁龙","f":"七言古诗","c":["画龙天下称所翁，秃笔光照骊珠宫。","长廊白日走云气，大厦六月生寒风。","兴来一饮酒一石，手提玄兔追霹雳。","涨天烟雾晴不收，头角峥嵘出墙壁。","全形具体得者稀，今日海边亲见之。","满堂火燄动鳞甲，倒挟海水空中飞。","凌风直上九天去，天下苍生望甘雨。","太平天子居九重，黍稷穰穰千万古。"]},{"t":"题寿监司所藏瘦马图","f":"七言律诗","c":["沙场日暮春草肥，瘦马不受黄金羁。","天生神骏天所爱，岂容过市无人知。","郎官病坐芙蓉幕，喜见马图天上落。","人生相遇贵相知，孰谓世间无伯乐。"]},{"t":"喜寿里客厅雪山壁图","f":"曲","c":["一年在京口，雪片冬深大如手。","独骑瘦马入谁家，四面云山如户牖。","大江东去流无声，金焦二山如水晶。","瓜洲江口人不渡，时有蓑笠渔舟横。","一年在建业，腊月梅花满城雪。","五更冻合石头城，霜风鼓寒冰柱裂。","秦淮酒楼高十层，钟山对面如银屏。","鹭洲不见二水白，天外失却三山青。","一年在镇阳，燕山积雪飞太行。","滹沱冰合断人迹，井陉路失迷羊肠。","长空万里绝飞鸟，卷地朔风吹马倒。","狐裘公子猎城南，茅店酒旗摇树杪。","今年入闽关，马蹄出没千万山。","瘴烟朝暮气霭霭，石泉日夜声潺潺。","雪花半落不到地，但见晴空涌流翠。","海头鼓角动边城，木末楼台出僧寺。","何人蹇驴踏软沙，出门无处不梅花。","江潮入市海船集，水暖游鱼不用叉。","良工画出雪色壁，过眼令人忆南北。","玉京银阙五云端，待漏何年凤池侧。"]},{"t":"吴真人京馆画壁","f":"七言古诗","c":["砚池花落丹水香，步虚白日声琅琅。","江南道士爱潇洒，新粉素壁如秋霜。","王郎酒酣衫袖湿，醉眼朦胧电光急。","玄龙云重雨脚斜，白兔秋高月中泣。","倦游借榻日观东，恍忽夜梦三湘中。","鹧鸪声断江路远，青林雨暗春濛濛。"]},{"t":"梅仙山行","f":"七言古诗","c":["赤星落色汉祚微，端门日日边风吹。","咸阳秋色压宫树，金人夜泣铜驼悲。","先生袖疏探虎窟，汉鼎犹堪支一足。","九重烟雾似海深，门外何人知恸哭。","贼莽白日升高台，玉玺堕地声如雷。","周公揖让孺子戏，绛袍将军何日来。","尘飞沧海风掷瓦，白鹤身轻快如马。","一声铁笛度闽关，山月溪风共潇洒。","龙争虎斗耳不闻，长啸袖拂松枝云。","夜铛白日煮秋雨，玉佩赤锦飘霞裙。","先生一去几千载，尚有当年遗迹在。","题诗绝壁寄先生，顿使林峦颜色改。","药炉寂莫秋草深，丹井水落莓苔侵。","至今火灰化为土，犹有丹光穿树林。"]},{"t":"马翰林寒江钓雪图","f":"七言古诗","c":["天寒日短乌鸦啼，江空野阔黄云低。","村南村北人迹断，山后山前玉树迷。","歌楼酒香金帐暖，岂知篷底鱼羹饭。","一丝天地柳花春，万顷烟波莲叶晚。","风流不数王子猷，清兴不减山阴舟。","人间富贵草头露，桐江何处寻羊裘。","还君此画三叹息，如此江湖归未得。","洗鱼煮酒卷孤篷，江上云山好晴色。"]},{"t":"登云际题壁","f":"曲","c":["长吟入云际，袖拂日边霞。","摩挲织女机，柱杖倚灵槎。","闻说名泉奇观，倒泻银河千丈玉乳溅飞花。","寄语陆鸿渐，我有武夷茶。","令仆支铛僧，扫叶鹤看家。","不妨茶罢酣歌醉饮，直到日西斜。","满笔淋漓醉墨，应有山灵夜护林壑动龙蛇。","秉烛下山去，渡口月笼沙。"]},{"t":"同曹克明清明日登北固山次韵 其一","f":"七言古诗","c":["江南三月万花柳，北固山头一回首。","东风吹绿扬子江，滟滟江波泻春酒。","况乃又是清明天，元从一饮三百钱。","英雄一去几千载，当年饮者今何在。","陌上家家列纸钱，孙刘高冢何人拜。"]},{"t":"送广信司狱","f":"七言古诗","c":["江城六月凉雨馀，吴郎买舟之鹅湖。","江南酌别酒满壶，酒尽落日青天孤。","如君俊气江海少，奇语惊人天所宝。","春莺乳燕绿窗深，酒醒梦回银烛小。","江东子弟多少年，见君丰采如神仙。","时明刑措日无事，檀板且下鹅湖船。","鹅湖山下秋稻熟，鹅湖山前秋水绿。","五风十雨乐太平，肯使人间有冤狱。"]},{"t":"和友人游鹤林韵","f":"七言古诗","c":["何人结屋山之阻，剩水残山半间与。","竹院东风僧未归，落日楼台自铃语。","刘家事业今沉沦，空馀黄鹄青嶙峋。","孙家气概果何在，当时未必分伪真。","可怜处士若冯道，安得骂贼如张巡。","百年往事空白日，万山花落如红尘。","不如扫地倾二斗，径造何必问主人。","东廊西廊云不扫，白鹤归来立华表。","沈郎敲棋山鸟惊，陈郎落笔龙蛇绕。","葛公饮酒不论钱，何必三茅求悟道。","乌髯白面郭将军，痛哭长歌写怀抱。","了公绝若耳不闻，何处深山拾瑶草。","倚歌和者病参军，小窗病起风日好。","荼䕷满庭香雪晴，柳花帘幕捲春晓。","人生乐事当胜游，山堂作者半日留。","古来此事谁不乐，只恐人去山灵愁。"]},{"t":"高堂刘侯定斋野友亭","f":"七言古诗","c":["淮阴季年韩将军，狡兔已死走狗烹。","沛中白发周将军，碧色已满细柳营。","何如高堂刘将军，太平不许矢石勋。","棹头青海无传箭，天山挂却乌角巾。","归来买地筑小亭，漯水为镜山为屏。","樵人溪叟日相过，野歌村舞醉复醒。","去年偶尔剑戟鸣，潼关马过战血腥。","白头老子如不闻，牛背一笑千山青。"]},{"t":"贺山长邱臣敬复淮西田","f":"七言古诗","c":["鄞城公子人中英，天恩教领来国城。","秋霜满区老剑鸣，开口磊落肝胆明。","前年岁丰夏无麦，去年雨足秋无粟。","先生激烈气不平，馆下谁令有饥色。","扬眉掉臂傍无人，义动天子耳目臣。","谁人归我三千里，坐令孔席回阳春。","只今寒士望梁栋，文梓高梧天所用。","诸生食饱待先生，日午杏坛看舞凤。"]},{"t":"补阙歌","f":"七言古诗","c":["钱塘三日风雨急，古铜夜光飞霹雳。","是知神物出人间，犹带吴宫土花碧。","玉桥素练悬银河，支机女儿飞凤梭。","虾须风软乱纤影，春水日晴生潮波。","破窗冷砚留不得，零落江南酒家客。","狂歌索酒仰面歇，误击红筹唾壶裂。","何人进入蓬莱宫，银屏碧幕珠帘重。","此生补阙亦何用，玉龙泻水流芙蓉。"]},{"t":"过淮河有感","f":"曲","c":["淮水清，河水黄，出山偶尔同异乡。","排空卷雪势莫当，随风逐浪庸何伤。","东流入海殊不恶，万里同行有清浊。"]},{"t":"拥炉夜酌嘲张友寄诗谢","f":"曲","c":["张生不好酒，饮酒如饮药。","得酒味濡唇，形影先落魄。","野人饮不辞，饮尽杯中涸。","酒渴向茶烟，松风语幽壑。","芳山道士胡不来，一夜灯花向人落。"]},{"t":"送友人之京","f":"七言律诗","c":["霜高木落河始冰，台郎别我之燕京。","朔风迎面飞鸟尽，腊雪打帽鞭马行。","新年捧表拜阙下，春寒诏赐玻瓈觥。","朝官如问小参军，为言卧病丹阳城。"]},{"t":"题南宫子蜡嘴图","f":"七言律诗","c":["南宫山人何俊奇，小窗睡起凉云飞。","野棠秋早霜子熟，枯木叶高蜡嘴肥。","满前累累甘尔口，正犹痴心落人手。","五陵年少知尔名，一饱无人早回首。"]},{"t":"西楼别寄闽宪诸公","f":"曲","c":["八月八日溪上别，溪上彩旗红猎猎。","离情已逐渡江云，边草连天剪秋色。","玉骢金虎诸大夫，欲别不别留斯须。","沙明浅渚白鸟下，酒尽落日青山孤。","丈夫有泪不须洒，去客挂帆君上马。","悠悠回首各东西，惟见西溪捕鱼者。","闽关一片月，太行一片云。","雁书远寄隔山岳，云飞月明多忆君。"]},{"t":"赠别鹫峰上人","f":"曲","c":["建溪秋高山水清，溪边偶识衡阳僧。","临水洗钵挂溪阁，夜访校书天禄灯。","圣经佛偈通宵读，苜蓿堆盘胜食肉。","回雁峰南难寄书，武夷洞前堪煮粥。","西风猎猎吹水寒，相送郎官南出关。","校书公子玉京去，衡阳上人何日还。","手中玉杖春雨绿，毋乃湘君庙前竹。","胡不截作双凤箫，吹作来仪舜庭曲。","古曲雅以淡，天高难上闻。","不如且挂杖头月，归卧祝融峰畔云。"]},{"t":"送马伯庸子之京","f":"七言古诗","c":["欲晴不晴天气悭，欲别不别人语难。","丈夫意气自磊落，握手一笑心与肝。","南宫子弟吐金缕，何必尊前花解语。","树摇晚翠下风凉，烛落春红剪秋雨。","高歌痛饮如有神，醉吐不惜车中茵。","明朝送子上船去，回首江南江北人。"]},{"t":"送韩司业","f":"七言律诗","c":["杨花落尽梅子青，丹阳酒满双玉瓶。","使君买舟渡江去，落日淡淡波溟溟。","先生抱才登馆阁，东壁文采光龙廷。","自怜落日江湖上，为言纵迹如云萍。"]},{"t":"蒲萄酒美鲥鱼味肥赋蒲萄歌","f":"七言古诗","c":["扬州酒美天下无，小槽夜走蒲萄珠。","金盘露滑碎白玉，银瓮水暖浮黄酥。","柳花吹尽春江涨，雪花鲥鱼出丝网。","李郎载酒过江来，开酒斫鱼醉春晚。","世事反覆如摴蒱，会须一饮空百壶。","淋漓宫袍亦奇士，夜起看对青灯孤。"]},{"t":"江南春次前韵","f":"七言古诗","c":["江南四月春已无，黄酒白酪红樱珠。","吴姬小醉弄弦索，十指春雪如凝酥。","池塘过雨春波涨，风捲杨花落蛛网。","翠眉新妇歌春愁，白马少年归日晚。","游鱼水浅出短蒲，谁家银箭飞金壶。","日长睡起翠阴午，帘外忽过流莺孤。"]},{"t":"送鹤林长老","f":"七言古诗","c":["胡桃一裹茶三角，胡桃壳坚乳肉肥，香茶雀舌细叶奇。","枯肠无物不可用，寄与说法谈禅师。","竹龙吐雪涧水活，茅屋烟吹树云薄。","竹院深沈有客过，碎桃点茶亦不恶。"]},{"t":"寄省郎沙子丁","f":"七言古诗","c":["忆昔射策官明光，序列前后如雁行。","不才瘦马走州县，君已落笔中书堂。","巍巍中书开大府，宰相出入势如虎。","省郎夜直殿烛长，紫薇花间月当午。","有人此际犹未还，正与士卒夜守关。","风吹衣裳露被面，举目只是水与山。","嗟余同时异甘苦，何时逢君倾一语。","典衣为买小红舟，剪烛西窗听秋雨。"]},{"t":"夏夜积雨霁阴云不收病坐南轩月复出","f":"七言古诗","c":["积雨已敛云不明，淡月忽出户牖晴。","幽人开窗看月色，投入怀抱亦有情。","数宵相连尔何在，应驾老蟾出东海。","今宵见尔不得眠，未脱人间女儿态。","爱渠中夜雪满庭，照出饮颗山脰形。","何人此际步微影，玉堂珂佩风泠泠。"]},{"t":"连夜雨晴","f":"七言律诗","c":["石榴花红细雨白，江南四月天气凉。","须臾云散忽晴色，满院花树生幽香。","幽人抱病无可语，日出南窗看晴雨。","小儿造化多戏人，世上俗子徒劳神。"]},{"t":"题郭元二公画壁","f":"七言古诗","c":["两山出没如虎头，争奇角怪不肯休。","一山如龙入云去，一山化作长江流。","崚嶒相雄不相下，欲向人间索高价。","尘中有客语如狂，龙者可先江者亚。","一笑上马归醉眠，曲生使我多妄言。","酒醒忽记夜来语，先者姓郭亚者元。"]},{"t":"次韵休上人见寄","f":"七言律诗","c":["山深树密鸣鸦肥，山人得句多清奇。","深沈竹院白日静，焚香自礼天人师。","门前雨过岩花活，凉风萧萧袖衣薄。","狂邻卧病在江城，怀抱思君空作恶。"]},{"t":"复次前韵东龙江上人","f":"七言律诗","c":["山中酒熟黄鸡肥，闭门索句何瑰奇。","何人剥啄急如雨，门前忽见黄冠师。","挥毫落纸龙蛇活，愧我无能才思薄。","欲师更洒杨柳枝，疟鬼床头敢为恶。"]},{"t":"夜坐赠秀才","f":"七言律诗","c":["青原故人贫且穷，燕山野客疲且聋。","拥炉不觉残火白，开窗忽见月明东。","乃知清景不可得，得诗一笑衰颜红。","夜深吹烛且睡去，楼外落雁呼霜风。"]},{"t":"夜坐分韵得此字","f":"七言律诗","c":["逢冬亦欲乡风举，客舍萧条念闾里。","夜寒铁马嘶北风，漏下铜壶冻春水。","床头斗酒复何为，灯下三豪犹在此。","明朝上马气如云，挥剑长歌为君起。"]},{"t":"晓起","f":"七言律诗","c":["乌鸦哑哑霜树晴，纸窗泼眼春雪明。","野人卧病睡方起，官街踏踏闻马行。","矮窗小户坐终日，煮茶绕坐松风生。","明朝呼儿刷骏马，出门一笑青天横。"]},{"t":"赓眠字韵","f":"七言律诗","c":["去年走马寻阳关，五里十里逢烽烟。","孤臣泣血紫塞外，壮士倚剑青云边。","今年卧病在江海，呼儿夜读归来篇。","结茅松壁知何日，饱听一枕松风眠。"]},{"t":"赓覆字韵","f":"七言律诗","c":["朔风吹帐灭前烛，将军夜拥貂裘宿。","玉关飞雪入紫宫，白发孤臣守金屋。","近思往事良可悲，世事樗蒲多反覆。","古来宫殿说咸阳，落日猿啼挂枯木。"]},{"t":"送陈衡之之金陵","f":"七言古诗","c":["买舟上溯金陵道，寒江水落波浪小。","片帆遥挂蒋山青，空城渐觉秦淮晓。","白门美酒满城春，吴姬唤客客不行。","楼中子弟皆年少，玉奴送酒吹鸾笙。","陈郎不听黄金缕，朝之东吴暮西楚。","半生落魄一布袍，感慨长歌吊千古。","六朝遗迹生暮烟，故宫衰草埋花砖。","凤凰台上醉李白，何人知子囊无钱。"]},{"t":"元子游戏竹木","f":"七言律诗","c":["元君磊落谁与同，秃笔一扫俗子空。","萧条瘦竹卧疏雨，槎枒老树悬春风。","野人卧病在京口，见君此画心神融。","何人识此岁寒景，为我进入蓬莱宫。"]},{"t":"送惟英之淮安","f":"七言律诗","c":["江南木落天欲霜，故人别我之淮乡。","野人一月病在床，不能送子河之傍。","殷勤拂子衣上黄，呼子醉酒三百觞。","岁寒归计不可忘，吴门白发遥相望。"]},{"t":"同友人扬子江送客","f":"七言律诗","c":["将军之马骏且雄，葛仙骑之如游龙。","金陵之酒香且冽，葛仙饮之豪兴发。","马上送客扬子津，下马饮客金陵春。","主人上马客已渡，回首江南江北人。"]},{"t":"题江乡秋晚图","f":"七言古诗","c":["沙头潮下秋水枯，云山落日云模糊。","草堂远近路长驱，萧萧行李行人孤。","蹇驴渡桥归思急，村南村北天秋色。","何者相呼鸡犬声，山前山后烟树立。","江风水面吹残莎，打鱼小艇如飞梭。","何人荡桨立船尾，钓者船头腰半驼。","小李将军不可作，粉壁流传愁剥落。","石门守者犹可奇，柱杖敲门索新跋。","京口绿发参军郎，见君此画心即降。","携家便欲上船去，买鱼煮酒扬子江。"]},{"t":"为九江方七高赋","f":"七言古诗","c":["匡庐山中有佳士，读书结屋青云松。","碧窗夜影紫翠动，落日照见香炉峰。","窥灯夜壁山鬼过，采兰东径仙人逢。","危檐堕雪听风竹，古寺隔岭闻烟钟。","每思幽绝动归兴，岁晚落叶迷行踪。","扁舟何日过湖口，分我半壁青芙蓉。"]},{"t":"将至太平驿即兴","f":"七言律诗","c":["上滩泊处无十里，舟人鼓舞家家喜。","到驿欢呼如到家，明日舟行复如此。","驿行传食过年年，何日归种淮南田。","玉堂金马虽云贵，白酒黄鸡不论钱。"]},{"t":"中秋月夜泛舟于金陵石头城","f":"七言古诗","c":["秦淮流水西复东，倒涵天影磨青铜。","飞廉扫空出海月，明珠飞入琉璃宫。","著我扁舟二三友，江上雪槎泛牛斗。","笑语人间两岸灯，进君江上一尊酒。","醉来起舞听浩歌，宛如玉树春风和。","世间乐事古来少，天下月明今夕多。","六代江山自潇洒，潮落潮生石城下。","人生得意当欢游，此月此水年年秋。"]},{"t":"晓上石壁滩","f":"七言古诗","c":["龙溪三月人上船，十里五里滩声喧。","浪花飞雪洒石壁，船尾落月倾金盘。","越儿卧篙头刺水，露重布帆风不起。","近山钟动石楼中，隔水鸡鸣烟树里。","过江日日水与山，诗人得趣如得官。","白云遥在太行北，何日归舟下石滩。"]},{"t":"过临平","f":"七言律诗","c":["昔人五月临平路，汀洲藕花满无数。","此来三月过临平，雪白杨花捲波去。","杨花捲尽藕花开，今人古人俱到来。","欲向山阴寻贺老，酒船到处且徘徊。"]},{"t":"越溪曲","f":"七言古诗","c":["越溪春水清见底，石罅银鱼摇短尾。","船头紫翠动清波，俯看云山溪水里。","谁家越女木兰桡，髻云堕耳溪风高。","采莲日暮露华重，手滴溪水成蒲萄。","盈盈隔水共谁语，家在越溪溪上住。","蛾眉新月破黄昏，双橹如飞剪波去。"]},{"t":"紫溪道中","f":"七言古诗","c":["三月晦日春欲还，深林百鸟鸣间关。","绿云迷合紫溪岭，白雨遥挂乌石山。","山高雨落不到地，万壑千岩洒飞翠。","远人送春千里归，风送蓝舆野花坠。","间关咫尺上青霄，海上三山路不遥。","地僻题诗公事少，芙蓉帐里紫云飘。"]},{"t":"和同年观志能还自武昌咏","f":"七言律诗","c":["短衣匹马走江汉，山川历历何雄哉。","汉阳风紧鼓角动，洞庭水深鸿雁来。","雪消巴蜀浪翻屋，黄鹤矶下声如雷。","是时立马夜呼渡，清江苦竹猿声哀。"]},{"t":"溪行中秋玩月","f":"七言古诗","c":["龙津秋水涵太虚，今夕何夕光景殊。","皓月当镜星贯珠，河汉倒影垂平芜。","微波漾漾风徐徐，新凉拂拂飘裙裾。","阿母今年八十馀，清晨理发云满梳，起居俨重天人如。","有子在官名在儒，奉母禄养南北区。","晨昏不忍离斯须，荆楚燕赵闽粤吴。","今年去官南海隅，北上咫尺天子都。","官船轧轧如安车，阿母坐卧襟怀舒，清晨夜泊不知挐。","母在船上重褥铺，芙蓉映水摇氍毹。","开瓮酒熟浮新蛆，秋园摘果雨剪蔬。","船尾曲突通行厨，家鸡水鸭美且腴，鲤鲫鲜大如江鲈。","奉觞酌酒前拜趋，月波荡酒如浮酥。","子为母寿妇寿姑，阿妹次进偕婿夫。","酌献亦及婢与奴，熙熙春盎无亲疏。","行礼有节俱欢娱，阿母笑语情愉愉，有妇右策儿左扶。","舟人醉饱从欢呼，鼓枻节歌声呜呜。","四山叠翠开画图，溪濑漱石如笙竽。","双壶酒尽村可酤，盘馔狼藉溪可渔。","人生此乐更有无，异乡到处同里闾。","惟期母寿庄椿踰，有子愿效返哺乌。","作诗记实无浮誉，至元丁丑仲秋书。"]},{"t":"黯淡滩歌","f":"曲","c":["长滩乱石如叠齿，前后行船如附蚁。","逆湍冲激若登天，性命斯须薄如纸。","篙者倒挂牵者劳，攀崖仆石如猿猱。","十步欲进九步落，后滩未上前滩遭。","上滩之难难于上绝壁，虽有孟贲难致力。","滩名况复呼黯淡，过客攒眉增叹息。","下滩之舟如箭飞，左旋右折若破围。","欢呼踏浪棹歌去，晴雪洒面风吹衣。","飞流宛转乱石隘，奔走千峰如马快。","贾客思家一夕还，传语滩神明日赛。","下滩之易易如盘走珠，瞬目何可停斯须。","长风破浪快人意，朝可走越暮可吴。","乃知逆顺有如此，逆者悲愁顺者喜。","请君听我《黯淡歌》，顺则流行逆须止。","顺者不必喜，逆者不必愁。","人间逆顺俱偶尔，且得山水从遨游。"]},{"t":"云际感兴","f":"曲","c":["昨日登芝峰，兹晨陟云岭。","俯视城中居，万瓦落深井。","风露洒洒生秋寒，飞泉落涧声潺湲。","笋舆轧轧度修竹，石阑曲曲跻层峦。","层峦绝顶天尺五，我欲排云击天鼓。","九关虎豹不须惊，吐胆开心见天语。","天鼓不可击，天门何日开。","请君听我《紫芝曲》，手招白云归去来。"]},{"t":"百禽歌","f":"曲","c":["汉密将军开大府，门外纷纷客如雨。","繁弦急管耳厌闻，要听山中百禽语。","购求走马东海头，海头百禽声啾啾。","疾飞苦走亦不免，能言有色贻身忧。","将军纵使花作屋，不似山林有真乐。","江南白苧细于丝，紫竹方笼作青幕。","鸾凤在野麟在郊，太平将军胡不招。","箫韶一奏百兽舞，玉帛万国皆来朝。","嗟嗟百鸟何足录，日食将军太仓粟。","色衰身死蝼蚁分，不补将军一脔肉。","个中鹦鹉最能言，不说舆夫行路难。","万山雨暗泥滑滑，不如归去声亦乾。","行不得也哥哥，九关虎豹高嵯峨，行不得也哥哥。"]},{"t":"雨伞","f":"曲","c":["开如轮，合如束，剪纸调膏护秋竹。","日中荷叶影亭亭，雨里芭蕉声簌簌。","晴天却阴雨却晴，二天之说诚分明。","但操大柄常在手，覆尽东西南北行。"]},{"t":"梳头乐府","f":"七言古诗","c":["红绡捲袖摇剑声，摩挲睡眼窥秋菱。","阳台梦断不知处，一片乌云愁欲倾。","一钩新月掀云起，月渐低流麻草地。","玉纤盘转戏龙形，宝钗压定飞鸦翅。","撩春拨晓誇自然，黄金双燕珍珠蝉。","白头老妪低低笑，不觉婆婆二八年。"]},{"t":"灯草","f":"七言古诗","c":["天涯何处无青青，王孙去后䕷芜深。","瑶田手种绿玉发，道是无情却有心。","此心未明人未识，金篦剖腹森如戟。","撮将一缕玉虫儿，散作万家红粟粒。","侯门珠网百面霞，秦楼玉树双头花。","慧灯莫与群迷染，正性何愁欲镜遮。","韩堂风露光微颤，万古圣贤对面面。","但勤挑剔不惮劳，万炬金莲红药院。"]},{"t":"胡桃","f":"七言古诗","c":["武陵仙子裙如血，不肯洞中事幽绝。","东风吹佩嫁西羌，生子棱棱刚似铁。","道逢贾客怀故山，遣儿随客东南还。","铜铃破晓广沙漠，蜡弹缄愁度玉关。","瑶池阿母沈吟久，何物外孙如此丑。","撇归鹦鹉不回头，欲啄无由堪下口。","谁知造化无秋春，人间枯槁中清淳。","请君剖破浑沦看，会见空腔都是仁。"]},{"t":"芒鞋","f":"楚辞体","c":["东家西家买芒屦，南州北州多岐路。","严霜烈日太行坡，斜风猛雨瓜州渡。","南人求利赴北都，北人徇利多南趋。","朝朝迎送名利客，身身消薄非良图。","人负屦，屦负人，草从土生复归土，人兮履兮不知所。"]},{"t":"绣鞋","f":"七言古诗","c":["罗裙习习春风轻，莲花帖帖秋水擎。","双尖不露行复顾，犹恐人窥针线情。","缫云隐映笼新月，花影依稀衬香颊。","彩凤将翔相顾飞，鸳鸯谩语愁丹裂。","落红湿透胭脂腻，半幅凌波剪秋水。","莫教踏破《浣溪沙》，湿重东风抬不起。"]},{"t":"灯蛾来 其一","f":"楚辞体","c":["灯蛾劳，灯蛾劳，粉其面，锦其袍。","绕灯不去千百遭，忽然性命轻鸿毛。","一鸟死，百鸟号，一兽死，百兽嘷。","尔为微物不自觉，往来就死何滔滔。","灯虽灭，灯复多，蛾兮蛾兮奈尔何。"]},{"t":"灯蛾来 其二","f":"曲","c":["灯蛾来，灯蛾来，绕灯不去飞徘徊。","清光红燄午夜开，忽然性命随飞灰。","平生不傍太阳里，何故趋炎来就死。","人生有情皆爱身，何故将身为戏尔。"]},{"t":"飞奴","f":"七言古诗","c":["雌雄相对鸣呜呜，翅翎无异颜色殊。","营叶寄养出人力，安心饮啄还哺雏。","借问何修得如此，世上群禽那可比。","不疑不诈已恋人，自去自来人信已。","晓天空阔风日清，雕笼彩袖相赍擎。","得时可展青云志，回首无忘白屋情。","苍鹰絷紧鹤笼窄，以身误人颖愈力。","吁嗟此鸟得人怜，有性有情非一日。"]},{"t":"长门秋漏","f":"七言古诗","c":["上壶注水水缕明，中壶激箭移银星。","铜龙宛转吐余毒，闷杀长门不寝人。","情云心上如火色，泪涛湿透银蟾白。","三百六旬尚可支，二十五声消不得。","何人夜扣相如扉，千金买赋成何迟。","男儿酒后多情思，此意文君知不知。"]},{"t":"北人上冢","f":"七言古诗","c":["南人城南逢清明，北人望北号哭声。","人生何处问南北，春秋霜露俱含情。","天涯芳草何青青，杜鹃口血花冥冥。","酪浆一壶麦一饭，香火照日藏流萤。","自言家住大河北，闽巅相望六十六。","血气寻寻呼应声，音容皎皎常在目。","虚名薄利非良图，故山松柏号夜狐。","儿身有禄亲不待，亲坟无主儿义辜。","低头再拜襟尽血，行路人情为惨切。","纸灰低拂绿杨风，杯沥浇残沙上月。","人言朔客铁心肠，谁无半饷情惨伤。","游宦既知离别苦，何如拂衣归故乡。"]},{"t":"枯荷","f":"七言律诗","c":["红云一梦何茫茫，绿萦瘦骨擎欲僵。","愁多有魂吊秋水，故池日夜凄新霜。","鸳鸯相顾魂已泣，白鱼起身银尺立。","堂中书客感秋风，一片青衫和泪湿。"]},{"t":"春别","f":"七言古诗","c":["花气压帘愁不扫，细雨粼粼长芳草。","玉钗燕尾剪春寒，坐惜流年镜中老。","东风吹柳人不知，春娇满眼颦双眉。","吴松锦字梦中得，晓来月落闻乌啼。","南园日暖蝴蝶醉，香雾熏人海棠睡。","朱门小立蹴金莲，落红起作离人泪。"]},{"t":"南台月","f":"七言古诗","c":["城南江上逢中秋，城南石梁初截流。","长虹一道贯秋色，中分百里江南州。","残露消尽鱼尾黑，金蛇翻动三江白。","冰轮拥出碧玻瓈，照见钓龙台上客。","台中之客怀古心，黄河太华三登临。","今年携月醉台畔，越水越山为月吟。","无诸城里人如海，无诸故冢埋残霭。","无诸台上草离离，龙去台空三十载。","昔龙已去江悠悠，今龙虽在人未求。","怀珠岂立此台下，要上黄金台上钩。","乾坤四顾渺空阔，诗书亢气行勃勃。","合沙古谶此其时，天下英雄求一决。","南台月照男儿面，岂照男儿心与肝。","燕山买骏金万斛，万里西风一剑寒。"]},{"t":"征妇怨","f":"曲","c":["有柳切勿栽长亭，有女切勿归征人。","长亭杨柳自春色，岁岁年年送行客。","一朝羽檄风吹烟，征人远戍居塞边。","辚辚车马去如箭，锦衾绣枕难留恋。","黄昏寂寞守长门，花落无心理针线。","新愁暗恨人不知，欲语不语颦双眉。","妾身非无泪，有泪空自垂。","云山烟水隔吴越，望君不见心愁绝。","梦魂暗逐蝴蝶飞，觉来羞对窗前月。","窗前月色照人寒，迟迟钟鼓夜未阑。","灯阑有恨花不结，妆台尘惨恨班班。","半生偶得一锦字，道是前年战时苦。","一朝血杵烟薮除，腰间斜挂三珠虎。","妾心自喜还自惊，门前忽闻凯歌声。","锦衣绣服归故里，不思昔日别离情。","别离之情几青草，镜里容颜为君老。","黄金白璧买娇娥，洞房只道新人好。"]},{"t":"春游太真观","f":"七言律诗","c":["东风恼人如著酒，晓莺啼断门前柳。","青山忽然契我怀，飞上玄都弄星斗。","绿云弄雨小立久，几片落花春在手。","辽东白鹤胡不归，松下丹铅老霜臼。"]},{"t":"题二宫人琴壶图","f":"七言古诗","c":["行云留影雪弄香，藕丝织翠芙蓉裳。","春风拂拂兰蕙芳，金殿不锁双鸳鸯。","冰弦素手弹凤凰，玉壶投矢声玎珰。","花落无人春寂寂，侍女空抱琵琶泣。","谁知绝代有佳人，不解倾城与倾国。","笙歌别院留春住，婵娟千古蛾眉妒。","却笑长门闭阿娇，黄金好买相如赋。"]},{"t":"过桐庐","f":"七言古诗","c":["桐庐山水天下清，洪涛拍岸山围城。","桐君已乘丹凤去，世间草木谁知情。","落日摇红鱼尾赤，江上潮回沙嘴立。","三三两两野人家，半住渔村半樵牧。","尽抛章甫求仙灵，松间黄鹤唤不应。","阻风三日看山色，平生惯识枯枝藤。","碧桃海上开多少，几度春风长瑶草。","白云满地不归来，石烂松枯天地老。"]},{"t":"过洪","f":"五言古诗","c":["奔流激长川，百折怒未已。","长年与水争，退尺进才咫。","艰哉力舟子，观可悟至理。"]},{"t":"和韵题石城峭壁","f":"五言律诗","c":["离宫长蓬蒿，画栋落花綵。","翠华不复游，空馀石城在。","马蹄踏云霞，鸟声隔烟霭。","老僧喜客来，山中深似海。"]},{"t":"偕杨善卿丘以敬刘载民游法云寺以色即是空分韵得即字","f":"五言律诗","c":["驾言招提游，系马日之夕。","黍酒浓滴珠，松风暗笼漆。","朝士昼鸣珂，山僧夜飞锡。","凤台锦袍人，可望不可即。"]},{"t":"病中寄即休上人","f":"五言律诗","c":["床头药裹列，门外芳草荣。","庭閒午阴转，睡觉馀香清。","曹吏日三谒，幽鸟时一鸣。","岂不好驰逐，但恐劳吾生。"]},{"t":"经姑苏与张天雨杨廉夫郑明德陈敬初同游虎丘山次东坡旧题韵","f":"五言古诗","c":["孤峰峙平畴，松杉夹飞岭。","古剑池独奇，两壁插天井。","晃疑将军拜，灵泉奔老耿。","深惟著蛟螭，净莫容虬黾。","昔试盘陀锋，斩斲寻尺矿。","兆瘗银凫多，气结金虎猛。","至今王霸业，堪笑未全骋。","何如吾同游，俯仰无少哽。","小吴不满目，坐览三万顷。","风高塔铃语，日昃萝衣冷。","香积饷醍醐，法喜得隽永。","嗟嗟蛾眉仙，尝来弄光景。","踪迹留雪泥，宇宙寄泡影。","九京倘可作，当为折简请。"]},{"t":"白翎雀","f":"曲","c":["凄凄幽雀双白翎，飞飞只傍乌桓城。","平沙无树巢弗营，雌雄为乐相和鸣。","君不见旧日轻盈舞紫燕，鸳鸯锁老昭阳殿。","风暄芍药春可怜，露冷芙蓉秋莫怨。"]},{"t":"凌波曲","f":"七言古诗","c":["吴蚕入茧双鸳绮，绣缕团花金凤尾。","昔时啼艳晓妆慵，满眼春娇扶不起。","昔时解带罗袜松，玉尖微露生春红。","翩翩白练轻舒卷，笋萚初翻宫样软。","三尺春云入手轻，一钩新月凌波浅。","象床舞罢娇无力，雁沙踏破参差迹。","金莲窄小不堪行，独倚东风玉阶立。"]},{"t":"吴姬曲","f":"五言律诗","c":["皎皎红罗幕，高高碧云楼。","娟娟一美人，炯炯露双眸。","郎居柳浦头，妾住鹤沙尾。","好风吹花来，同泛春江水。"]},{"t":"洞房曲和刘致中员外作","f":"七言古诗","c":["峭寒暗袭云蓝绮，鲛帐愔愔夜如水。","美人骨醉红玉软，满眼春酣不忺起。","幽禽关关唤霜曙，金璧屠苏溢香雾。","有生只合老温柔，璧月长教挂璚树。","鸳鸯同心暗中结，满意芳兰暖红雪。","痴云騃雨自年年，不管人间有离别。"]},{"t":"汉宫早春曲","f":"七言古诗","c":["女夷鼓吹招摇东，羲和驭日骑苍龙。","金环宝胜晓翠浓，梅花飞入寿阳宫。","寿阳宫中锁香雾，满面春风吹不去。","鞭却灵鳌驾五山，芙蓉夜暖光阑干。","鸡人一唱晓星起，四野天开春万里。"]},{"t":"新夏曲","f":"七言律诗","c":["红泣香枯怨流水，夜放箨龙千尺尾。","风生宫树晓层层，凉绿一帘收不起。","烟乾宝鸭白昼清，祝融缓辔行且停。","蔷薇花深雾冥冥，碧窗睡起香满肱。"]},{"t":"醉歌行","f":"七言古诗","c":["草生金谷韩信饿，古来不独诗人穷。","今朝有酒且共醉，明日一饮由天公。","红楼弟子年二十，饮酒食肉书不识。","嗟予识字事转多，家口相煎百忧集。","乃知聪明能误身，不如愚鲁全天真。","百年简宪曾何畏，一日礼法能杀人。","贤愚千载同一朽，我为君歌君拍手。","流芳遣兴不必论，且尽樽前一壶酒。"]},{"t":"鬻女谣","f":"七言古诗","c":["扬州袅袅红楼女，玉笋银筝响风雨。","绣衣貂帽白面郎，七宝雕笼呼翠羽。","冷官傲兀苏与黄，提笔鼓吻趋文场。","平生睥睨纨裤习，不入歌舞春风乡。","道逢鬻女弃如土。","惨澹悲风起天宇。","荒村白日逢野狐，破屋黄昏闻啸鬼。","闭门爱惜冰雪肤，春风绣出花六铢。","人誇颜色重金璧，今日饥饿啼长途。","悲啼泪尽黄河乾，县官县官何尔颜。","金带紫衣郡太守，醉饱不问民食艰。","传闻关陕尤可忧，旱荒不独东南州。","枯鱼吐沫泽雁叫，嗷嗷待食何时休。","汉宫有女出天然，青鸟飞下神书传。","芙蓉帐暖春云晓，玉楼梳洗银鱼悬。","承恩又上紫云车，那知鬻女长欷歔。","愿逢昭代民富腴，儿童拍手歌《康衢》。"]},{"t":"练湖曲","f":"七言古诗","c":["练湖七月凉雨通，白水荡荡芙蓉红。","芙蓉红尽早霜下，鸳鸯飞去何匆匆。","茜塘女儿弄轻碧，鸣榔声断无消息。","清波小藻出银鱼，落日吴山秋欲滴。","望湖楼上云茫茫，鸟飞不尽青天长。","丹阳使者坐白日，小吏开罂宫酒香。","倚阑半醉风吹醒，万顷湖光落天影。","挂冠何日老江南，短褐纶巾上渔艇。"]},{"t":"终南进士行和李五峰题马麟画钟馗图","f":"七言古诗","c":["老日无光霹雳死，玉殿咻咻叫阴鬼。","赤脚行天踏龙尾，偷得红莲出秋水。","终南进士发指冠，绿袍束带乌靴宽。","赤口淋漓吞鬼肝，铜声剥剥秋风酸。","大鬼跳梁小鬼哭，猪龙饥嚼黄金屋。","至今怒气犹未消，髯戟参差努双目。"]},{"t":"桃源行题赵仲穆画","f":"七言古诗","c":["长城远筑阿房起，黔首驱除若蝼蚁。","谁知别有小乾坤，藏在桃花白云里。","桃花重重间白云，洞门锁住千年春。","男耕女织作生业，版籍不是秦家民。","桑麻鸡犬村村屋，流水门墙映花竹。","无端渔父绿蓑衣，带得黄尘入幽谷。","主人迎客坐茅堂，共话山中日月长。","但见花开又花落，岂知世上谁兴亡。","明朝渔父归城市，回首云山若千里。","再来何处觅仙踪？","恨满桃花一溪水。"]},{"t":"回风波吊孔明先生","f":"七言古诗","c":["大江东流日夜白，已矣英雄不堪说。","朔风挟雨过江来，犹向矶头溅腥血。","汉家神气四海摇，奸雄贼子相贪饕。","二龙雌雄尚未决，将军战骨如山高。","先生谋略满怀抱，坐视狂尘不为扫。","若非蜀主三顾贤，终只如龙卧南亩。","仰天一出摧奸锋，纶巾羽扇生清风。","许君义气肝胆裂，兵枢尽在掌握中。","赤壁楼船满江夏，伏剑登坛唯叱咤。","忠心耿耿天必从，烈火回风山亦赭。","可怜一炬功未成，将星已坠西南营。","力吹汉水灰未醒，呜呼天命何不平。","伫立矶头盼吴越，感慨令人生白发。","先生虽死遗表存，大义晶晶明日月。"]},{"t":"送王伯循御史赴广东佥宪时仆将回燕京","f":"七言律诗","c":["沙头酒尽惜别离，江波日色浮绣衣。","清溪柳花白荡荡，白下柳树青依依。","秋云双骢岭表去，明月一雁燕南飞。","曲江水发愿相忆，莫遣鲤鱼音信稀。"]},{"t":"高邮阻风","f":"七言古诗","c":["离家十日得顺水，不卸蒲帆一千里。","忽然今日风打头，寸波寸水逆上流。","小儿造物不可测，昨日南风今日北。","黄郎束手篷下眠，尽日閒看顺水船。","顺船得势如马走，相望招呼不回首。","长风破浪我亦曾，顺逆偶尔非人能。"]},{"t":"清明游鹤林寺","f":"七言律诗","c":["青青杨柳啼乳鸦，满山烂开红白花。","小桥流水过古寺，竹篱茅舍通人家。","潮声卷浪落松顶，骑鹤少年酒初醒。","若将何物赏清明，且伴山僧煮新茗。"]},{"t":"题茅山梅石道士卷","f":"七言古诗","c":["华阳洞里罗浮仙，袖携冰雪梅花篇。","玉堂道士字一尺，紫清老人诗四联。","夫何题咏到疏懒，日短天寒岁云晚。","独怜空谷有佳人，翠壁丹厓作屏板。","道人鹤氅颠倒披，芒鞋踏雪夜深归。","莫将铁笛山头吹，只恐石裂梅花飞。"]},{"t":"北上别郑文学","f":"七言律诗","c":["朔风吹散鸿雁群，郎君上马气如云。","绕街鞭影拂河汉，毳袍貂帽文将军。","扶桑日出马上见，金鸡一声天下闻。","青灯细雨坐官舍，遥忆江南郑广文。"]},{"t":"为姑苏陈子平题山居图黄公望作","f":"七言古诗","c":["尘途宦游廿年馀，每逢花月满幽居。","烟萝荦确走麋鹿，云壑窈窕通樵渔。","那如隐君不出户，读尽万卷人间书。","有生穹壤贵自摅，布韦轩冕奚锱铢。","便当买山赋归欤，石田老我扶犁锄。"]},{"t":"扬帆松江甚驶西望吴诸山快而有作","f":"七言古诗","c":["秋风秋水清浮波，片帆送舟如掷梭。","篙师绝叫凫雁起，但见流沫翔盘涡。","汀芦雪舞花婆娑，绿净已消菱与荷。","青山蹀躞奔青骡，倏忽过眼千群多。","放情盍买鲈乡鲈，侑以满酌金叵罗。","醉拍铜斗踏浪歌，江行之乐其如何？"]},{"t":"中秋前二夜步至吴江垂虹桥盥漱湖渚而归倚篷望月清兴翛然因成数语","f":"七言古诗","c":["万顷太湖风浪静，玻瓈倒浸虹蜺影。","瀼瀼露滴金波流，一筇独立秋云冷。","步回长啸倚篷窗，月华正在青霄顶。"]},{"t":"和韵三茆山呈张伯雨外史","f":"七言古诗","c":["碧桃花落蓬莱宫，银屏甲帐围春风。","冰帘卷水玉堂静，白露滴月银床空。","仙人夜酌九霞酒，手握北斗倾尊中。","梧枝落影凤凰语，幽韵仿佛临苍穹。","伐毛洗髓天地老，火鼎夜出芙蓉红。","呼龙洞口种瑶草，采药忽遇松间童。","茆君自骑一虎去，犹闻珂佩声丁东。","武华山人三载别，绿袍赤杖苍髯翁。","淮南江上复相见，落日淡淡天无穷。","明朝稽首渡江去，楚水清浅银河通。"]},{"t":"再泊钓台次鲜于伯机韵","f":"七言律诗","c":["富春山下桐江渡，今古舟车南北路。","敢将一片利名心，重宿高人钓游处。","客星去后无人住，苍山白水还朝暮。","沙鸥也解避红尘，见人飞上沧洲去。"]},{"t":"秋江泛棹琴乐图","f":"楚辞体","c":["抱琴船头为谁鼓，满江秋色荻花浦。","神鱼出听掉尾舞，曲中鸿雁起江浒，帝子降兮木叶下。"]},{"t":"送闻师之五台","f":"五言律诗","c":["闻子初识面，天涯任去留。","西风洞庭树，落日楚淮舟。","岁月棕鞋底，江湖竹杖头。","丹阳才洗钵，又入五台游。"]},{"t":"题北固山无传上人小楼","f":"五言律诗","c":["瓮城春寂寂，石磴草斑斑。","倚杖高低月，登楼远近山。","百年诗句里，三国酒杯间。","自叹黄尘客，来消半日閒。"]},{"t":"送石民瞻过吴江访友","f":"五言律诗","c":["老友吴江去，吴江水尚高。","一樽散鲈脍，四月过樱桃。","矍铄绿玉杖，风流白纻袍。","西窗故人夜，应是动挥毫。"]},{"t":"秋日钟山晓行","f":"五言律诗","c":["楼阁笼云气，苍茫第几峰。","长林万松雨，落日半山钟。","石磴盘空险，僧廊落叶重。","先王曾驻跸，千古说蟠龙。"]},{"t":"宿龙潭寺","f":"五言律诗","c":["倦游借禅榻，客意稍从容。","落日江船鼓，孤灯野寺钟。","竹鸡啼雨过，山臼带云舂。","半夜波涛作，长潭起卧龙。"]},{"t":"寄舍弟天与","f":"五言律诗","c":["鸿雁飞南北，关河隔弟兄。","水通郧子国，舟泊汉阳城。","落木风霜下，高秋鼓角清。","故人如有意，为我道乡情。"]},{"t":"送景南彦上人归江西","f":"五言律诗","c":["登高伤远别，鸿雁几行飞。","万木江头落，一僧船上归。","故山秋嶂远，残日晚钟微。","亦有同袍者，多应候竹扉。"]},{"t":"偕赵逢吉避暑石头城日暮余归逢吉留宿山中次日寄逢吉并长老圭白岩","f":"五言律诗","c":["竹下一僧坐，城头独客还。","星河下平地，风露满空山。","犬吠松林外，灯明石壁间。","故人借禅榻，心共白云閒。"]},{"t":"凤凰台望祭进士郑复初录事","f":"五言律诗","c":["已矣郑录事，功名与愿违。","须翘如插戟，体弱不胜衣。","白日长江去，青山何处归。","崇台三酹酒，目断雁南飞。"]},{"t":"夜宿升龙观","f":"五言律诗","c":["旧日宸游地，朱栏护辇纹。","龙飞九天雨，鹤梦一龛云。","神火丹炉见，仙音客枕闻。","殷勤谢道士，深夜礼茅君。"]},{"t":"访石城白岩上人","f":"五言律诗","c":["石头城上瞑，红叶雨纷纷。","半日不见路，四山都是云。","鱼龙随水上，钟磬隔林闻。","遥想南峰叟，天寒补衲裙。"]},{"t":"同朱舜咨王伯循登金山妙高台","f":"五言律诗","c":["几年无此客，同上妙高台。","落日地中去，长江天际来。","英雄成往事，岁月付衔杯。","无限登临意，舟人莫重催。"]},{"t":"寄御史王伯循","f":"五言律诗","c":["旷达王夫子，才高早避名。","昨离建业水，今住广陵城。","有酒从人饮，无田藉笔耕。","竹西灯火夜，谁识绣衣行。"]},{"t":"九月七日舟次宝应县雨中与天与弟别","f":"五言律诗","c":["解缆不忍发，船头雨湿衣。","汝兄犹是客，吾弟独先归。","行役关河远，虚名骨肉稀。","如何淮上雁，不作一行飞。"]},{"t":"泊舟黄河口登岸试弓","f":"五言律诗","c":["泊舟黄河口，登岸试长弓。","控弦满明月，脱箭出秋风。","旋拂衣上露，仰射天边鸿。","词人多胆气，谁许万夫雄。"]},{"t":"录囚河间还司送宪使韩仲宜调山东","f":"五言律诗","c":["一想分司日，人生类转蓬。","同行三伏尽，此别几时逢。","雪窦泉花白，霜林柿叶红。","山东好风景，少驻莫匆匆。"]},{"t":"立秋日登乌石山和幕府杨子承韵","f":"五言律诗","c":["海国山四围，繁华坐消歇。","楼观沉夕阳，鸿雁下秋色。","水边无丽人，石上多古刻。","感此暮归迟，秋露满山白。"]},{"t":"登乌石山仁王寺横山阁","f":"五言律诗","c":["千尺青莲座，烟霞拥地灵。","山川几緉屐，日月两浮萍。","鸟没天垂海，龙归水在瓶。","深堂说法夜，应有石头听。"]},{"t":"送观志能分得君字志能与仆同榜又同南台从事考满北还","f":"五言律诗","c":["登台曾并辔，射策又同文。","八月中秋别，三年此日分。","风霜下木叶，鸿雁渡江云。","无日不思我，有诗还寄君。"]},{"t":"过采石驿","f":"五言律诗","c":["客路青山外，乡心落照边。","润烟浮野树，凉雨过淮天。","水调谁家笛，江帆何处船。","蛾眉台上月，今夜照孤眠。"]},{"t":"和权上人","f":"五言律诗","c":["故人久不见，怅望思迟留。","白雁寒沙月，黄云老树秋。","风霜侵客鬓，鼓角入边愁。","满目关河兴，登临倦倚楼。"]},{"t":"送李恕可随王宗师入京","f":"五言律诗","c":["借得茅山鹤，乘风飞上天。","江声近九里，客路已三千。","禁阙红云上，家乡碧海边。","待闻金马诏，复见玉堂仙。"]},{"t":"送莫秀才归番阳","f":"五言律诗","c":["番阳秋水落，白下买船还。","远梦惊新雁，归帆识旧湾。","打碑过荐福，携酒看芝山。","却忆曾游处，清溪万柳间。"]},{"t":"寄朱县尹","f":"五言律诗","c":["才入金川境，行行望眼赊。","乱山迷驿路，一水护人家。","地僻民安业，官清县少衙。","江东贤令尹，心地似梅华。"]},{"t":"寄石民瞻","f":"五言律诗","c":["京口石彭泽，诗怀似鹤形。","苍天容老健，白发照江清。","夜鼎薰鸡舌，秋袍织凤翎。","醉扶绿玉杖，应望石头城。"]},{"t":"题旧县驿","f":"五言律诗","c":["高树日停午，斜飞燕子风。","一身千里外，孤馆万山中。","作客辞家久，闻人问岁丰。","村村桑柘柳，羸马厌西东。"]},{"t":"题江东精舍","f":"五言律诗","c":["长日重门静，幽居曲径深。","开樽临沼上，移席就檐阴。","竹乱鸟声散，萍开鱼影沉。","能文李公子，抱膝但长吟。"]},{"t":"题紫薇观冯道士房","f":"五言律诗","c":["卜筑长江上，回峰晚更奇。","山村猿索饭，竹屋鹤听棋。","云护烧丹灶，泉香洗药池。","道人足高兴，不许俗人知。"]},{"t":"正觉寺晚归赠益山长老","f":"五言律诗","c":["粥鱼声已罢，日暮掩柴扉。","送客月在地，出山云满衣。","灯明闻犬吠，松暗见萤飞。","深夜长廊静，多应独自归。"]},{"t":"次崔镇壁间韵","f":"五言律诗","c":["木落岁时晏，黄云欲雪天。","买舟河下客，立马渡头船。","野迥风欺帽，天寒袖裹鞭。","夜眠三鼓后，晓发五更前。"]},{"t":"寄王御史","f":"五言律诗","c":["御史传天语，飞霜到海垠。","浙江潮似雪，闽土腊如春。","孤客见明月，乱山愁远人。","何时动归兴，家有白头亲。"]},{"t":"送管元帅南征 其一","f":"五言律诗","c":["楚帆风一叶，此去几时还。","日暮汉江碧，雨晴湘竹斑。","边声连草木，野色动荆蛮。","决策平徭后，归心北固山。"]},{"t":"送管元帅南征 其二 过淮安畅曾伯都事幽居","f":"五言律诗","c":["万事归来好，淮阴二亩园。","教儿书满架，过客酒盈樽。","野水到门外，渔船系树根。","除书下霄汉，坐席恐难温。"]},{"t":"送管元帅南征 其三","f":"五言律诗","c":["幽居有真趣，何必在山村。","楚竹深藏屋，淮河直到门。","钓丝鱼浪细，书帙燕泥昏。","吟笑坐终日，佳期谁与言。"]},{"t":"过高唐","f":"五言律诗","c":["残雪复残草，凄风吹未消。","王孙去不返，魂魄有谁招？","往事皆如梦，无人问早朝。","荒陵斜照里，松柏晚萧萧。"]},{"t":"送管元帅南征 其五 寄省郎郭天锡","f":"五言律诗","c":["人道省郎好，簿书清昼閒。","惟公不自喜，忽尔要思还。","酒债西湖路，归心北固山。","閒愁且抛却，莫遣鬓毛斑。"]},{"t":"送金德启之句容","f":"五言律诗","c":["元宵能几日，君去独何心。","县市春灯乱，山村夜雪深。","乡情犹越分，诗句尽唐音。","后会逢寒食，晴光满树林。"]},{"t":"赠诉笑隐长老","f":"五言律诗","c":["佛宫天上有，人世见应稀。","客遇钟鸣饭，僧披御赐衣。","青春忘蝶梦，白日说龙飞。","遥忆宸游处，金莲照夜归。"]},{"t":"都下同翰林诸公送御史尚游题紫骝马","f":"五言律诗","c":["御史紫骝马，今朝行且嘶。","远烟芳草露，细雨落花泥。","蹋月饮淮水，随云过汴堤。","遥思乡旆日，晓立听朝鸡。"]},{"t":"钟山遇风雨 其一","f":"五言律诗","c":["城市多骢马，清游有几人。","山灵飞白雨，朝士说红尘。","云起钟楼暝，桃开野寺春。","上人归太晚，谁主复谁宾。"]},{"t":"钟山遇风雨 其二","f":"五言律诗","c":["游乐有深处，岂知行路难。","山风吹马倒，松雨滴花寒。","丘壑篮舆转，花台石磴盘。","吾皇千万寿，曾此驻金銮。"]},{"t":"四美亭饯别时雪大作戏赠赵公子","f":"五言律诗","c":["公子青骢马，追游十里遥。","风头云叶冻，酒面雪花消。","惜别迟回首，何因见舞腰。","君归金帐暖，无限可怜宵。"]},{"t":"送道士良豸冠还楚丘","f":"五言律诗","c":["淮水春帆动，山城积雨馀。","南台去千里，北阙有三书。","白下曾行马，黄河可脍鱼。","庙堂公论在，君去莫踌躇。"]},{"t":"寄习思敬","f":"五言律诗","c":["深冬残雪夜，醉卧玉山楼。","风劲银筝响，花垂绛烛流。","连床无客梦，中酒失乡愁。","岁月如流水，凭高忆旧游。"]},{"t":"寄中台照磨子徵","f":"五言律诗","c":["中台高百尺，幕府得姚郎。","洗面风生雨，鸣珂月照霜。","诗成裁昼锦，酒饮赐天香。","独有无媒者，台城立晚凉。"]},{"t":"病起城东晚步","f":"五言律诗","c":["扶病谁同步，寻幽思不群。","逢僧穿竹去，吹笛隔林闻。","山势浮云合，溪流野水分。","徘徊归晚径，树影月纷纷。"]},{"t":"次韵郭侍御","f":"五言律诗","c":["江左风流在，长怀晋谢安。","传家须教子，畏事即嫌官。","云雾天风险，烟波世路难。","雄心端有望，白发漆纱冠。"]},{"t":"寄士岩台郎","f":"五言律诗","c":["荐士如君子，文章立玉泥。","自登台阙去，不使簿书迷。","薄俸无馀积，长贫有病妻。","长安贵公子，中酒听莺啼。"]},{"t":"送宣古木","f":"五言律诗","c":["铁面小将军，旌旗照海门。","兵机出孙武，胆气走桓温。","社稷剑三尺，乾坤酒一樽。","茫茫霄汉内，此意与谁论。"]},{"t":"过贾似道废宅","f":"五言律诗","c":["贾生亦何者，此地起楼台。","社稷无人物，湖山养祸胎。","前朝亡国恨，遗迹后人哀。","落日空江上，王宫亦草莱。"]},{"t":"途次吴江别高照庵","f":"五言律诗","c":["适意无南北，相逢江海边。","乡关千里外，风雨一灯前。","呼酒吾同醉，论文子独贤。","分襟在今日，握手又何年。"]},{"t":"寄友","f":"五言律诗","c":["紫禁莺花老，京城四月初。","层楼开别酒，小海出银鱼。","度日轻肥马，朝天借蹇驴。","愿言江海上，亦有病相如。"]},{"t":"范佥事幽居","f":"五言律诗","c":["邑外桑麻长，山中笋蕨甜。","儿孙荐时果，燕雀下晴檐。","芳草生含路，杨花飞过帘。","人头似白雪，对客口如钳。"]},{"t":"大别山","f":"五言律诗","c":["落日在平地，苍茫吴楚秋。","人随孤鹤远，天共九江流。","风物吞淮海，楼船下鄂州。","凭高一登眺，不尽古今愁。"]},{"t":"元统乙亥余录囚至沧州坐清风楼","f":"五言律诗","c":["晋代繁华地，如今有此楼。","暮云连海溆，明月满沧州。","归鸟如云过，飞星拂瓦流。","城南秋水尽，寂寞采莲舟。"]},{"t":"山中怀友 其一","f":"五言律诗","c":["远望空山里，天寒夕梦孤。","林昏行魍魉，江晚变䕷芜。","课议难容我，交游重有吾。","论文轻咳唾，问俗到耕锄。"]},{"t":"山中怀友 其二","f":"五言律诗","c":["天府超群彦，脩材复壮腾。","波澜开白昼，羽翼动苍冥。","弱质悲殊调，明时欲独醒。","应怜扬执戟，寂寞太玄经。"]},{"t":"山中怀友 其三","f":"五言律诗","c":["何事虚斋里，犹分苜蓿盘。","高林容偃蹇，众翼避扶抟。","黑夜文星动，青天剑气寒。","终南山正好，那得悔儒官。"]},{"t":"山中怀友 其五","f":"五言律诗","c":["卓荦恒山秀，相逢几抱琴。","五年风雨别，四海弟兄心。","岭外梅花远，山中桂叶深。","定知嵇叔夜，高兴满云林。"]},{"t":"山中怀友 其六","f":"五言律诗","c":["洛社推年久，清村照柿林。","春风何处客，芳草独行深。","遗墨收秦刻，新诗学楚音。","别离无一字，目断白云岑。"]},{"t":"送唐卿御史","f":"五言律诗","c":["去去红尘外，秋光满华嵩。","故乡归衣锦，行路避乘骢。","未觉长安远，真成冀北空。","燕山一枝桂，回首正西风。"]},{"t":"题刘山长雪夜板舆图","f":"五言律诗","c":["板舆行乐处，鹤发尽鬖鬖。","人子谁无母，刘家独有男。","诸孙嬉掌上，阿母度溪南。","玉宇光连夜，颜酡酒半酣。"]},{"t":"宿大横驿","f":"五言律诗","c":["灯火明沙渡，牛羊过水西。","村舂干涧落，野店四山齐。","桂树偏宜月，人家尽向溪。","秋蟾莫相恼，惟听度关鸡。"]},{"t":"溪行中秋望月","f":"五言律诗","c":["去岁南闽客，今年此日还。","中秋八月半，一水万山间。","皓月飞圆镜，回流转曲环。","携家共清赏，何异在乡关。"]},{"t":"游梅仙山和唐人韵 其一","f":"五言律诗","c":["城郭千峰合，仙凡一水分。","颠崖悬鸟道，乱石聚羊群。","苔井分丹水，茶炉煮白云。","肩舆万松岭，有客访梅君。"]},{"t":"游梅仙山和唐人韵 其二","f":"五言律诗","c":["绝顶寻仙迹，寒泉照病容。","栖鸾多种竹，爱鹤莫移松。","丹药人来乞，山粳手自舂。","秋深霜叶满，麋鹿日相逢。"]},{"t":"游梅仙山和唐人韵 其四","f":"五言律诗","c":["洞天何处是，休日漫寻真。","老鹤来迎客，隔松长似人。","茶炉敲火急，丹井汲泉新。","风景秋过半，烟霞晚更亲。"]},{"t":"平川幽居 其一","f":"五言律诗","c":["深隐云林静，何须负郭田。","图书从塞屋，鸡犬亦登仙。","酿酒寻仙术，脩琴借药钱。","閒过武夷洞，来上钓鱼船。"]},{"t":"平川幽居 其二","f":"五言律诗","c":["九曲溪行尽，平川隐者居。","看家留白鹤，度竹借蓝舆。","架上多丹药，床头有古书。","汉廷论封禅，应问马相如。"]},{"t":"次王伯循御史韵","f":"五言律诗","c":["江城连日雪，骑马欲何之。","老树昏鸦集，寒塘落雁迟。","松窗灯下火，竹屋夜深棋。","寄语王公子，幽栖或可期。"]},{"t":"和吴赞府斋中十咏 其一 焦桐","f":"五言律诗","c":["怜尔抱奇质，无香已自焚。","材高初偶得，音古更谁闻。","天海空遗操，冰霜见裂纹。","中官方煮鹤，终得舍夫君。"]},{"t":"和吴赞府斋中十咏 其二 蠹简","f":"五言律诗","c":["六籍灰寒久，名山依旧藏。","漆痕微有字，芸草欲无香。","后死嗟犹及，斯文岂遽亡。","世方珍贝叶，掩卷一凄凉。"]},{"t":"和吴赞府斋中十咏 其三 破砚","f":"五言律诗","c":["巨璞何人凿，磨穿偶至今。","系文虚绿润，雨气共玄阴。","瓦砾开无异，尘埃积转深。","明光几携入，往事复何心。"]},{"t":"和吴赞府斋中十咏 其四 残画","f":"五言律诗","c":["胜境不可得，生绡馀旧图。","丹青初彷佛，尘土半模糊。","蝴蝶飞疑去，波涛折转无。","良工今岂有，为尔一长吁。"]},{"t":"和吴赞府斋中十咏 其五 败裘","f":"五言律诗","c":["袭尔亦已久，风霜两袖穿。","甘从稚子笑，未受故人怜。","雅志逾前古，深期及暮年。","累丝今化尽，念汝独依然。"]},{"t":"和吴赞府斋中十咏 其六 旧剑","f":"五言律诗","c":["忆昔蛟龙剑，提携竟出门。","红尘走马处，白日报人恩。","岁月铜花涩，云烟牛斗昏。","凄然中夜舞，回首暗销魂。"]},{"t":"和吴赞府斋中十咏 其七 尘镜","f":"五言律诗","c":["古镜色如墨，千年独此留。","玉台尘网暗，珠匣土花浮。","莫笑尘埃满，曾令鬼魅愁。","蟠龙今已化，云雨梦悠悠。"]},{"t":"和吴赞府斋中十咏 其八 废檠","f":"五言律诗","c":["不解照珠翠，早同文字盟。","何年中路弃，无复向人明。","宿雨高斋梦，秋吟废馆情。","相看几今夕，及此慨平生。"]},{"t":"和吴赞府斋中十咏 其九 断碑","f":"五言律诗","c":["零落秋风卧，何年破庙碑。","图经愁莫载，耆旧说频移。","野烧龟文失，荒台鸟迹疑。","遥知千载后，拂拭转堪悲。"]},{"t":"和吴赞府斋中十咏 其十 卧钟","f":"五言律诗","c":["龙簴久摧折，深埋奈尔何。","耕民谁睥睨，野衲自摩挲。","雅奏多年歇，铭文几字讹。","斜阳荆棘里，长伴旧铜驼。"]},{"t":"寄志道张令尹","f":"五言律诗","c":["淮南宣化阁，相对石头城。","二月风帆过，满江春浪生。","青山行不断，绿野尽开耕。","令尹张公子，儿童知姓名。"]},{"t":"送人兄弟相别","f":"五言律诗","c":["送兄南浦上，情思两悠悠。","昆弟难为别，江山总是愁。","橹声摇夜月，帆影障寒流。","后夜相思处，嗷嗷鸿雁秋。"]},{"t":"玉山道中","f":"五言律诗","c":["积雨千峰霁，溪流两岸平。","野花多映水，山鸟自呼名。","人语随乡变，官船带月行。","江南数千里，无处不关情。"]},{"t":"道中漫兴 其一","f":"五言律诗","c":["云气千峰暝，溪流水拍桥。","竹溪泥滑滑，榕树雨潇潇。","曲栈钩崖角，垂虹挂岭腰。","山家酒初熟，或事借椰瓢。"]},{"t":"道中漫兴 其二","f":"五言律诗","c":["绿树莺啼尽，山红映碧萝。","一年春事了，四月雨声多。","闽海夏无暑，山田晚种禾。","远人千里别，归思欲如何。"]},{"t":"哭同年进士李竹操经历 其一","f":"五言律诗","c":["进士如公少，何期与死邻。","青山归葬骨，白发未封亲。","已矣官三郡，哀哉子一人。","送君螺水上，呜咽泪沾巾。"]},{"t":"哭同年进士李竹操经历 其二","f":"五言律诗","c":["此去成长别，频将雨泪挥。","空江片帆远，落日乱鸦飞。","白纸招魂葬，青山有梦归。","双亲头似雪，尘暗老莱衣。"]},{"t":"偶题清凉境界","f":"五言律诗","c":["今日清凉境，明朝剑水心。","酒堪消客况，泉可洗尘襟。","佛古荒苔藓，林深繁绿阴。","樵歌山路晚，馀兴付归禽。"]},{"t":"题蜀山驿","f":"五言律诗","c":["荒山孤馆静，老树冻云低。","马识来时路，诗存旧日题。","邮亭一尊酒，客枕五更鸡。","到晓征鞍发，村村雪涨溪。"]},{"t":"宿因胜庄 其一","f":"五言律诗","c":["薄莫雨初作，客愁行路难。","长风吹短发，平地走惊湍。","云气千山暝，松声五月寒。","小窗僧话久，亦学坐蒲团。"]},{"t":"宿因胜庄","f":"五言律诗","c":["竹院亦幽雅，参禅愧未能。","梦回僧枕雨，花落佛龛灯。","风响过墙竹，窗摇挂树藤。","裁诗题素壁，聊尔记吾曾。"]},{"t":"宿龙潭寺","f":"五言律诗","c":["客路青山下，僧庵绿水边。","撞钟惊鸟宿，洗钵动龙眠。","未有林泉趣，先寻粥饭缘。","上人喜留客，夜雨佛灯前。"]},{"t":"次龙潭壁间韵忆新之区谦二台节 其一","f":"五言律诗","c":["故人久不见，怅望思迟留。","客路愁山虎，渔灯散渚鸥。","清歌闻越调，小艇入淮流。","江市虽萧索，人家酒可谋。"]},{"t":"次龙潭壁间韵忆新之区谦二台节 其二","f":"五言律诗","c":["勤劳贤使者，官马未曾閒。","夜醉谁家酒，晓行何处山。","莫云留客住，落日望君还。","相忆寻诗处，波涛汹涌间。"]},{"t":"江馆写事","f":"五言律诗","c":["晚市人烟合，归帆带夕阳。","青山到江尽，白鸟去天长。","越女能淮语，吴姬学楚妆。","栖迟未归客，犹著锦衣裳。"]},{"t":"谢龙江虚白上人雨中见过","f":"五言律诗","c":["山僧入城市，归路晚沈沈。","雨湿缁衣重，灯明黑树深。","泥途信行脚，粥鼓急归心。","应到松窗下，新诗剪烛吟。"]},{"t":"铁塔寺写怀","f":"五言律诗","c":["萧条冶城寺，杖屦日登临。","古木凉风急，空山落叶深。","夜灯明铁塔，秋雨暗松林。","衲子清游处，閒来独自吟。"]},{"t":"漫兴","f":"五言律诗","c":["去岁干戈险，今年蝗旱忧。","关西归战马，海内卖耕牛。","元老知谁在，孤臣为尔愁。","西风吹短发，落日倦登楼。"]},{"t":"贺阴君锡封赠","f":"五言律诗","c":["奕世阴家子，居官迈等伦。","妙年全至孝，馀禄养慈亲。","致敬归荣早，推恩敕署新。","綵衣映萱草，日日北堂春。"]},{"t":"夏日游鹤林寺","f":"五言律诗","c":["病馀乘野兴，来扣了翁房。","竹笋迸出地，花枝垂过墙。","雨声鸣客枕，云气暗僧堂。","归路马啼滑，风吹酒面凉。"]},{"t":"贺丘郡博持敬新修镇江儒学","f":"五言律诗","c":["孔门新壮观，化雨过南徐。","紫殿风鸣铎，青灯夜读书。","杏坛翔彩凤，芹沼跃银鱼。","馆下诸生意，如游小石渠。"]},{"t":"花山寺投壶","f":"五言律诗","c":["落日花山寺，秋风铁瓮城。","野人欢讼简，稚子说官清。","系马岩花落，投壶山鸟惊。","兴阑山下路，相送晚钟鸣。"]},{"t":"次韵答奎章虞阁老伯生见寄","f":"五言律诗","c":["衮职须公称，江波属我閒。","宦情鱼鸟畔，德誉董韩间。","黄阁论思地，金焦放浪山。","尽操舟泛泛，空忆佩珊珊。"]},{"t":"病中书怀二首 其一","f":"五言律诗","c":["半月闭门坐，萧然远俗氛。","病中心似水，门外马如云。","练杵捣寒月，香炉生昼薰。","兴来览明镜，太瘦小参军。"]},{"t":"病中书怀","f":"五言律诗","c":["欲向江湖去，何年理钓蓑。","城山入楼近，邻竹过墙多。","春瓮浮红酒，晴天戏白鹅。","闭门且消病，俗吏莫相过。"]},{"t":"病中寄了上人二首 其一","f":"五言律诗","c":["鹤林四月路，佳景集芳辰。","花落石桥水，鸟啼山树春。","吟归山似画，醉卧草如茵。","衲子清游处，何妨问病人。"]},{"t":"病中寄了上人二首 其二","f":"五言律诗","c":["日长草木茂，古寺乐芳辰。","野衲归时晚，山泉滴夜春。","清吟联石鼎，病酒吐车茵。","不是天涯客，林泉一故人。"]},{"t":"忆鹤林即休翁","f":"五言律诗","c":["城南鹤林寺，幽境脱尘烦。","地僻藤花落，窗虚贝叶翻。","池塘浮野鸭，竹树挂山猿。","病起借禅榻，高眠避市喧。"]},{"t":"登山亭","f":"五言律诗","c":["山上新亭好，红尘不可侵。","雨阶幽草合，风径落花深。","野水浮晴色，平田下夕阴。","城中公子少，日日就登临。"]},{"t":"送人之金陵","f":"五言律诗","c":["之子金陵去，黄梅细雨天。","晚钟近萧寺，野水急吴泉。","枕有思家梦，囊无买酒钱。","凤台动诗兴，落笔授蛮笺。"]},{"t":"题高秋泉诗卷","f":"五言律诗","c":["美矣高夫子，能文武亦全。","横琴弹夜月，洗剑动秋泉。","酒熟春如海，诗閒日似年。","纶巾北窗下，倦可枕书眠。"]},{"t":"野潜堂","f":"五言律诗","c":["高隐有深意，情閒直万金。","溪鱼鲜作鲙，竹笋长成林。","鹤有还巢梦，云无出岫心。","读书风雨夜，灯火野堂深。"]},{"t":"题朱泽民画雪谷晓行","f":"五言律诗","c":["茆店冲寒出，永厓拂曙来。","磴危留虎迹，萝密隐猿哀。","行李一檐重，疏梅几树开。","阳乌在何处，不照雪盈腮。"]},{"t":"秋暮过吴值雨感怀","f":"五言律诗","c":["长啸拂吴钩，篷窗起白鸥。","江山同逆旅，风雨忽穷秋。","乐矣陶潜酒，高哉范蠡舟。","一簪吾有雪，道路尚悠悠。"]},{"t":"道中风雨","f":"五言律诗","c":["野水池塘满，泥涂愁问程。","小车冲雨去，曲路绕山行。","恁地沾衣冷，谁家压酒声。","飘零江海客，汲汲事南征。"]},{"t":"初到闽","f":"五言律诗","c":["旧说榕乡好，来游鬓已丝。","片云山对户，一雨水平墀。","绿袖持蕉叶，丹林压荔枝。","城闉南有市，灯火夜眠迟。"]},{"t":"登金山雄跨亭","f":"七言律诗","c":["朱栏六曲倚高秋，元气茫茫日夜浮。","客去客来天地老，潮生潮落古今愁。","疏钟水国前朝寺，落日海门何处舟。","更拟黄昏尽馀兴，却从灯火望扬州。"]},{"t":"寒夜怀京口韵","f":"七言律诗","c":["帝京久别梦相同，鸿濛佳气凌青空。","石麟铜雀动凉月，玉楼珠箔摇天风。","宫壶龙渴晚漏尽，御街马滑春雪融。","绣衣貂帽少年子，银瓮索酒蒲萄宫。"]},{"t":"马上偶成","f":"七言律诗","c":["秋水芙蓉淡淡妆，平湖昨夜有新霜。","人间女子空自好，马上郎君不暇狂。","十二玉楼空薄命，三千客路尽他乡。","上林白雁无消息，欲向何人寄断肠。"]},{"t":"送管十班监宪除广西宣慰使","f":"七言律诗","c":["持节曾临江汉上，分符又入瘴云间。","花骢一日行千里，金虎三珠照百蛮。","露帐旌旗天接水，星营鼓角月连山。","九重应有平猺诏，日听将军奏凯还。"]},{"t":"偕侍御郭翰卿过钟山大崇禧万寿寺文皇潜邸所建御榻在焉侍御索诗因为赋此","f":"七言律诗","c":["虎踞龙蟠王气多，云深石磴碧嵯峨。","珠峰独占金陵胜，宝地尝经翠辇过。","花草旧曾沾雨露，殿台今已近星河。","登高愿效封人祝，万岁千秋保太和。"]},{"t":"送欣上人笑隐住龙翔寺","f":"七言律诗","c":["江南隐者人不识，一日声名动九重。","地湿厌看天竺雨，月明来听景阳钟。","衲衣香暖留春麝，石钵云寒卧夜龙。","何日相从陪杖屦，秋风江上采芙蓉。"]},{"t":"夜宿池阳石墨驿纳凉溪桥文皇南幸江陵驻跸所也徘徊久之赋诗未就忽雷电晦冥风雨大作急趋驿舍秉烛写东壁时至顺壬申五月","f":"七言律诗","c":["圣明天子南巡日，尚想溪桥洗马时。","雷电神光犹警跸，草茅贱士敢言诗。","山河夜黑鬼神护，雨露春深草木知。","松柏如龙入霄汉，行人谓是万年枝。"]},{"t":"高邮城晓望","f":"七言律诗","c":["城上高楼城下湖，城头画角晓呜呜。","望中灯火明还灭，天际星河淡欲无。","隔水人家暗杨柳，带霜凫雁起菰蒲。","短衣匹马非吾事，拟向烟波觅钓徒。"]},{"t":"凤凰台为御史大夫易释董公同赋","f":"七言律诗","c":["六朝歌舞豪华歇，商女犹能唱《后庭》。","千载江山围故国，几番风雨入空城。","凤凰飞去梧桐老，燕子归来杨柳青。","白面书生空吊古，日陪骢马绣衣行。"]},{"t":"再过钟山大禧万寿寺有感","f":"七言律诗","c":["紫翠烟霞出上方，游人登览忆先皇。","石阑空见岩花落，翠辇不来山路荒。","此日风云消王气，旧时草木染天香。","夜深行殿无人到，应有山灵护御床。"]},{"t":"和马伯庸除南台中丞时仆驰驿远迓至京复改徽政以诗赠别","f":"七言律诗","c":["江南驿使路遥遥，远赴龙门望海潮。","桂殿且留修月斧，银河未许度星轺。","隔花立马听更漏，带月鸣珂趁早朝。","祇恐淮南春色动，万竿烟雨绿相招。"]},{"t":"三益堂芙蓉","f":"七言律诗","c":["斑帘十二卷轻碧，秋水芙蓉隔画阑。","绣扇摇风霞透影，锦袍弄月夜生寒。","湘魂翠袖留江浦，仙掌红云湿露盘。","只恐淮南霜信早，绛纱笼烛夜深看。"]},{"t":"次学士卢疏斋题赠句容唐别驾","f":"七言律诗","c":["疏斋落落谪仙才，句曲名山数往来。","日读茶经医酒病，春从邻舍觅花栽。","昔年奏对含鸡舌，今日登临独凤台。","赖有閒居唐别驾，寻诗猿鹤莫惊猜。"]},{"t":"宿曲阳仙馆","f":"七言律诗","c":["天际三峰横紫烟，山前山后尽芝田。","楼台木末疑无路，鸡犬云中半是仙。","白石经年皆化玉，青松尽日只闻泉。","曲林三馆幽深处，一夜重楼听雨眠。"]},{"t":"题元符宫东秀轩又名日观","f":"七言律诗","c":["茅君山下种玉田，道士辟为东秀轩。","五色晓霞开日观，万株秋露滴云根。","竹园笋出穿龙角，松树年深长鹤孙。","一道天河横屋过，奎光垂地夜当门。"]},{"t":"元统乙亥岁集贤学士济尔噶台奉旨代祀真定路玉华宫睿宗仁圣景襄皇帝影堂仆备监礼","f":"七言律诗","c":["大帝天香出内宫，孝思与世总无穷。","百年礼乐行三献，一派箫韶起半空。","使者领班云气里，女仙摇佩月明中。","小臣监礼陪清列，两袖葵花映烛红。"]},{"t":"登镇阳龙兴寺阁观铜铸观音像","f":"七言律诗","c":["眼中楼观见应稀，铁凤栖檐势欲飞。","天半宝花飘阁道，月中桂子落僧衣。","高擎玉露仙人掌，上碍银河织女机。","全赵堂堂遗物在，山川良是昔人非。"]},{"t":"寄进士野仙不花仲实除侍仪通事舍人","f":"七言律诗","c":["舍人楚楚好容仪，玉立清朝白玉墀。","紫袖窄衫花萼绕，黄金小带荔枝垂。","綵旗拂柳春班卷，宫漏穿花午仗移。","朝罢太平无事日，芙蓉叶上好题诗。"]},{"t":"仆官燕南照磨大名文济王重赐綵二端赋诗以谢","f":"七言律诗","c":["夜梦东南五色云，晓闻使者已临门。","府中重遣年前赐，幕下多承望外恩。","芝草暖霞浮露綵，藕丝秋水织霜痕。","何因得侍西园宴，宫锦淋漓献寿樽。"]},{"t":"寄文济王府教授郭尚之","f":"七言律诗","c":["闻君客食贤王府，剪地芙蓉赐坐温。","不爱时名题雁塔，愿将苦学授龙孙。","中官送酒银瓶小，前席谈经绛帐尊。","却笑冯驩事干谒，无鱼弹铗尚侯门。"]},{"t":"元统乙亥余除闽宪知事未行立春十日参政许可用惠茶赋此以谢","f":"七言律诗","c":["春到人间才十日，东风先过玉川家。","紫薇书寄斜封印，黄阁香分上赐茶。","秋露有声浮薤叶，夜窗无梦到梅花。","清风两腋归何处？","直上三山看海霞。"]},{"t":"别江州总管真定王克绍","f":"七言律诗","c":["我识文章王太守，不知几日上浔阳。","琵琶亭前好明月，香炉峰头多夜光。","吟诗写字午衙静，打鼓劝农春社忙。","万一公馀颇相忆，寄诗应到荔枝乡。"]},{"t":"再过界首驿","f":"七言律诗","c":["二月好风吹渡淮，满湖春水绿如苔。","官船到岸人多识，楚馆题诗客又来。","近水人家杨柳暗，禁烟时节杏花开。","一官迢递三山远，海上星槎几日回。"]},{"t":"姑苏台奉别侍御王继学","f":"七言律诗","c":["骢马霜台好使君，碧罗衫色透春云。","帘垂绶带虾须细，烛剪金钗燕尾分。","四海名高瞻北斗，五弦调古和《南薰》。","姑苏台下人无数，争看门生拜主文。"]},{"t":"赠陈众仲","f":"七言律诗","c":["江南少识陈众仲，阙下才名北斗齐。","直阁每从花底过，挥毫曾向御前题。","观鱼小海凤新浴，立马上林莺乱啼。","今日西湖湖上路，独骑款段踏春泥。"]},{"t":"吴山女道士","f":"七言律诗","c":["不见辽东丁令威，旧游城郭昔人非。","镜中春去青鸾老，华表山空白鹤归。","石竹泪乾斑雨在，玉箫声断綵云飞。","洞门花落无人扫，独坐苍苔补道衣。"]},{"t":"过鹅湖寺","f":"七言律诗","c":["十里苍松对寺门，四围翠滴露纷纷。","湖心水满通银汉，山顶鹅飞化白云。","玉井芙蓉天上露，剑池雪浪月中闻。","石床茶灶如招隐，还许閒人一半分。"]},{"t":"题鸦浴池","f":"七言律诗","c":["天池霹雳斧斤馀，天风万劫吹不枯。","白云石面化青雨，落日海眼翻金乌。","银河灵鹊渡夜影，月窟老兔时濡须。","太平海上锦袍客，跨鹤来看浴凤雏。"]},{"t":"赠仁王讲师达上人","f":"七言律诗","c":["香山居士美如玉，亭亭秋水开芙蓉。","承恩长揖紫宸殿，飞锡遥挂乌石峰。","散花天女绕经阁，出海神龙闻讲钟。","攒眉入社笑陶令，载酒三生石上逢。"]},{"t":"石夫人","f":"七言律诗","c":["危危独立向江滨，四伴无人水作邻。","绿鬓懒梳千载髻，朱颜不改万年春。","雪为腻粉凭风傅，霞作胭脂仗日匀。","莫道脸前无宝镜，一轮明月照夫人。"]},{"t":"安分","f":"七言律诗","c":["心求安乐少思钱，无辱无荣本自然。","春日赏花惟贳酒，冬天踏雪旋添绵。","频将棋局消长日，时爇香薰篆细烟。","万事皆由天理顺，何愁衣禄不周全。"]},{"t":"丁卯及第谢恩奉天门","f":"七言律诗","c":["禁柳青青白玉桥，无端春色上宫袍。","卿云五彩中天见，圣泽千年此日遭。","虎榜姓名书綵纸，羽林冠盖竖旌旄。","朝回龙尾频回首，玉漏花深紫殿高。"]},{"t":"赐恩荣宴","f":"七言律诗","c":["内侍传宣下玉京，四方多士被恩荣。","宫花压帽金牌重，舞妓当筵翠袖轻。","银瓮春分官寺酒，玉杯香赐御厨羹。","小臣涓滴皆君赐，惟有丹心答圣明。"]},{"t":"同克明曹生清明日登北固山和韵","f":"七言律诗","c":["三月二日风日暖，千家万家桃李开。","少年白日骑马去，满城红雨拂面来。","共君且饮酒一斗，处世不必歌七哀。","孙刘事业果何在，百年断石生莓苔。"]},{"t":"寄呈江东廉使王继学","f":"七言律诗","c":["瓜步遥闻鼓角声，淮船夜过石头城。","当年岭海家何在，此日江湖梦亦清。","紫塞秋风初度雁，玉堂夜月旧闻莺。","秪应王谢风流在，卧治山东足令名。"]},{"t":"金陵道中","f":"七言律诗","c":["烟树云林半有无，野人行李更萧疏。","堠长堠短逢官马，山北山南闻鹧鸪。","万里关河成传舍，五更风雨忆呼卢。","寂寥一点寒灯底，酒熟邻家许夜酤。"]},{"t":"述怀","f":"七言律诗","c":["客程去住与身违，误掷渔竿下钓矶。","好客不来门户俗，远亲相弃信音稀。","青春背我堂堂去，黄叶无情片片飞。","遥望家山搔短发，故园酒熟蟹螯肥。"]},{"t":"句曲赠清玄道士陈玉泉朝京还山复拜广陵观","f":"七言律诗","c":["清玄道士骑黄鹤，曾向春班趁早朝。","香动螭头云气暗，路回龙尾佩声遥。","还山去采泉中玉，洗耳终亡树上瓢。","闻说淮南招桂隐，渡江明月听吹箫。"]},{"t":"望金陵","f":"七言律诗","c":["行人雨霁金陵去，萧寺钟声又远听。","五月潮声方汹涌，六朝文物已凋零。","春风玉树留歌韵，暮日青山立画屏。","干古兴亡堪一笑，买花载酒赏心亭。"]},{"t":"季子庙","f":"七言律诗","c":["公子不来春草绿，故宫禾黍亦离离。","沸原尚有千年井，古篆犹存十字碑。","去国一身轻似叶，归田两鬓细如丝。","李家兄弟一朝暮，羞见延陵季子祠。"]},{"t":"题扬州驿","f":"七言律诗","c":["银烛高烧照不眠，呼儿饮马吸清泉。","寒砧万户月如水，塞雁一声霜满天。","《金缕》款歌来枕上，银瓶索酒到亭前。","明朝走马燕山道，赢得红楼说少年。"]},{"t":"雪米","f":"七言律诗","c":["万斛珠玑泻大荒，六丁谁为发天仓。","云孙捧出南箕簸，月姊春来北斗量。","狼戾也知逢稔岁，贮储尤不济饥肠。","风流灞上寻诗客，千古无人说秕糠。"]},{"t":"移梅","f":"七言律诗","c":["几夜幽香恼梦魂，殷勤来倩陇头人。","凿开东阁窗前地，分得西湖雪里春。","瘦影番来新体态，疏枝犹带旧精神。","今朝伴我清吟处，不许诗怀更有尘。"]},{"t":"都门元日","f":"七言律诗","c":["元日都门瑞气新，层层冠盖羽林军。","云边鹄立千官晓，天上龙飞万国春。","宫殿日高腾紫霭，箫韶风细入青云。","太平天子恩如海，亦遣椒觞到小臣。"]},{"t":"寄马昂夫总管","f":"七言律诗","c":["衢州太守文章伯，酒渴时敲玉井冰。","径造竹床忘是客，横拖藜杖去寻僧。","人传绝句工唐体，自恐生前是薛能。","日暮江东怀李白，凤凰台上几回登。"]},{"t":"送僧归庐山","f":"七言律诗","c":["扬子江头木叶风，上人归兴白云重。","净瓶满贮蓬莱水，客舫遥听精舍钟。","到家自笑门前鹤，洗钵不惊潭底龙。","珍重匡庐山畔路，逢人应问旧栽松。"]},{"t":"次张举韵题皖山金氏绣野亭","f":"七言律诗","c":["南冠犹有旧风流，说看舒州处处幽。","最喜园林动花竹，不妨城郭带林丘。","一樽浊酒青山暮，三径晚香黄菊秋。","未识孤高金处士，杖藜应许约同游。"]},{"t":"赠莫州同年县尹米思泰","f":"七言律诗","c":["倦客重来忆去年，荒城斜日淡炊烟。","民居星散无官讼，里巷秋深尽水田。","禾稼半生城郭里，槐花乱落县门前。","路傍父老头如雪，共道文章令尹贤。"]},{"t":"送刘照磨之桂林","f":"七言律诗","c":["一官未厌马蹄遥，要使南荒识凤毛。","幕府红莲开白昼，辕门碧草映青袍。","牙旗晓湿蛮烟重，羽箭宵鸣岭月高。","努力平猺当第一，剖符悬印赐勋劳。"]},{"t":"和马昂夫赏心亭怀古","f":"七言律诗","c":["景阳宫井绿芜深，空有杨花暗御林。","一自朝云归寺里，几回明月到楼心。","陈台露冷蛩声苦，楚水波寒雁影沈。","白发词臣多感慨，长歌对酒向谁斟。"]},{"t":"和马昂夫登楼有感","f":"七言律诗","c":["倚遍阑干忆往年，南朝民物已萧然。","空遗故国山如画，依旧长江浪拍天。","市井笙歌今渐少，御街灯火夜相连。","青青门外秦淮柳，几度飞花送客船。"]},{"t":"上赵凉国","f":"七言律诗","c":["笑辞天上九鼎贵，来种江东二顷田。","屈指已无元老在，全身惟有国公贤。","新亭不必悲王道，彭泽何曾改晋年。","如此声名半天下，人间野史亦堪传。"]},{"t":"赠学古澹上人","f":"七言律诗","c":["瘦影相随九节筇，同袍无处觅行踪。","远看天目山中寺，来听石头城里钟。","洗钵泉通陈井水，开窗云度蒋陵松。","忽闻一夜猿啼月，却忆飞来最上峰。"]},{"t":"送约上人归宜兴湖洑寺","f":"七言律诗","c":["云水上人归兴忙，棕鞋蒲扇葛衣凉。","过湖就得乡船便，入寺行穿茶树香。","晓趁钟声持木钵，夜随灯影认禅床。","定回却忆潜龙地，曾住西廊第几房。"]},{"t":"再游崇禧寺","f":"七言律诗","c":["野人再到城南寺，临水芙蓉次第开。","新酒瓦盆青映竹，旧题石壁绿封苔。","夕阳半岭牛羊下，秋色满天鸿雁来。","独有新亭天地阔，不须挥泪洒蒿莱。"]},{"t":"游清溪道院","f":"七言律诗","c":["旧游淮水东边月，高照升龙道士家。","丹灶火光穿树木，石坛幡影走龙蛇。","虾须卷夜收云气，仙掌擎秋泻露华。","天外松风吹鹤梦，珊珊珂佩隔青霞。"]},{"t":"题李遵道画竹木图","f":"七言律诗","c":["风流未识生前面，翰墨空遗死后名。","凤尾拂云秋有影，龙头出水夜无声。","半生清节江南梦，万里灵槎海上行。","应逐锦袍弄明月，倒骑赤鲤对吹笙。"]},{"t":"送张都事南台","f":"七言律诗","c":["幕府三年冰雪里，清溪秋水照芙蕖。","早霜两鬓厌为客，明月满船空载书。","忆惜中台簪豸角，曾封直谏动鸾舆。","而今江海多归思，白发慈亲暮倚闾。"]},{"t":"送南台察院史马允中台","f":"七言律诗","c":["御史台郎书上考，彩衣归慰日相亲。","风烟驿路江天晓，灯火船窗雪夜春。","幕府十年心似水，京华三月马如尘。","此时应有寻君处，日到松厅莫厌频。"]},{"t":"和张仲举清溪夜行","f":"七言律诗","c":["溪上人家溪树青，溪行野客思冥冥。","月光荡水游鱼出，屐齿穿沙宿雁醒。","蔓草古陵神道没，枫林夜火鬼祠灵。","《后庭》遗曲依然在，商女能歌不忍听。"]},{"t":"九日","f":"七言律诗","c":["北固山前逢九日，小凉天气入青袍。","湘江水落玄霜下，吴地秋深白雁高。","落帽看花怜我辈，呼鹰戏马忆儿曹。","孙刘事业今何在，斗酒聊书太白豪。"]},{"t":"休上人见访","f":"七言律诗","c":["京口参军门不出，鹤林老子轿相过。","主人病久来车少，门巷秋深落叶多。","金帐人趋新党项，尘寰谁识病维摩。","如何与子谈诗夜，腊雪空林落冻柯。"]},{"t":"李清庵见过","f":"七言律诗","c":["采石仙人携酒来，病怀今日为君开。","何人更有八十岁，与子须倾三百杯。","《金缕》歌残银烛短，锦袍醉倒玉山颓。","明朝酒醒重相见，杖屦江村看腊梅。"]},{"t":"送友人进柑入京","f":"七言律诗","c":["绿发参军门不出，黄岩老叟肯相过。","九重玉食常年进，千里金柑细马驮。","绿水青山南郡远，毳袍貂帽北风多。","同年若问侬消息，为说愁来无奈何。"]},{"t":"送友人之广西","f":"七言律诗","c":["昂昂野鹤在鸡群，客里相逢又见分。","酒醒玉箫江左月，梦回白马广西云。","洞庭秋水连天去，建业寒潮入夜闻。","君过此时应忆我，我逢此际却思君。"]},{"t":"四时宫词 其一","f":"七言律诗","c":["御沟涨暖绿潺潺，风细时闻响佩环。","芳草宫门金锁闭，柳花帘幕玉钩閒。","梦回绣枕听黄鸟，困倚雕阑看白鹇。","落尽海棠天不管，修眉惭恨锁春山。"]},{"t":"四时宫词 其二","f":"七言律诗","c":["日长缝就缕金衣，高柳风轻拂翠眉。","閒倚小楼题画扇，但闻别院笑弹棋。","主家恩爱有时尽，贱妾心情无限思。","又向晚凉新浴罢，琵琶自拨断肠词。"]},{"t":"四时宫词 其三","f":"七言律诗","c":["宫沟水浅不通潮，凉露瑶街湿翠翘。","天晚不闻青玉佩，月明偷弄紫云箫。","正宫夜半羊车过，别院秋深鹤驾遥。","却把閒情望牛女，银河乌鹊早成桥。"]},{"t":"京城春暮","f":"七言律诗","c":["三月京城飞柳花，燕姬白马小红车。","旌旗日暖将军府，弦管春深宰相家。","小海银鱼吹白浪，层楼珠酒出红霞。","蹇驴破帽杜陵客，献赋归来日未斜。"]},{"t":"京城访揭曼硕秘书","f":"七言律诗","c":["城中车马多如云，载酒问字无一人。","碧桃花开光艳艳，砚池水暖波粼粼。","先生楷书白昼静，家童画纸乌丝匀。","落花满地送客去，十年不见江南春。"]},{"t":"采石怀李白","f":"七言律诗","c":["梦断金鸡万里天，醉挥秃笔扫鸾笺。","锦袍日进酒一斗，采石江空月满船。","金马重门天似海，青山荒冢夜如年。","秪应风骨蛾眉妒，不作天仙作水仙。"]},{"t":"秋日登石头城","f":"七言律诗","c":["登临未惜马蹄遥，古寺秋高万木彫。","废馆尚传陈后主，断碑犹载晋南朝。","年深辇路埋花径，雨坏山墙出翠翘。","六代兴亡在何许，石头依旧打寒潮。"]},{"t":"题舒真人北山楼观图","f":"七言律诗","c":["瑶花琪树间霓旌，十二朱楼接五城。","台上吹箫秦弄玉，云边度曲许飞璚。","光流汉殿青鸾舞，霞拥函关紫气明。","方丈蓬莱俱咫尺，不须东望问长生。"]},{"t":"次韵送虞伯生入蜀代祀","f":"七言律诗","c":["芙蓉仙掌座中低，后土宵光手可齐。","阁道蹴云衣有瓣，蜀天漏雨石无泥。","岐山过马应闻凤，陈宝停辀莫信鸡。","扬我大邦文物盛，题诗应近草堂西。"]},{"t":"寄句曲外史","f":"七言律诗","c":["霞佩翩翩出洞天，当时彷佛见臞仙。","几年海上张公子，今日山中葛稚川。","沧海尘飞丹已熟，玉堂人去榻空县。","林间载酒来相觅，乞写丹经与世传。"]},{"t":"寄中台王本中","f":"七言律诗","c":["王郎楚楚金闺彦，五凤楼前看斗鸡。","花外漏传银箭午，日边班退紫宫西。","吟诗月白倾瑶露，归马春红踏锦泥。","应念栖迟江海客，破窗灯火雨凄凄。"]},{"t":"次韵寄茅山张伯雨 其一","f":"七言律诗","c":["句曲道人门不出，几时杖屦接殷勤。","春晴洗药分泉去，午睡烹茶隔竹闻。","山脚客行惊犬吠，树皮苔老结龙文。","三层台上月如水，半夜吹箫入紫云。"]},{"t":"次韵寄茅山张伯雨 其二","f":"七言律诗","c":["天际三峰翠色浮，更于何处觅瀛洲。","也知方外神仙好，不识人间儿女愁。","白犬吠人惊夜鬼，珠帘捲雨入明楼。","挂冠何日寻高隐，竹杖芒鞋绝顶游。"]},{"t":"过孙虎臣园","f":"七言律诗","c":["洛阳花木昔如霞，冷雨酸风尽委沙。","金谷东风只芳草，绿窗晴日自杨花。","莺儿老去空台树，燕子归来无主家。","回首繁华歌舞地，景阳宫沼夜闻蛙。"]},{"t":"同吴郎饮道院","f":"七言律诗","c":["三月江南飞柳花，松间童子脸如霞。","旋呼采石仙人酒，来醉山阴道士家。","西日下城人影散，东风吹马帽檐斜。","吴郎今夜瓜州渡，回首江头月满沙。"]},{"t":"病中夜坐","f":"七言律诗","c":["江树花开午夜春，绿香吹散隔帘云。","吟诗思苦家人骂，捣药声高邻舍闻。","惟有工程餐白术，亦无心事对红裙。","消愁且喜楼西畔，明月一池蛙乱喧。"]},{"t":"观驾春游 其一","f":"七言律诗","c":["箫韶风细入清虚，日暖旌旗卷复舒。","双凤晓开金羽箭，六龙春驾紫云车。","将军斜插黄金虎，丞相低垂锦带鱼。","遥想金盘珠露滑，江南渴杀病相如。"]},{"t":"观驾春游 其二","f":"七言律诗","c":["日奏云间紫凤韶，春随天上柘黄袍。","仗前虎将千金斧，马上鹰儿五色绦。","猎士开弓黄犬壮，宫官击鼓紫驼高。","侍游亦有中书令，七宝雕笼看绿毛。"]},{"t":"送僧还江西","f":"七言律诗","c":["病僧岁晚归何处，落日空山白雁声。","洗钵欲辞扬子水，买鱼多上豫章城。","云深庐阜青松老，风细鄱湖白浪生。","更展诸方图画看，高低远近互纵横。"]},{"t":"寒夜即事","f":"七言律诗","c":["枕边漏水催更箭，城下霜风动捲芦。","寒夜绣帘人送酒，小楼银烛客提壶。","自怜今日江南梦，犹认当年柳下垆。","又拟上年灯火夜，扁舟载酒下姑苏。"]},{"t":"招隐首山分韵得生字","f":"七言律诗","c":["龙飞凤隐知何处，今日空馀黄鹄名。","千古江山围故国，五更风雨入空城。","猿啼洞府暮云合，花落祠堂春草生。","何日结茅向青壁，抱琴坐石听泉声。"]},{"t":"殿试谢恩次韵","f":"七言律诗","c":["御柳青青白玉桥，无端春色暖宫袍。","蓬莱云气红楼近，阊阖天风紫殿飘。","士子拜恩文物盛，舍人赞礼旺声高。","小臣虽出江湖远，马上听莺梦早朝。"]},{"t":"游竹林寺","f":"七言律诗","c":["野人一过竹林寺，无数竹枝生白烟。","江近玉龙埋碧草，月明黄鹤下芝田。","树衔宿雨啼山鹧，花落春风老杜鹃。","何日来分云半榻，故人不用买山钱。"]},{"t":"次韵送人还茅山","f":"七言律诗","c":["八十华阳洞里仙，朝回剑履御阶前。","丹砂出鼎无馀火，白发看经有太玄。","三月云江春似海，九重金阙日如年。","归来依旧茅山月，道德明言说五千。"]},{"t":"酌桂芳庭","f":"七言律诗","c":["桂枝秋露洗银瓶，醉里题诗记答曾。","接竹池通丹井水，隔松人诵蕊珠经。","茶香石鼎烧红叶，酒渴冰盘破紫菱。","一带钟山青未了，碧窗云气护龙亭。"]},{"t":"贺内台治书奉敕树碑先茔","f":"七言律诗","c":["獬豸峨冠侍紫皇，绣衣玉斧破炎荒。","江东丘垄云山好，天上文章雨露香。","句曲洞中天紫翠，凤凰台上月清光。","忠臣孝子千年意，永刻丰碑不可忘。"]},{"t":"游长干寺","f":"七言律诗","c":["秦淮河上长干寺，松柏萧萧云日鲜。","故堠尚存铜雀瓦，断碑犹载晋朝年。","石坛幡影风吹动，辇路砖花雨滴穿。","惟有长廊旧时月，几回缺后几回圆。"]},{"t":"次韵 其一","f":"七言律诗","c":["之子慇勤何处来，清谈煮茗不论杯。","五更门外过风雨，四月街头买杏梅。","喜客有情窗动竹，吟诗无兴砚生苔。","君家白酒何时熟，病起应须去不回。"]},{"t":"次韵 其二","f":"七言律诗","c":["池塘过雨水生漪，倚槛观鱼自悦怡。","长日似添诗有趣，故人因为病相知。","凉风忽过帘钩动，午箭初长刻漏移。","何处榴花照人面，隔墙红过两三枝。"]},{"t":"次韵","f":"七言律诗","c":["江南三月踏残芳，白苧衣轻树影凉。","曲巷银灯先马去，谁家翠袖隔帘香。","细歌《金缕》鸣牙板，新酒檀槽出玉浆。","卧病日长思往事，买舟乘兴过沧浪。"]},{"t":"广平马怀素寓居姑苏雨中见过","f":"七言律诗","c":["湖海相逢若弟昆，丈夫志气共谁论。","江山如此苦多梦，风雨萧然忽过门。","为客尚嫌吴俗薄，哦诗久别楚音存。","明朝北固楼中去，共听江声倒百樽。"]},{"t":"送友之金陵","f":"七言律诗","c":["江城晓雨开新霁，行李萧萧去远坰。","千古风流鬓毛白，六朝山色马头青。","秦淮月出潮初上，萧寺钟鸣酒半醒。","莫唱当时《后庭》曲，殿台芳草夜飞萤。"]},{"t":"寄良常伯雨","f":"七言律诗","c":["良常道士人不识，终岁看山不下楼。","隔屋书香开酒瓮，捲帘树色入茶瓯。","云深石磴麋鹿下，月黑花崖猿鹤愁。","安得飘然出尘鞅，长年送别若为游。"]},{"t":"奉次参政继学王先生海南还桂林道中韵","f":"七言律诗","c":["空山幽响落林柯，蛮犬呶呶吠碧萝。","大庾岭头三月尽，郁孤台下几人过。","槟榔雨过鸠鸣急，薜荔云深猿啸多。","几度裁诗寄相忆，江南如此奈愁何。"]},{"t":"无题","f":"七言律诗","c":["为客三年海上洲，故乡何处瘴云稠。","数千里外蛮人域，十八滩头过客舟。","时有山禽呼姓字，或从海鸟作朋俦。","故人珂佩周旋处，紫殿风清十二楼。"]},{"t":"南安道中","f":"七言律诗","c":["笋舆初下上江船，无数青山入枕边。","几处猿啼愁入瘴，五更鸡叫梦朝天。","不堪岁月如流水，赖有文章似涌泉。","归日乡人问何往，云从海上觅神仙。"]},{"t":"章贡道中","f":"七言律诗","c":["多情明月落船傍，万里孤城望帝乡。","客里已无金马诏，箧中犹有赐衣香。","岭南地湿家山暮，天上风微殿阁凉。","忆得当年曾夜直，玉龙银箭漏声长。"]},{"t":"吉安道中","f":"七言律诗","c":["西风吹雁不成行，万里孤舟下夕阳。","度峡冷风攲客帽，卷帘凉月落琴床。","江湖水满鸥偏乐，花柳春深马正忙。","又看青原山色好，故乡归计喜相将。"]},{"t":"采石谩兴","f":"曲","c":["谁记将军亡国时，江东父老鬓如丝。","古今天堑几千里、南北楼船百万师。","中国一飞传檄箭，南朝谩有渡江碑。","太平到处山如画，暖日晴风飏酒旗。"]},{"t":"过姑熟怀陈行之教授","f":"七言律诗","c":["经过姑熟多佳趣，卜筑黄花老亦佳。","白发故人田负郭，青骢游子客为家。","郡斋檐雨閒棋子，官路山风过楝花。","自笑欲归归未得，裁诗相忆墨翻鸦。"]},{"t":"宿青阳云松台 其一","f":"七言律诗","c":["九老排云独擅尊，众山拱戴似儿孙。","石房仙去神光现，洞府龙归雨气昏。","上古几年埋地轴，至今九柱插天根。","何时身在层峰顶，手把丹书扣帝阍。"]},{"t":"宿青阳云松台","f":"七言律诗","c":["县门遥接九华山，日日天开图画看。","云气晓连铜篆湿，翠光晴锁砚池寒。","人间官府红尘马，天上神仙白玉盘。","高卧云松定何日，仰攀北斗夜阑干。"]},{"t":"过五溪","f":"七言律诗","c":["万壑泉声下五溪，小凉天气下溪时。","相逢桥上无非客，行尽江南都是诗。","苦雨最嫌鸠唤急，爱山不厌马行迟。","几时宿向华峰顶，露月萧萧生桂枝。"]},{"t":"寄中曹学士除浙江财赋总管闻至姑苏","f":"七言律诗","c":["钱塘西府曹学士，饮酒吟诗亦快哉。","閒醉时游虎丘寺，浩歌独上姑苏台。","一生好客黄金去，百岁催人白发来。","藉藉声名满天下，朝廷今日肯遗才。"]},{"t":"梦登高山得诗 其一","f":"七言律诗","c":["登高远望四山齐，何处风流杜牧之。","白苧曾听松下唱，紫箫还向月中吹。","野云雨过无行迹，芳草春深有断碑。","梦里胜游閒记得，翠微高上写乌丝。"]},{"t":"梦登高山得诗","f":"七言律诗","c":["杖藜踏破碧崔嵬，梦里清游乐未回。","万壑泉声松外去，数行秋色雁边来。","文章小杜人何在？","风雨重阳菊自开。","山路云深行客倦，竹鸡飞上独春台。"]},{"t":"石门怀舜咨夜坐","f":"七言律诗","c":["道人挂剑丹阳去，欲入茅山恐未曾。","飞去难寻云外鹤，归来独礼斗前灯。","梦回洗钵分秋水，酒醉敲壶碎夜冰。","独有江东未归客，西风诗骨瘦崚嶒。"]},{"t":"建德道中","f":"七言律诗","c":["泉作溪流石作桥，桑麻成垄接东饶。","鸡鸣犬吠人家近，水转峰回驿路遥。","虎啸树林风猎猎，人行弓箭马萧萧。","多情一片吴天月，夜夜相随伴寂寥。"]},{"t":"寄湖南张子寿以西台御史拜前职素有退志故举兼善劝之","f":"七言律诗","c":["初拂绣衣来日下，又持宪节驻湖边。","铁冠晴雪照荆国，羽扇清风扫瘴烟。","客馆如闻鹧鸪语，乡程好买洞庭船。","状元御史今何学，已过扬州看月圆。"]},{"t":"大同驿","f":"七言律诗","c":["题诗洒墨江东驿，笔力犹能挽怒涛。","飞骑将军朝出猎，打门县吏夜催徭。","天高路远心如水，夜永愁多独过桥。","却忆玉堂诸学士，凤池东畔佩声遥。"]},{"t":"答茅山道士见寄","f":"七言律诗","c":["道人自有爱山癖，蜡屐平生几两穿。","七窍冷云秋喷竹，一琴明月夜调弦。","山中紫府茅君宅，肘后丹方许史传。","短褐拟寻黄犊出，长镵斸雪早春前。"]},{"t":"酬张伯雨寄茅山志","f":"七言律诗","c":["恨余未识茅君面，喜得茅山道士书。","灯外雨声那厌听，风前石发岂堪梳。","碧窗云气寒生楮，清室丹珠夜绕厨。","梦到层台夜披卷，桂林风动月疏疏。"]},{"t":"奎章阁观进皇朝经世大典","f":"七言律诗","c":["文章天子大一统，馆阁词臣日纂脩。","方丈奎光悬秘阁，九重春色满龙楼。","门开玉钥芸香动，帘捲金钩砚影浮。","圣览日长万几暇，墨花流出凤池头。"]},{"t":"西宫春日与吴锦衣赋","f":"七言律诗","c":["九重春色金银阙，冠带将军尽羽林。","上苑春莺随柳啭，西宫午漏隔花深。","天开阊阖收金锁，帘卷奎光听玉音。","白发儒臣卖词赋，《长门》应费万黄金。"]},{"t":"京师春夜呈宋礼部","f":"七言律诗","c":["柳色无端染翠裙，官街车马去纷纷。","莺花御苑春多少，漏箭宫壶夜几分。","金缕悠扬燕市月，玉箫缭绕凤楼云。","太平天子恩如海，亦遣馀音客枕闻。"]},{"t":"送王习灵新授宗师朝京","f":"七言律诗","c":["玉佩珊瑚下界闻，天风吹动碧榴裙。","刘郎跨鹤游三岛，王子吹箫到五云。","花洞夜深传玉印，石坛月黑礼茅君。","若逢天上吴夫子，应有丹砂肯我分。"]},{"t":"寄新原林道士","f":"七言律诗","c":["我识华阳林道士，步虚空里带淮腔。","几年挂剑茅君洞，一夜渡船扬子江。","醉酒惯眠松下石，题诗爱近水边窗。","仙家白鹤养无数，不惜人间借一双。"]},{"t":"游钟山感兴","f":"七言律诗","c":["骢马穿松到上方，南巡辇路碧苔荒。","禅僧白首看行殿，山鬼黄昏避御床。","云冷夜无龙在钵，日长时有虎巡廊。","小桃十月开如锦，犹带前朝雨露香。"]},{"t":"春日登北固多景楼录奉即休长老二首 其一","f":"七言律诗","c":["醉拍阑干起白鸥，登临不尽古今愁。","六朝人物空流水，三国江山独倚楼。","秃发凉风吹木叶，孤城落日下帘钩。","海门不管兴亡事，犹送春潮打石头。"]},{"t":"鹤林僧送竹笋","f":"七言律诗","c":["棕鞋桐帽走风雨，正是山僧送笋时。","夜月不留栖凤影，春雷失却化龙枝。","从来不识葛藤味，此去方参玉版师。","老子胸中冰雪满，岁华晚节更相期。"]},{"t":"游钟山遇雨","f":"七言律诗","c":["虎踞龙蟠翠作堆，竹舆高下路萦回。","潮声万壑松风过，云气满楼山雨来。","梁武庙前芳草合，荆公墓下野花开。","百年感慨成何事？","且尽生前酒一杯。"]},{"t":"陪张御史游钟山","f":"七言律诗","c":["乌府仙人獬豸冠，清游喜得共儒酸。","鹃花过雨干岩净，骢马穿云六月寒。","山鬼每惊诗句险，客怀惟爱酒杯宽。","一时佳兴千年遇，莫作浮生半日看。"]},{"t":"题半山寺","f":"七言律诗","c":["今日偶成林壑趣，清幽恨未得从容。","龙归石洞半山雨，潮卷天风十里松。","春路泥深多滑马，晚楼雾重只闻钟。","荆公旧隐知何处，回首苍茫第几重。"]},{"t":"江城玩雪","f":"七言律诗","c":["雪正纷纷客倚栏，长江风急吼天关。","干重铁瓮成银瓮，一夜金山换玉山。","舟子迷归寒浦外，衲僧疑在白云间。","晓来霁日高林照，好景依然悦我颜。"]},{"t":"游金山","f":"七言律诗","c":["约客同游买渡船，閒观古刹礼金仙。","山中好景无多地，天下知名第一泉。","佛阁齐云浮海屿，客帆过寺带风烟。","当年郭璞因何事，来葬江心作浪传。"]},{"t":"平望驿道","f":"七言律诗","c":["左带吴松右五湖，人家笑语隔菰蒲。","风涛不动鱼龙国，烟雨翻成水墨图。","越客卧吹船上笛，吴姬多倚水边垆。","鉴湖道士如招隐，一曲他年得赐无。"]},{"t":"送王御史","f":"七言律诗","c":["骢马如龙玉作鞭，江头下马上官船。","承恩不比寻常辈，入谏频瞻咫尺天。","草满畬田多战骨，花飞驿路少人烟。","宪台自是清高甚，时事关心易白颠。"]},{"t":"题玄妙观玉皇殿","f":"七言律诗","c":["虚空台殿枕层岑，木杪丹梯起百寻。","花落鸟啼青竹里，客来犬吠白云深。","松坛昼日移幢影，石室天风送铎音。","老鹤如人窗下立，閒听羽士理瑶琴。"]},{"t":"复题平望驿","f":"七言律诗","c":["秋雨黄华下九天，又随归雁过吴川。","荒村有火夜投宿，野渡无人秋放船。","中酒不堪连夜饮，思家无奈五更前。","归来却被青山笑，万丈黄尘两鬓烟。"]},{"t":"春日侍驾游香山","f":"七言律诗","c":["马上游人隔苑墙，天家未肯纵春阳。","轻寒轻暖鸟声转，无雨无风花命长。","香殿云烟随凤辇，交旂日月耀龙章。","三三节近晴光稳，满进虞廷万岁觞。"]},{"t":"寓升龙观时吴宗师持旨先驾至大都度滦川遂次韵赋此以寄并简顺咨先生","f":"七言律诗","c":["扈跸千官取次行，道人先踏雪泥晴。","关南日暖龙颜近，岭北风高鹤背轻。","丞相早行霜滑马，将军夜宿火连营。","一年两度经过处，惟有青山管送迎。"]},{"t":"送南安镇抚赵南山捧表西省","f":"七言律诗","c":["平生尺剑众中师，臣子肝肠天地知。","少壮金戈探虎穴，太平铠甲网蛛丝。","青衫白发尊前酒，紫塞黄云马上诗。","今日又随天表去，梅花香里立沙墀。"]},{"t":"过李陵墓","f":"七言律诗","c":["降入天骄愧将才，山头空筑望乡台。","苏郎有节毛皆落，汉主无恩使不来。","青草战场雕影没，黄沙鼓角雁声哀。","那堪携手河梁别，泪洒西风骨已灰。"]},{"t":"拟李陵送苏武","f":"七言律诗","c":["同是肝肠十九年，河梁携手泪潸然。","铁衣骨朽埋沙碛，白首君归弃雪毡。","海北牧羊无梦到，上林过雁有书传。","汉家恩爱君须厚，剪纸招魂望塞边。"]},{"t":"黄河夜送西台御史张子寿时新除湖广佥宪","f":"七言律诗","c":["爱君足迹半天下，白简清霜秋气多。","帆影东南湖上去，马蹄西北日边过。","风波玉露仙人掌，文彩云机织女梭。","自笑追随远游客，斗槎星夜下黄河。"]},{"t":"黄河夜雨怀兀颜子方","f":"七言律诗","c":["风流俊逸四公子，轻帽短衣过鲁城。","紫陌东风閒戏马，绿窗明月醉闻莺。","樱桃花下春中酒，沈水香回夜按筝。","独有黄河千里客，短篷听雨到天明。"]},{"t":"题高唐驿","f":"七言律诗","c":["三尺高唐帝子坟，东风吹草绿沄沄。","官中子母生前别，天上箫韶梦里闻。","日暮白杨飞乱雪，夜深黑气结愁云。","小臣泣血应无补，留与他年太史云。"]},{"t":"送王御史时巡历河道解舟金陵","f":"七言律诗","c":["淮南雨过好晴色，御史楼船动楚桡。","杨柳清风秋解缆，琼花明月夜闻箫。","卧听天上银河浪，梦到云边白玉桥。","后夕相思裁短咏，莫将书札付洪乔。"]},{"t":"游铁塔寺","f":"七言律诗","c":["江南地僻繁华盛，古寺巍然铁塔存。","金屋月梅横夜雨，铜驼露草泣秋原。","六朝王气人何在，几度悲风铃自喧。","尚有他年旧时字，摩挲一半没苔痕。"]},{"t":"送外舅慎翁之燕京","f":"七言律诗","c":["扬子江头柳色浓，小船春雨去匆匆。","青袍铁瓮龙门婿，紫锦蒲帆鹤发翁。","晋府旧臣还塞北，星门娇客卧床东。","明年亦是燕山客，骑马天街踏软红。"]},{"t":"春日登北固多景楼录奉即休长老二首 其二","f":"七言律诗","c":["东风吹树散晴岚，独上层楼酒半酣。","拍岸潮声来海外，满江山色入淮南。","当时霸主分三国，此日吴禅老一龛。","惟有楼前旧时柳，年年三月色如蓝。"]},{"t":"还京口","f":"七言律诗","c":["黄鹤山头雪未消，行人归计在今朝。","城高铁瓮江山壮，地接金陵草木凋。","北府市楼开旧酒，南朝官柳识归桡。","吏人莫见参军面，水宿风餐鬓发焦。"]},{"t":"寄金山长老","f":"七言律诗","c":["老师召对金銮殿，喜动龙颜坐赐茶。","一日潮音起般若，九重春色上袈裟。","高风已入三天竺，妙果重开五色花。","渴想杨枝旧甘露，何时一到病人家。"]},{"t":"腊尽过练湖","f":"七言律诗","c":["独倚牙樯数客程，残年风景足乡情。","寒天半夜无人语，明月满船闻雁声。","云外好山如有约，烟中野树不知名。","明朝乌鹊桥头闹，应是人家出户迎。"]},{"t":"丹阳普宁寺席上","f":"七言律诗","c":["红白桃花开满枝，满城微雨牡丹时。","因过古寺逢僧话，莫遣扁舟解缆迟。","客里逢春多病酒，江南到处半题诗。","山川总是曾游处，一曲琵琶写别离。"]},{"t":"送王郎还钱塘","f":"七言律诗","c":["王郎会我丹阳郭，归兴钱塘不可留。","北固雪晴山出画，西湖春动水明楼。","草生湘浦行人远，日落吴山故国愁。","安得与君二三月，买花沽酒醉红舟。"]},{"t":"宿玄洲精舍芝菌阁别张伯雨二首 其一","f":"七言律诗","c":["一到茆山三日留，满山风雨过中秋。","云行松树高低见，日落涧水东西流。","外史相邀登菌阁，此身只合往瀛洲。","它年丛桂结招隐，野服愿随麋鹿游。"]},{"t":"宿玄洲精舍芝菌阁别张伯雨二首 其二","f":"七言律诗","c":["竹树忽闻乾鹊鸣，明朝归计候新晴。","小楼无处有秋意，暗雨空山如海声。","叶落窗虚开鹤步，峰回路合断人行。","谁知昨夜玄洲客，剪烛题诗过二更。"]},{"t":"登德兴聚远楼上有宋庙书","f":"七言律诗","c":["眉山仙去风流尽，聚远楼空月色寒。","波暖东风入尊俎，夜深北斗挂阑干。","幽花野草先灵杳，铁画银钩御墨残。","不见旧时双燕子，春风几度捲帘看。"]},{"t":"九华山石墨驿","f":"七言律诗","c":["马上行人思九华，飘飘高兴满天涯。","排空峭石生玄笋，落日奇峰挂赤霞。","仙掌九秋倾露屑，天河半夜碍星槎。","云中五老应招手，呼我来游太乙家。"]},{"t":"至龙潭驿","f":"七言律诗","c":["野草山花知姓字，人生踪迹似浮萍。","帆冲细雨空江白，鸟没长淮远树青。","今夜故人离水驿，明朝别酒尽沙瓶。","匆匆又入丹阳去，暮鼓晨鸡已候听。"]},{"t":"凤凰台怀古","f":"七言律诗","c":["凤凰一去不复返，竹实桐花空满庭。","暮雨楼台连野寺，秋风鼓角动边城。","水边万井吴烟白，天外三山楚树青。","不见骑鲸李公子，几回惆怅此中行。"]},{"t":"次王本中灯夕观梅","f":"七言律诗","c":["翠禽偷梦出南园，绰约冰姿傍绿尊。","冰镜玉钗浮翠影，风帘银烛照妆痕。","粉香微润无人见，素质多寒藉酒温。","不似海棠春睡去，西楼月落已黄昏。"]},{"t":"谢人惠木犀","f":"七言律诗","c":["霜高落叶如雨急，有客敲门送木犀。","夜月不留藏兔影，秋风失却挂蟾枝。","云中仙子金华坠，天上吴生玉斧移。","寄语凤台老居士，旋磨香露写新诗。"]},{"t":"奉和邓善之学士赠陈尧夫教授之作","f":"七言律诗","c":["巴西夫子邓学士，文彩珊珊玉佩琚。","天上已无金马诏，人间空有白鹅书。","云窗春透松花湿，月殿秋高桂影疏。","不见青山埋骨处，水晶宫里是幽居。"]},{"t":"过江东驿次王侍御韵","f":"七言律诗","c":["政事文章王侍御，朱帘捲雨送将归。","江东春色分银篆，马上清风吹绣衣。","泽国水香鱼藻动，砚池春暖墨花飞。","至今吴楚经行处，夜夜奎光绕太微。"]},{"t":"九日登石头城","f":"七言律诗","c":["九日吟鞭聚石头，翠微高处倚晴秋。","西风不定雁初度，落木无边江自流。","两眼欲穷天地观，一杯深护古今愁。","乌台宾主黄华宴，未必龙山是胜游。"]},{"t":"寄野堂","f":"七言律诗","c":["忆昔相逢春莫天，道傍杨柳尽飞绵。","池鱼出水将三尺，竹笋成林又一年。","高士已成招隐赋，行人未办买山钱。","野堂灯火清秋夜，何日联床听雨眠。"]},{"t":"寄同年友","f":"七言律诗","c":["忆昔同登龙虎榜，思君一度一悽然。","三年岁月红尘里，万里关河白雁前。","天上故人淮水隔，江南老树楚云连。","不堪回首知何处，闻说年来海变田。"]},{"t":"寄茅山谢舜咨","f":"七言律诗","c":["升龙观里谢道士，一入茅山不肯回。","白发笑人年百岁，青天容我日千杯。","已知圣主求方士，未必先生下钓台。","每向石头城下望，顺风应寄鹤书回。"]},{"t":"送王幼达之北京","f":"七言律诗","c":["五色云烟百尺台，王郎独步近蓬莱。","江湖水落鱼龙上，天地秋高鸿雁来。","北苑芙蓉风惨淡，西宫杨柳月徘徊。","此行正及扶桑日，应献尧庭万寿杯。"]},{"t":"升龙观夜烧香印上有吕洞宾老树精","f":"七言律诗","c":["兰风吹动吕仙影，老树槎牙吐暮秋。","夜静药炉丹火现，月明神剑夜光浮。","已知浩气无穷尽，不到心灰未肯休。","铁笛一声吹雪散，碧云飞过岳阳楼。"]},{"t":"送湖洲鼓元明道士入茅山","f":"七言律诗","c":["道人居住碧湘湾，清夜月明摇佩环。","出门倒拄九节杖，辞家却入三茅山。","开笼放鹤横江去，写檄收龙带雨还。","便拟访君吹铁笛，青松白石往来间。"]},{"t":"送崔知印之江东","f":"七言律诗","c":["金陵市上多骢马，白下桥头喜识君。","玉佩清摇乌府月，篆银红带赤城云。","买舟又过江东去，离笛难禁柳外闻。","独有无媒送行者，依然野鹤在鸡群。"]},{"t":"题先春卷上有萧滕王三学士赞","f":"七言律诗","c":["番阳山人春拥门，玉堂学士墨翻盆。","屋前屋后雪千树，枝北枝南月半痕。","寒夜老龙摇玉骨，霜天瘦鹤吊冰魂。","未经调鼎休惆怅，会见留酸到子孙。"]},{"t":"寒夜即事次韵呈许荣达","f":"七言律诗","c":["呵笔题诗逸兴舒，翠帘寒重捲虾须。","春分采石仙人酒，夜读茅山道士书。","箭刻未移寒漏浅，江声渐少夜潮枯。","闭门岁晚仍多事，归梦无端绕故庐。"]},{"t":"鹤骨笛","f":"七言律诗","c":["九皋声断楚天秋，玉顶丹砂一夕休。","杨柳肯忘枯朽恨，梅花吹尽古今愁。","魂归辽海身如蜕，曲破江城月满楼。","惆怅玉人三弄罢，杳无消息到扬州。"]},{"t":"天灯","f":"七言律诗","c":["高挂长绳百尺馀，直飞红燄上天衢。","一包春髓蒸元气，九转灵丹炼太虚。","綵凤抱成吞日卵，赤龙衔出照天珠。","高高不受飞蛾扑，长使凡人仰面吁。"]},{"t":"过紫薇庵访冯道士 其一","f":"五言绝句","c":["道士爱幽居，年来一事无。","盆池新过雨，石上种菖蒲。"]},{"t":"过紫薇庵访冯道士 其二","f":"五言绝句","c":["山中华盖洞，石气冷萧萧。","不见眠云客，惟逢避雨樵。"]},{"t":"过紫薇庵访冯道士 其三","f":"五言绝句","c":["研珠滴露清，自点太玄经。","尽日无人到，小窗兰叶青。"]},{"t":"雪霁过清溪题道士江野舟南馆 其一","f":"五言绝句","c":["孤舟横野水，门外雪晴初。","白日莫放鹤，青溪閒钓鱼。"]},{"t":"雪霁过清溪题道士江野舟南馆 其二","f":"五言绝句","c":["江南正月半，犹自有梅花。","踏雪去何处，青溪道士家。"]},{"t":"过高邮射阳湖杂咏 其三","f":"五言绝句","c":["野鹤如人长，迎风理毛羽。","独立秋雨凉，人来忽飞去。"]},{"t":"过高邮射阳湖杂咏 其四","f":"五言绝句","c":["雨湿鼓声重，风匀湖面平。","官船南北去，帆影挂新晴。"]},{"t":"过高邮射阳湖杂咏 其六","f":"五言绝句","c":["秋水落红衣，秋波日潇洒。","不见采莲人，惟逢捕鱼者。"]},{"t":"过高邮射阳湖杂咏 其七","f":"五言绝句","c":["霜落大湖浅，渔家悬破罾。","此时生计别，小艇卖秋菱。"]},{"t":"过高邮射阳湖杂咏 其八","f":"五言绝句","c":["捕鱼湖中水，卖鱼城市里。","夫妇一叶舟，白头共生死。"]},{"t":"过高邮射阳湖杂咏 其九","f":"五言绝句","c":["大罾一丈阔，小舟一叶轻。","相传子与孙，终古无人争。"]},{"t":"病中杂咏 其一","f":"五言绝句","c":["十日九风雨，深秋独闭门。","积阴须自散，倚杖望朝暾。"]},{"t":"病中杂咏 其二","f":"五言绝句","c":["为客家千里，思归月满楼。","木犀开欲尽，病里过中秋。"]},{"t":"病中杂咏 其三","f":"五言绝句","c":["门系青骢马，多应问病人。","小官好疏散，莫讶懒衣巾。"]},{"t":"病中杂咏 其四","f":"五言绝句","c":["病形如瘦鹤，照影向清池。","自有冲霄志，游鱼莫见疑。"]},{"t":"病中杂咏 其五","f":"五言绝句","c":["风叶高下落，秋砧远近闻。","天涯多病客，倚杖看孤云。"]},{"t":"病中杂咏 其六","f":"五言绝句","c":["陶令贫无酒，郎言菊也无。","家僮烧柿叶，邻舍送茱萸。"]},{"t":"病中杂咏 其七","f":"五言绝句","c":["多病东厅客，深秋出幕迟。","芙蓉开也未，叶上好题诗。"]},{"t":"赠钦师","f":"五言绝句","c":["随缘驻瓶锡，顶雪已差差。","莫道禅非学，心空不废诗。"]},{"t":"画","f":"五言绝句","c":["树色浓堪掬，痴岚扑雨秋。","道人岩下住，屋角挂奔流。"]},{"t":"画二首 其二","f":"五言绝句","c":["草迷苍耳子，鸟弄白头翁。","十里湖山树，平分杳霭中。"]},{"t":"次韵与德明小友 其一","f":"曲","c":["烟雨短篷水口，人家乱石山前。","送别莫忘今日，相逢知在何年。"]},{"t":"次韵与德明小友 其二","f":"曲","c":["莫笑风餐水宿，暂离马足车尘。","两岸好山送客，一江细雨归人。"]},{"t":"舟中题画卷","f":"曲","c":["两岸好山如画，丹崖翠壁楼台。","爱杀南闽风景，小官何日归来。"]},{"t":"雪中渡江过山饮旸谷简上人房 其一","f":"七言绝句","c":["闻说山中新酒熟，野人乘兴过江来。","小窗无处看春色，一树梅花雪里开。"]},{"t":"雪中渡江过山饮旸谷简上人房 其二","f":"七言绝句","c":["山酒吹香出小槽，灯前痛饮污青袍。","夜深梦醒知何处，老鹤一声山月高。"]},{"t":"京口城南次集 其一","f":"七言绝句","c":["野荠花开春欲尽，山樱子落雨初晴。","酒醒骑马踏花去，门外绿阴无数生。"]},{"t":"京口城南次集 其二","f":"七言绝句","c":["雨深绿叶樱桃肥，日长青草蝴蝶飞。","江南三月春欲尽，白马王孙游不归。"]},{"t":"憩奉真道院","f":"七言绝句","c":["落花风飏步虚声，翠草玄芝烂熳生。","过客不知春早晚，午窗晴日睡闻莺。"]},{"t":"对客","f":"七言绝句","c":["石榴花开光照屋，胡桃叶大阴满帘。","焚香终日对客坐，时有白云来纤纤。"]},{"t":"过扬州","f":"七言绝句","c":["买舟南浦秋闻雁，呼酒西窗夜剪灯。","何处玉箫天似水，琼花一夜白如冰。"]},{"t":"宿淮南长芦寺","f":"七言绝句","c":["柳花漠漠春归寺，芦叶青青晚渡江。","屋角松声撼风雨，道人一夜不开窗。"]},{"t":"宿化阁渡口阻风 其一","f":"七言绝句","c":["江船日午无人渡，渡口人家尽不罾。","却忆吴姬新压酒，钟山对岸是金陵。"]},{"t":"宿化阁渡口阻风 其二","f":"七言绝句","c":["艇子渡江何日回，石头城下浪如雷。","淮南春色知多少，一树樱桃带雨开。"]},{"t":"宿化阁渡口阻风 其三","f":"七言绝句","c":["客船伐鼓春江暮，水面鱼龙出浪花。","今夜石头城下泊，买鱼沽酒向谁家。"]},{"t":"宣化江阻风","f":"七言绝句","c":["渡口无人上野航，白头巨浪自冲撞。","东风三日不肯住，吹送杨花飞度江。"]},{"t":"题界首驿 其一","f":"七言绝句","c":["清气扑人湖面水，幽声到耳树头风。","人家蚕老樱桃过，恰似淮南四月中。"]},{"t":"题界首驿 其二","f":"七言绝句","c":["平湖过雨天开镜，落日放船人打鱼。","野老柳阴沽秫酒，行人马上寄家书。"]},{"t":"渡淮即事","f":"七言绝句","c":["杨花点点冲帆过，燕子双双掠水飞。","淮上渔人閒不得，船头对结绿蓑衣。"]},{"t":"西宫即事 其二","f":"七言绝句","c":["退朝西殿承平日，一片春云奏凤笙。","白面内官供玉食，却将黄帕覆银铛。"]},{"t":"还台偶成 其一","f":"七言绝句","c":["高低柳絮飞渡水，红白桃花开满枝。","自笑江南无用客，一春无事只题诗。"]},{"t":"春日偶成","f":"七言绝句","c":["踏马归来过早春，空阶已见草如茵。","东风吹绿青溪柳，马上轻寒不著人。"]},{"t":"题冶城道士稽秋山卷","f":"七言绝句","c":["不见冶城稽道士，云深无处访仙踪。","夜闻老鹤行枯叶，知在秋山第几重。"]},{"t":"余与观志能俱以公事赴北舟至梁山泊时荷花盛开风雨大至舟不相接遂泊芦苇中余折芦一叶题诗其上寄志能","f":"七言绝句","c":["题诗芦叶雨斑斑，底事诗人不奈閒。","满浦荷花开欲遍，客程五月过梁山。"]},{"t":"春词","f":"七言绝句","c":["深宫尽日垂珠箔，别殿何人度玉筝。","白面内官无一事，隔花时听打毬声。"]},{"t":"上京即事 其一","f":"七言绝句","c":["白昼箫韶起半空，水晶行殿玉屏风。","诸王舞蹈千官贺，高捧蒲萄寿两宫。"]},{"t":"上京即事 其二","f":"七言绝句","c":["沙苑棕毛百尺楼，天风摇曳锦绒钩。","内家宴罢无人到，面面珠帘夜不收。"]},{"t":"上京即事 其三","f":"七言绝句","c":["凉殿参差翡翠光，朱衣华帽宴亲王。","红帘高卷香风起，《十六天魔》舞袖长。"]},{"t":"上京即事 其四","f":"七言绝句","c":["中官队仗等宫车，小样红靴踏软沙。","昨日官家清宴罢，御罗轻帽插珠花。"]},{"t":"上京即事 其五","f":"七言绝句","c":["大野连山沙作堆，白沙平处见楼台。","行人禁地避芳草，尽向曲阑斜路来。"]},{"t":"上京即事 其六","f":"七言绝句","c":["院院烧灯有咒僧，垂帘白日点酥灯。","上京六月凉如水，人渴天瓢更赐冰。"]},{"t":"上京即事 其七","f":"七言绝句","c":["祭天马酒洒平野，沙际风来草亦香。","白马如云向西北，紫驼银瓮赐诸王。"]},{"t":"上京即事 其八","f":"七言绝句","c":["牛羊散漫落日下，野草生香乳酪甜。","卷地朔风沙似雪，家家行帐下毡帘。"]},{"t":"上京即事 其十","f":"七言绝句","c":["五更寒袭紫毛衫，睡起东窗酒尚酣。","门外日高晴不得，满城湿露似江南。"]},{"t":"再过梁山泊有怀观志能 其一","f":"七言绝句","c":["故人同出不同归，云水微茫入梦思。","记得题诗向芦叶，满湖风雨似来时。"]},{"t":"再过梁山泊有怀观志能 其二","f":"七言绝句","c":["灯火官船夜睡迟，满湖风露袭人衣。","无端惊起沙头雁，明月芦花各自飞。"]},{"t":"邵伯舟中","f":"七言绝句","c":["惊鱼时出浪花雪，短鬓凉吹水面风。","远客行船秋色里，谁家吹笛月明中。"]},{"t":"题京口高资包氏壁","f":"七言绝句","c":["肩舆晓踏新晴出，山色青青上客衣。","昨日千林风雨过，满田白水鹭鸶飞。"]},{"t":"赠茅山道士胡琴月","f":"七言绝句","c":["茅山道士来相访，手抱七弦琴一张。","准拟月明弹一曲，桐花落尽晓风凉。"]},{"t":"送镜中圆上人游钱塘","f":"七言绝句","c":["西湖西畔三天竺，古木苍藤望欲迷。","遥忆道人禅榻夜，月高霜落听猿啼。"]},{"t":"过赞善庵","f":"七言绝句","c":["夕阳欲下行人少，落叶萧萧路不分。","脩竹万竿秋影乱，山风吹作满窗云。"]},{"t":"云中过龙潭紫微观访道士不值","f":"七言绝句","c":["道人已跨龙潭鹤，童子能煎雀舌茶。","一夜山中满林雪，客来无处觅梅花。"]},{"t":"将游茅山先寄道士张伯雨","f":"七言绝句","c":["借骑白鹤访茅君，琪树秋声隔夜闻。","料得山中张道士，开门先扫鹤巢云。"]},{"t":"登众妙堂题商学士画雨霁归舟图","f":"七言绝句","c":["大茅峰顶见日出，烟树云林宿雨收。","万里澄江净如练，却从天际识归舟。"]},{"t":"紫阳道士冯友直与余同宿菌阁次日予过元符宫友直同僧安上人入五云观因以寄之","f":"七言绝句","c":["道人采药出山迟，菌阁秋高袭羽衣。","半夜忽闻孤鹤唳，五云相伴一僧归。"]},{"t":"同张伯雨过凝神庵因观宋高宗所赐蒲衣道士张达道白羽扇","f":"七言绝句","c":["晴日赤山湖水明，湖中山影一眉青。","蒲衣道士无人识，羽扇年年落凤翎。"]},{"t":"茅山玄洲精舍有道士号紫轩又号木通生白日坐解遗书其徒许道民者至今坐墙尚存为题其卷","f":"七言绝句","c":["白日飞升凌紫烟，灵书犹许道民传。","玄洲精舍无多地，夜夜火珠光烛天。"]},{"t":"九日渡淮喜东南顺风 其一","f":"七言绝句","c":["青旗红字映河滨，九日人家物色新。","渡口客船争贳酒，斫鱼裂纸赛江神。"]},{"t":"九日渡淮喜东南顺风 其二","f":"七言绝句","c":["东南风送渡淮船，过雁声寒水接天。","落日红霞收未尽，澹云微月出东边。"]},{"t":"春日镇阳柳溪道院","f":"七言绝句","c":["城外青溪出洞门，道人归去日长曛。","柳花满地无人扫，隔水遥看是白云。"]},{"t":"过镇阳城南观音院","f":"七言绝句","c":["柳色暗藏溪上寺，露华偏湿水边僧。","门前天暝荷花满，出水游鱼夜戏灯。"]},{"t":"寄奎章学士济南李溉之","f":"七言绝句","c":["山东李白似刘伶，投老归来酒半醒。","天下三分秋月色，二分多在水中亭。"]},{"t":"寄奎章学士济南李溉之 其二","f":"七言绝句","c":["笑掷金龟上酒船，不须图像在凌烟。","碧罗衫色乌纱帽，便是开元李谪仙。"]},{"t":"过献州","f":"七言绝句","c":["西风老树昏鸦集，落日荒城暗雨崩。","寂寞断碑秋草里，路人遥指献王陵。"]},{"t":"补题淮西送王仲和从事诗卷","f":"七言绝句","c":["百年驰马苦匆匆，水落乌江楚庙空。","眼底山川犹历历，淮南旧梦雨声中。"]},{"t":"题李溉之送别诗卷","f":"七言绝句","c":["清平三曲动明皇，四海知名李白狂。","把酒探春送行客，挥毫字字柳花香。"]},{"t":"将入闽赵郡崔好德求题舆地图","f":"七言绝句","c":["月轮西转日生东，四海车书总会同。","骑马出门天万里，山川长在别离中。"]},{"t":"黄河舟中月夜","f":"七言绝句","c":["十丈雪帆拂斗杓，星槎风急浪花飘。","夜深露冷银河近，卧听天孙织绛绡。"]},{"t":"阻风南露筋过罗汉寺登楼看山茶","f":"七言绝句","c":["野寺寻春酒未醒，不知几日过清明。","小阑干外东风急，一树山茶落晚晴。"]},{"t":"夜宿金山题金山图","f":"七言绝句","c":["远人夜宿金山寺，坐对画图如梦中。","剪烛题诗云气里，不知身已在龙宫。"]},{"t":"春日过丹阳石仲和宅会茅山道士石山辉","f":"七言绝句","c":["杏花一夜雨声寒，酒醒丹阳几日还。","却遇茅君三白鹤，借骑一只到三山。"]},{"t":"登姑苏台","f":"七言绝句","c":["阊门杨柳自春风，水殿幽花泣露红。","飞絮年年满城郭，行人不见馆娃宫。"]},{"t":"登姑苏台 其二","f":"七言绝句","c":["野水满城飞燕子，谁家小艇载吴姬。","姑苏台上一樽酒，落日昏鸦无限悲。"]},{"t":"入闽过松陵和王伯循所题","f":"七言绝句","c":["广陵城里别匆匆，一去三山隔万重。","日暮江东寄相忆，欲从秋水剪芙蓉。"]},{"t":"宿长安驿 其一","f":"七言绝句","c":["坝北坝南河水平，客船争缆水云腥。","乡音吴越不可辨，灯火黄昏如乱星。"]},{"t":"宿长安驿 其二","f":"七言绝句","c":["水面微风动杨柳，客船吹笛月明中。","远人江海多归思，卧看流星度水东。"]},{"t":"钓台夜兴","f":"七言绝句","c":["仙茶旋煮桐江水，客火遥分石壁灯。","风露满船山月上，夜凉独对钓台僧。"]},{"t":"早发钓台","f":"七言绝句","c":["山头钟响不闻鸡，重露翻鸦满树啼。","艇子钓台东畔发，月轮却在钓台西。"]},{"t":"兰溪舟中","f":"七言绝句","c":["水底霞天鱼尾赤，春波绿占白鸥汀。","越船一叶兰溪上，载得金华一半青。"]},{"t":"泊江家步无月同孟志学小酌溪上 其一","f":"七言绝句","c":["把酒无从邀月色，共君且复听滩声。","夜深灯影青溪上，鱼尾摇船亦有情。"]},{"t":"泊江家步无月同孟志学小酌溪上 其二","f":"七言绝句","c":["兰溪春水似蒲萄，越女如花压小槽。","今夜共君溪上醉，直须溪月照宫袍。"]},{"t":"黄亭驿晓起","f":"七言绝句","c":["积雨莓苔上壁青，晓寒山馆梦初醒。","鹧鸪声里流年度，自是行人不忍听。"]},{"t":"和经历杨子承晓发山馆","f":"七言绝句","c":["梦回山馆月西斜，曙色千峰动紫霞。","杜宇一声山竹裂，鹧鸪飞上野棠花。"]},{"t":"石林即事 其一","f":"七言绝句","c":["三山幕府无公事，多病郎官懒出门。","老鹤唤回童子睡，石盆新雨长兰孙。"]},{"t":"石林即事 其二","f":"七言绝句","c":["蒲扇屏山紫竹床，岭南五月似秋凉。","砚池风动云生石，帘外雨兰吹湿香。"]},{"t":"题屏风","f":"七言绝句","c":["海国夜凉星乱垂，石林逋客未眠时。","满帘月色吹轻雾，白露无声下竹枝。"]},{"t":"独坐恭和堂","f":"七言绝句","c":["东阁高悬如道院，人言幕府最清严。","印封不动坐终日，满树梅花雨一帘。"]},{"t":"闽城岁暮","f":"七言绝句","c":["岭南春早不见雪，腊月街头听卖花。","海国人家除夕近，满城微雨湿山茶。"]},{"t":"经历司暮春即事 其一","f":"七言绝句","c":["隔树幽禽送好音，沉沉幕府似云林。","小盆几个山茶落，桃叶满帘春雨深。"]},{"t":"经历司暮春即事","f":"七言绝句","c":["霞飞海燕拂帘过，风卷鱼鳞剪绿波。","閒倚石阑数春事，满池红雨落花多。"]},{"t":"赠道士陈华隐","f":"七言绝句","c":["早年濯足东海水，去卧华峰顶上云。","收得九秋仙掌露，归来酌献武夷君。"]},{"t":"题淮安王氏小楼 其一","f":"七言绝句","c":["江水粼粼鸭绿新，江头日日送行人。","南来北去年年事，岸草汀花自在春。"]},{"t":"题淮安王氏小楼","f":"七言绝句","c":["拂晓楼窗一半开，楼前昨夜浪如雷。","满江梅雨风吹散，无数青山渡水来。"]},{"t":"题淮安王氏小楼 其三","f":"七言绝句","c":["江月满楼江水澄，胡床据坐忆吾曾。","解吟如练澄江句，未信玄晖独擅能。"]},{"t":"题淮安王氏小楼 其四","f":"七言绝句","c":["雪满寒江压酒旗，江南无处不堪题。","小舟载得梅花去，渡领春风过水西。"]},{"t":"题画竹","f":"七言绝句","c":["小雨春池湿凤毛，天孙深夜织鲛绡。","何人更立湘江水，独倚薰风忆舜韶。"]},{"t":"彭城杂咏呈廉公亮佥事 其一","f":"七言绝句","c":["亚父冢前春草齐，楚王城上夕阳低。","黄莺不解兴亡事，飞过海棠枝上啼。"]},{"t":"彭城杂咏呈廉公亮佥事 其二","f":"七言绝句","c":["城下黄河去不回，四山依旧画屏开。","无人念得登临意，独上将军戏马台。"]},{"t":"彭城杂咏呈廉公亮佥事 其四","f":"七言绝句","c":["何处春风燕子楼，断碑落日古城头。","画眉人远繁华歇，无数远山生暮愁。"]},{"t":"彭城杂咏呈廉公亮佥事 其五","f":"七言绝句","c":["歌扇春风噀酒香，舞裙落日动鹅黄。","柳边今夜孤舟发，水远山遥空断肠。"]},{"t":"寒食马上","f":"七言绝句","c":["道傍杨柳已栖鸦，几度春深未到家。","城北城南干树雪，行人马上看梨花。"]},{"t":"燕京作","f":"七言绝句","c":["落月西窗闻禁钟，梦回远客立云龙。","江南飞尽千株雪，辜负梅花过一冬。"]},{"t":"奎章阁感兴 其一","f":"七言绝句","c":["奎章三月文书静，花落春深锁阁门。","玉座不移天步远，石碑空有御书存。"]},{"t":"奎章阁感兴 其二","f":"七言绝句","c":["花落春深似去年，无人再到阁门前。","当时济济誇多士，争进文章乞赐钱。"]},{"t":"京城立春","f":"曲","c":["燕姬白马青丝缰，短衣窄袖银?光。","御沟饮马不回首，贪看柳花飞过墙。"]},{"t":"九日遇雨","f":"七言绝句","c":["佳期不负到重阳，细雨浓阴又可伤。","试问东篱何处赏，有花无酒恼人肠。"]},{"t":"客中九日 其一","f":"七言绝句","c":["寥落天涯岁月赊，每逢佳节苦思家。","无钱沽得邻家酒，不敢开窗看菊花。"]},{"t":"客中九日 其二","f":"七言绝句","c":["佳节相逢作远商，菊花不异故人乡。","无钱沽得邻家酒，一度孤吟一断肠。"]},{"t":"过石子冈","f":"七言绝句","c":["霞光日落红穿树，山色雨馀青近人。","便好拂衣入山去，解鞍辞却马头尘。"]},{"t":"次王叔能侍御史","f":"七言绝句","c":["龙蛇偃蹇出墙阴，五色春云态度深。","台阁文章散清气，月明山馆夜萧森。"]},{"t":"醉起","f":"七言绝句","c":["杨柳楼心月满床，锦屏绣褥夜生香。","不知门外春多少，自起移灯照海棠。"]},{"t":"宫词","f":"七言绝句","c":["骏马骄嘶懒著鞭，晚凉骑过御楼前。","宫娥不识中书令，借问谁家美少年。"]},{"t":"衰柳","f":"七言绝句","c":["清凉亭上几株柳，霜夜凉风下夕阳。","依旧明年二三月，小金山上看鹅黄。"]},{"t":"戏友人","f":"七言绝句","c":["毗陵公子醉醺醺，白面迎风向酒痕。","几度小红楼上月，有人银烛掩重门。"]},{"t":"宴回","f":"七言绝句","c":["两行老柏参天翠，银烛青骢御史回。","深夜酒阑人散后，独留明月照霜台。"]},{"t":"约友游西峰不至","f":"七言绝句","c":["仙人约我峰头去，欲去峰头看白云。","一夜白云峰下宿，晓来散作雨纷纷。"]},{"t":"太平驿即事","f":"七言绝句","c":["驿鼓高悬使者稀，溪云断续树参差。","日斜山畔无人语，独立西风数桂枝。"]},{"t":"过光孝寺","f":"七言绝句","c":["秋日留题翠壁层，出山聊近在山僧。","肩舆又上沙头渡，隔水人家两岸灯。"]},{"t":"临丹青阁","f":"七言绝句","c":["飘然身在紫芝峰，翠壁丹崖有路通。","杰阁凌烟欲飞去，乱山无数夕阳中。"]},{"t":"黄河","f":"七言绝句","c":["斗杓照水半垂天，水气涨天如白烟。","南北橹声争上下，月中闻鼓避官船。"]},{"t":"沛尉蒋景山沛簿赵伯颜送予金沟月夜别去有怀","f":"七言绝句","c":["公子将军两少年，绣衣白马杏花天。","醉中送客归城暮，回首金沟月满船。"]},{"t":"和閒閒吴真人二首 其一","f":"七言绝句","c":["几度驱车上京国，五更归梦绕云林。","丹炉火伏虎书卧，石钵云寒龙夜吟。"]},{"t":"和閒閒吴真人二首 其二","f":"七言绝句","c":["天上神仙吴子晋，丹凤楼前驾鹿车。","红门下马见天子，袖有一卷养生书。"]},{"t":"兴圣寺即事三首 其一","f":"七言绝句","c":["宫阶白日杏花落，深院朱帘燕子飞。","回首人间春又老，将军白马几时归。"]},{"t":"兴圣寺即事三首 其二","f":"七言绝句","c":["御厨香动晚分羹，七宝玻瓈柈柈承。","白面内官呼小字，隔帘传旨赐中丞。"]},{"t":"兴圣寺即事三首 其三","f":"七言绝句","c":["二月深宫花似锦，柳丝垂地怯风吹。","御阶春水多三尺，丞相游湖太液池。"]},{"t":"题范阳驿","f":"七言绝句","c":["长路风寒酒力醒，马头岁月短长亭。","冻云欲雪风吹散，望出西山一半青。"]},{"t":"道傍萱花","f":"七言绝句","c":["萱草花开山路头，内家景致落林丘。","风尘不改好颜色，应与行人消百愁。"]},{"t":"书浍沟杨氏壁二首 其一","f":"七言绝句","c":["故人家在河边住，吏部书从天上来。","愧我挂冠归去晚，柳花飞尽楝花开。"]},{"t":"书浍沟杨氏壁二首 其二","f":"七言绝句","c":["杨柳人家春昼长，落花庭院燕飞忙。","买鱼沽酒黄河上，傲杀南风三月强。"]},{"t":"彭城杂咏","f":"七言绝句","c":["英雄去尽山河在，城郭荒凉草树迷。","过客无心吊千古，落花风雨听莺啼。"]},{"t":"夜过白马湖","f":"七言绝句","c":["春水满湖芦苇青，鲤鱼吹浪水风腥。","舟行未见初更月，一点渔灯落远汀。"]},{"t":"高邮至邵伯二首 其一","f":"七言绝句","c":["移棹偏惊临水雁，过淮时买出罾鱼。","有时得句无人和，风雨寒窗夜读书。"]},{"t":"高邮至邵伯二首 其二","f":"七言绝句","c":["几度秋深未到家，满湖开遍水红花。","远人日日频中酒，明月扁舟索买瓜。"]},{"t":"题淮东王廉访清凉亭","f":"七言绝句","c":["主人胸次洗冰雪，深夜金山月涌波。","二十四桥秋水白，淮南八月泻银河。"]},{"t":"次和清凉寺长老韵","f":"七言绝句","c":["缁衣送酒一壶冰，霜蒂悬香九月橙。","酌酒破橙天色晚，桂花树下出银灯。"]},{"t":"秋江横笛图为维扬苏天爵题","f":"七言绝句","c":["枫叶高低山远近，月明霜薄楚江澄。","何人吹笛孤舟外，莫是苏仙过广陵。"]},{"t":"过江后书寄成居竹","f":"七言绝句","c":["扬州酒力四十里，睡到瓜洲始渡江。","忽被江风吹酒醒，海门飞雁不成行。"]},{"t":"杨子江送同志","f":"七言绝句","c":["衮衮诸公立要津，一波才动总精神。","满江风浪晚来急，谁似中流砥柱人。"]},{"t":"夜发龙潭二首 其一","f":"七言绝句","c":["孤舟一夜发龙湫，水逆风回上石头。","暂泊沙洲过夜半，卧听钟鼓是升州。"]},{"t":"夜发龙潭二首 其二","f":"七言绝句","c":["船头夜静天如水，渡口潮平月在江。","灯影摇波风不定，老龙吹浪湿篷窗。"]},{"t":"江浦夜泊","f":"七言绝句","c":["千里长江浦月明，星河半入石头城。","棹歌未断西风起，两岸菰蒲杂雨声。"]},{"t":"金陵道中遇雨寄功父光国五首 其一","f":"七言绝句","c":["出城便喜风景好，淡水穿沙生细鳞。","多谢山云飞白雨，应教行客洗红尘。"]},{"t":"金陵道中遇雨寄功父光国五首 其二","f":"七言绝句","c":["平生梦想金陵道，此日偶然身自来。","应是山云喜诗客，野花满路雨中开。"]},{"t":"金陵道中遇雨寄功父光国","f":"七言绝句","c":["夹道长松风聒聒，满沟乱石水泠泠。","断云衔雨溪南去，失却长山一半青。"]},{"t":"金陵道中遇雨寄功父光国五首 其四","f":"七言绝句","c":["骑马何人冲白雨，乘舆有客看青山。","出城自谓身无事，冲雨看山未是閒。"]},{"t":"金陵道中遇雨寄功父光国五首 其五","f":"七言绝句","c":["梦想江南今日到，肩舆过处落花风。","行人五月金陵道，石竹花开白雨中。"]},{"t":"寓台城寄吴宗师","f":"七言绝句","c":["金陵城外凤凰台，夜夜吹箫独自来。","不见仙人倚歌和，白鹤飞下还飞回。"]},{"t":"雪中饮升龙观","f":"七言绝句","c":["银烛春船剪夜寒，道人鹤氅紫霞冠。","山瓢未尽金陵酒，玉树飞花满石坛。"]},{"t":"和王本中直台书事 其一","f":"七言绝句","c":["百尺台中谁夜直，西廊斜月照东廊。","五更梦觉春寒甚，帘外梨花满树霜。"]},{"t":"和王本中直台书事 其二","f":"七言绝句","c":["今日短衣鞭瘦马，每惭同辈说登科。","近曾夜直南台上，学得吴儿白苧歌。"]},{"t":"升龙观九日海棠杏花开二首 其一","f":"七言绝句","c":["九日江南风日暖，海棠花间杏花开。","升龙观里春光早，为是先承雨露来。"]},{"t":"升龙观九日海棠杏花开二首 其二","f":"七言绝句","c":["鼎湖龙去御床空，辇路花开旧日红。","九日人间春色早，不堪草木见秋风。"]},{"t":"寄诸台掾二首 其一","f":"七言绝句","c":["天上霜台耸百寻，诸郎不为簿书禁。","遥知閒倚东廊柱，看尽杨花过绿阴。"]},{"t":"寄诸台掾二首 其二","f":"七言绝句","c":["天上故人频寄语，江南倦客只吟诗。","梨花开尽东廊雪，又过梅黄杏熟时。"]},{"t":"赠谢舜咨羽士","f":"七言绝句","c":["扬子江头春水动，三茅洞里碧桃开。","道人不问天南北，夜半月明骑鹤来。"]},{"t":"送武侍御朝章","f":"七言绝句","c":["枫林湛湛草斑斑，御史青骢响玉环。","日暮酒醒人已去，不堪回首见青山。"]},{"t":"次程宗赐二首 其一","f":"七言绝句","c":["一冬雨雪天涯客，千里云山马上诗。","记得小红楼畔梦，杏花春雨早寒时。"]},{"t":"次程宗赐二首 其二","f":"七言绝句","c":["扬州正月雨如丝，江上梅花已尽时。","谁识能诗老何逊，晓寒明镜撚吟髭。"]},{"t":"赠来复上人四首 其一","f":"七言绝句","c":["北口雪深毡帐暖，紫驼声切夜思盐。","上人起饮黄封酒，可胜醍醐乳酪酣。"]},{"t":"赠来复上人四首 其二","f":"七言绝句","c":["燕山风起急如箭，驰马萧萧苜蓿枮。","今日吾师应不念，毳袍冲雪过中都。"]},{"t":"赠答来复上人","f":"七言绝句","c":["手持一钵走京华，乞食王侯宰相家。","今日归来如作梦，自锄明月种梅花。"]},{"t":"赠来复上人四首 其四","f":"七言绝句","c":["五云楼阁碧玲珑，口吐莲花入紫宫。","十二珠帘捲秋月，霏霏凉露下梧桐。"]},{"t":"戏王功甫","f":"七言绝句","c":["王郎酒醒倚脩竹，雪后重檐拥毳衣。","亦有江南未归客，青山影里马如飞。"]},{"t":"戏赠王本中柳枝词","f":"七言绝句","c":["日高燕语捲帘迟，独倚东风看柳枝。","三月柳花飞欲尽，远人凉露未归时。"]},{"t":"城南偶兴二首 其一","f":"七言绝句","c":["桃杏花开红映人，池塘水暖绿粼粼。","典衣沽酒入城去，报道江南二月春。"]},{"t":"城南偶兴二首 其二","f":"七言绝句","c":["断桥芳草生含路，隔水杨花飞度城。","客里不知春早晚，年年杯酒过清明。"]},{"t":"宿洞神宫春晓书事","f":"七言绝句","c":["道人睡起窗月白，饭熟黄粱鸡乱啼。","门外卖花声已过，街头春雨竟成泥。"]},{"t":"冶城三月晦日","f":"七言绝句","c":["雨前雨后莺乱啼，城南城北花交飞。","江南儿女裁苧衣；","燕京游子何时归。"]},{"t":"寄浙东聂经历","f":"七言绝句","c":["一片暮云千里隔，石头城上望天台。","夜深婺女明如镜，雁荡山前雁尽回。"]},{"t":"春日偶成二首 其一","f":"七言绝句","c":["归到江南才一月，短衣匹马又京尘。","明朝拟下江东去，晴日柳花飞送人。"]},{"t":"春日偶成二首 其二","f":"七言绝句","c":["水绕池塘朝饮马，月明苍柏夜鸣乌。","年来南北几千里，却笑书生无远图。"]},{"t":"春望","f":"七言绝句","c":["丹阳郭里春濛濛，骑马出郭诗思浓。","江南二月风雨过，梅花开尽杏花红。"]},{"t":"春暮","f":"七言绝句","c":["柳花扑帘春欲尽，绿阴满窗莺乱啼。","秪愁明日送春去，风雨满林闻竹鸡。"]},{"t":"端居书事答翟志道知事见寄韵二首 其一","f":"七言绝句","c":["短褐诗人瘦十分，平生不作送穷文。","几时结屋孤山下，为觅梅花种白云。"]},{"t":"端居书事答翟志道知事见寄韵二首 其二","f":"七言绝句","c":["瘦马春城曙色分，长年奔走愧移文。","几时黄鹤山房下，松火茶铛煮白云。"]},{"t":"镇江寄王本中台掾","f":"七言绝句","c":["梅花落尽空吹笛，正月半头思远人。","两岸好山青不断，一江微雨鹧鸪春。"]},{"t":"和友人招饮","f":"七言绝句","c":["山人开瓮满园香，短简招呼白面郎。","瘦马踏泥春巷去，一林烟雨杏梅黄。"]},{"t":"寄即休翁三首 其一","f":"七言绝句","c":["苔老应无屐齿痕，旧游历历眼中存。","秋深南国行人少，落叶萧萧满寺门。"]},{"t":"寄即休翁三首 其二","f":"七言绝句","c":["北窗终日对竹坐，老却参军不入城。","秋径山风多落叶，隔林疑是马蹄声。"]},{"t":"寄即休翁三首 其三","f":"七言绝句","c":["鹤林老子久不见，应是山门长绿苔。","几日城南风雨过，村村无处不黄梅。"]},{"t":"未归","f":"七言绝句","c":["白岩老子城中去，骢马游人寺里来。","城外风流城里少，岩花落尽野花开。"]},{"t":"夏仲书景","f":"七言绝句","c":["阶前萱草花开尽，堂上主人消百忧。","门外凉风吹树急，江南五月似凉秋。"]},{"t":"病起戏笔奉答御史王文休","f":"七言绝句","c":["江南倦客好清斋，炼得身形瘦似梅。","不到清溪三四日，藕花无数水中开。"]},{"t":"偶成","f":"七言绝句","c":["买鱼酤酒消长日，高树清风燕子閒。","却倚天南望天北，隔江青处是谁山。"]},{"t":"偶成三首 其二","f":"七言绝句","c":["自许痴儿了公事，肯教俗子议清流。","明日醉骑五花马，吹箫踏月过扬州。"]},{"t":"偶成三首 其三","f":"七言绝句","c":["疏帘日午花阴直，高柳清风语燕閒。","默坐焚香点周易，软红不到小屏山。"]},{"t":"层楼即事","f":"七言绝句","c":["浴罢焚香扫阁眠，过墙新竹翠娟娟。","半空云气层楼暗，四月江东欲雨天。"]},{"t":"纳凉","f":"七言绝句","c":["桂枝叶密阴覆地，栀子花开香满廊。","古寺纳凉过半日，葛衣石枕竹方床。"]},{"t":"寄鹤林休上人","f":"七言绝句","c":["上人才思塞胸次，强欲禁之无不鸣。","一日相望吐奇句，满林光彩照山精。"]},{"t":"宿丹阳普照院 其一","f":"七言绝句","c":["闭门三月听秋雨，酒醒丹阳客未归。","明日新晴练湖去，藕花无数落红衣。"]},{"t":"宿丹阳普照院 其二","f":"七言绝句","c":["灯火僧房伴寂寥，小凉天气入青袍。","夜深为倚西廊柱，药杵一声秋月高。"]},{"t":"逢托克托景颜","f":"七言绝句","c":["市酒泻糟清似水，湖鱼出网白如银。","买鱼沽酒丹阳郭，落日江南逢故人。"]},{"t":"赠歌者号梅芳二首 其一","f":"七言绝句","c":["露骨江南冰雪肌，断肠塞上锦绷儿。","春酸一点留无住，却是成阴结子时。"]},{"t":"赠歌者号梅芳二首 其二","f":"七言绝句","c":["玉骨冰清过岁寒，可怜蜂蝶已成团。","如何不解相如渴，散尽江南一点酸。"]},{"t":"寓栖云四首 其一","f":"七言绝句","c":["一尊未尽有馀兴，二子不来无可人。","满地凤仙落红雨，江南八月似残春。"]},{"t":"寓栖云四首 其二","f":"七言绝句","c":["盆池万点浮萍草，秋雨欲来无定踪。","好是诗人漂泊态，丹阳郭里夜间钟。"]},{"t":"寓栖云四首 其三","f":"七言绝句","c":["潇潇风雨客心孤，且尽尊前酒一壶。","夜半酒醒愁又到，一声白雁下平湖。"]},{"t":"寓栖云四首 其四","f":"七言绝句","c":["白面道人门不出，晚凉倚树听秋风。","最怜八月江南好，老雁叫云霜叶红。"]},{"t":"题隐上人房","f":"七言绝句","c":["练湖秋水霜眼碧，坐对茅盈山色青。","白日散花天女降，夜深钟磬尚闻经。"]},{"t":"寄金坛元鲁宣差行操二年兄","f":"七言绝句","c":["苍茫迥野冻云低，马上遥山玉四围。","自是诗人有清气，出门千树雪花飞。"]},{"t":"宿陵口寺","f":"七言绝句","c":["西风落叶陵口寺，薄暮钟声送夕阳。","酒醒不知过夜半，开门满地月如霜。"]},{"t":"题郑谷驿","f":"七言绝句","c":["谁处江东郑老家，自锄谷口种烟霞。","远山三月多归思，晴日东窗见杏花。"]},{"t":"赠张道士","f":"七言绝句","c":["道人新戴竹皮冠，头上星摇北斗寒。","一夜凉风吹发乱，半窗鹤梦绕琅玕。"]},{"t":"题吕城葛观二首 其一","f":"七言绝句","c":["诸葛仙翁七十馀，吕蒙城下筑幽居。","来从方外求丹诀，且乞人间教子书。"]},{"t":"题吕城葛观","f":"七言绝句","c":["吕公城下葛仙家，洞府春深锁暮霞。","过客不知天畔月，小风吹落凤仙花。"]},{"t":"延陵曲","f":"七言绝句","c":["延陵庙西落日低，延陵庙前春草齐。","千金公子去不返，淡云苦竹斑鸠啼。"]},{"t":"宿延陵昌国寺书于上人房二首 其一","f":"七言绝句","c":["旧日延陵客子家，只今门巷满桑麻。","姑苏回首神游处，无限春风野荠花。"]},{"t":"宿延陵昌国寺书于上人房二首 其二","f":"七言绝句","c":["东风吹水碧粼粼，雨过村村野色新。","小艇延陵庙前去，荇花开尽野塘春。"]},{"t":"谢人惠茶","f":"七言绝句","c":["送茶将军扣门急，惊觉秋深梦一窗。","半夜竹炉翻蟹眼，只疑风雨下湘江。"]},{"t":"题李蓟丘画松","f":"七言绝句","c":["平生恨不识遵道，忽见此图如梦间。","安得羲之九泉底，枯林风雨似初还。"]},{"t":"吴僧子庭古木竹","f":"七言绝句","c":["岁寒古木性所爱，况有此君初附之。","江湖眼明世无几，太息不生元祐时。"]},{"t":"和韵寄吴城陈敬初","f":"七言绝句","c":["吴江酒熟照行人，春江小雨波粼粼。","一樽未尽忽晴日，江头柳花撩乱春。"]},{"t":"席上次顾玉山韵","f":"七言绝句","c":["画墙班鸠啼绿树，白日紫燕穿朱帘。","昼长深院弄瑶瑟，吴姬十指行春纤。"]},{"t":"去吴留别于寿道陈子平诸友 其一","f":"七言绝句","c":["吴堤杨柳雨霏霏，四月犹寒总夹衣。","此去孤舟无好伴，空江惟见白鸥飞。"]},{"t":"去吴留别干寿道陈子平诸友","f":"七言绝句","c":["一尊判袂阖闾城，莫指青山管送行。","芳草绿波千万里，不闻杜宇也伤情。"]},{"t":"季夏游杭灵隐诸峰","f":"七言绝句","c":["佛国群山快我登，烟霞踏破几层层。","三天竺畔全无暑，六月松阴尺五冰。"]},{"t":"秋日寓钱塘","f":"七言绝句","c":["小楼一榻钱塘客，况味凄凉序属秋。","安得江淹赋予笔，因而书作半生愁。"]},{"t":"青松林","f":"七言绝句","c":["一点两点过云雨，千株万株临路松。","五月江南好风景，行人马上不从容。"]},{"t":"宿经山寺二首 其一","f":"七言绝句","c":["野人一宿经山寺，十里松声半夜潮。","何日挂冠寻旧隐，山中应有故人招。"]},{"t":"宿经山寺二首 其二","f":"七言绝句","c":["山中酒熟客初至，正是东林月上时。","痛饮不知过夜半，深山风露下松枝。"]},{"t":"题竹院壁","f":"七言绝句","c":["门外好山青入户，阶前芳草绿侵帘。","山僧应笑游人醉，头上花枝压帽檐。"]},{"t":"书高贤坊","f":"七言绝句","c":["穿松翠滴青骢马，过雨凉生白苧衣。","三月已过四月半，柳花开尽楝花飞。"]},{"t":"常山纪行 其一","f":"七言绝句","c":["绿阴门巷掩柴扉，五月江南笋蕨肥。","何处清香来马上，满山开遍野蔷薇。"]},{"t":"常山纪行 其二","f":"七言绝句","c":["山溜涓涓山雨晴，村南村北鹁鸠鸣。","行人五月不知倦，喜听农家打麦声。"]},{"t":"常山纪行 其三","f":"七言绝句","c":["石羊华表草离离，古木残阳立断碑。","马上不知何代冢，鹧鸪飞上野棠枝。"]},{"t":"常山纪行 其四","f":"七言绝句","c":["石壁飞泉作雨声，野花满路酒初醒。","吾侬何事不归去，一带长山马上青。"]},{"t":"常山纪行 其五","f":"七言绝句","c":["蚕妇携筐入桑柘，野猿抱子挂松萝。","绿阴门巷客呼酒，黄犊山村人唱歌。"]},{"t":"过浦城","f":"七言绝句","c":["人家鸡犬隔痴岚，城郭微茫见塔尖。","一片轻云笼马首，熟梅时节雨纤纤。"]},{"t":"到闽二首 其一","f":"七言绝句","c":["朔雪蛮烟总备尝，白头才到荔枝乡。","浮云不阻怀贤意，得扫寒芜拜紫阳。"]},{"t":"到闽二首 其二","f":"七言绝句","c":["潮水通城蚬蛤肥，万株红荔艳晴晖。","守臣只恐山飞去，高筑闉阇锁翠微。"]},{"t":"次繁昌邑宰梅双溪韵","f":"五言古诗","c":["矍铄繁昌宰，曾充观国宾。","儒冠犹破帽，礼服尚垂绅。","澹泊心无愧，清癯目有神。","老随朱绂贵，惊见白头新。","抚字三年政，歌谣百里民。"]},{"t":"题进士索士岩诗卷士岩与余同榜又同为燕南官由翰林编修为御史台掾兼经筵检讨除为燕南廉访经历","f":"五言古诗","c":["忆昔登天府，文华萃帝乡。","俊才鱼贯列，多士雁成行。","宝剑悬秋水，骊珠耿夜光。","三场如拾芥，一箭已穿杨。","上策师周孔，飞声陋汉唐。","凤池开御宴，虎榜出宫墙。","赐笏丘山重，恩袍雨露香。","天花皆剪翠，法酒尽封黄。","冠盖游三日，声名满四方。","历阶超宰辅，捧表谢君王。","第甲分三馆，镌碑立上庠。","曲江嘉宴会，合席尽才良。","契谊同昆弟，比和鼓瑟簧。","誓辞犹在耳，离思各惊肠。","台阁需材器，儒林作栋梁。","超迁乌府掾，辉映绣衣郎。","迫晏封几事，平明出奏章。","日披坟典旧，时念簿书忙。","检讨超经幄，论思近御床。","圣朝稽古道，日暮下回廊。","羁旅然薪桂，长吟出锦坊。","弱妻贫且病，羸马瘦仍僵。","穷巷回车辙，空厨泛酒浆。","故人传奏目，请便趣行装。","皇极三台重，燕南各道昌。","承恩辞魏阙，揽辔去恒阳。","晓幕芙蓉露，秋空柏树霜。","诸司循直矢，群吏肃宏纲。","汉水浮神马，岐山出凤凰。","行须冠獬豸，已见走豺狼。","惭愧蓬蒿翼，乘风亦下翔。"]},{"t":"送丁太初赴永嘉学正十八韵","f":"五言古诗","c":["国学崇儒代，人材绝妙年。","风云千里骏，日月九重天。","翰苑司抡选，中书属次铨。","光荣毛义檄，奋发祖生鞭。","学广儒官制，书传子弟员。","宦情依冷掾，官舍拥寒毡。","筮仕无踰此，如君更颖然。","永嘉今永郡，多艺夙多贤。","咨访兼留意，英髦孰接肩。","旧家疑寂寞，遗业想流传。","会看声华盛，应知德业全。","高情何特达，朦目共周旋。","春著花间屐，秋乘柳下船。","篇章微点染，山水自清妍。","荐豆登霜柚，充厨载海鲜。","洞箫吹月下，玉树立风前。","已作鱼龙变，何嫌雨露偏。","群公争荐进，拭目著腾骞。"]},{"t":"同御史王伯循时除广东佥事济扬子江余除燕南照磨","f":"七言绝句","c":["落叶正飞扬子渡，行人又上广陵船。","过江载得秋多少，老雁一声霜满天。"]},{"t":"过高邮射阳湖杂咏九首 其一","f":"五言绝句","c":["飘萧树梢风，淅沥湖上雨。","不见打鱼人，菰蒲雁相语。"]},{"t":"题焦山方丈","f":"五言律诗","c":["江风入霜林，寒叶下疏雨。","萧萧复萧萧，可听不可数。","山僧亦好奇，呼童扫行路。","何处觅秋声，肩舆入山去。"]},{"t":"送吴寅可之扬州","f":"五言律诗","c":["青杨吹白花，银鱼跳碧藻。","落日江船上，三月淮南道。","渺渺春水涯，悠悠云树杪。","安得快剪刀，江头剪芳草。"]},{"t":"寄王伯循诸公 其一","f":"五言律诗","c":["木落淮南秋，兰桡泊瓜渚。","把酒三人同，江亭看飞雨。","雨过江色净，妙景发天趣。","历历江南山，一一青可数。"]},{"t":"寄王伯循诸公 其二","f":"五言律诗","c":["大江涌金光，稳如青莲座。","就中有龙宫，人见不敢唾。","江山万古同，日月片帆过。","把酒妙高台，狂歌醉相和。"]},{"t":"寄王伯循诸公 其三","f":"五言律诗","c":["飘飘鹤林僧，布袜青鞋双。","长江飞锡渡，海磬鱼龙撞。","远来作偈别，楚雨鸣秋窗。","振锡独归去，天花飞满江。"]},{"t":"寄王伯循诸公 其四","f":"五言律诗","c":["微茫扬子桥，细雨湿秋色。","小艇载吴姬，摇摇语相接。","风起布帆高，一往不再得。","夜宿广陵城，吹箫怨明月。"]},{"t":"过居庸关","f":"曲","c":["居庸关，山苍苍，关南暑多关北凉。","天门晓开虎豹卧，石鼓昼击云雷张。","关门铸铁半空倚，古来几多壮士死。","草根白骨弃不收，冷雨阴风哭山鬼。","道傍老翁八十馀，短衣白发扶犁锄。","路人立马问前事，犹能历历言丘墟。","夜来芟豆得戈铁，雨蚀风吹半棱折。","色消唯带土花腥，犹是将军战时血。","前年又复铁作门，貔貅万灶如云屯。","生者有功挂六印，死者谁复招孤魂？","居庸关，何峥嵘。","上天胡不呼六丁，驱之海外消甲兵。","男耕女织天下平，千古万古无战争。"]},{"t":"夜泊钓台","f":"七言古诗","c":["双崖屹立几千仞，下有一叶之孤舟。","繁星乱垂光晔晔，长藤古木风飕飕。","荒祠幽黑山鬼集，怪石如人水边立。","锦峰绣岭云气深，万壑千岩露华滴。","山僧对话夜未央，不知风露满衣裳。","唤船振锡渡江去，林黑无由归上方。","高寒宇宙无人语，乱石滩声溅飞雨。","欲从严子借羊裘，坐待船头山月吐。"]},{"t":"崔镇阻风有感","f":"七言律诗","c":["逆风吹河河倒行，阻风时节近清明。","南人北人俱上冢，桃花杏花开满城。","虽云少年惯作客，便觉此日难为情。","河鱼春酒不足醉，赖有同舟好弟兄。"]},{"t":"寒夜闻角","f":"七言古诗","c":["野人卧病不得眠，呜呜画角声凄然。","黄云隔断塞北月，白雁叫破江南烟。","山城地冷迫岁暮，野梅雪落溪风颠。","长门美人怨春老，新丰逆旅惜年少。","夜深悲壮声摇天，万瓦月白霜华鲜。","野人一夜梦入塞，走马手提铁节鞭。","髑髅饮酒雪一丈，壮士起舞毡帐前。","五更梦醒气如虎，将军何人知在边。"]},{"t":"题刘涣中司空隐居图","f":"七言律诗","c":["放光山下结茅庐，光照山人夜读书。","童子抱琴随白鹤，邻翁看竹借篮舆。","门前秋叶从风扫，屋后春田带雨锄。","自笑天涯倦游客，十年未有一廛居。"]},{"t":"丞相出猎","f":"七言律诗","c":["将军一战山河定，云汉昭回玉树高。","柳外解鞍春洗马，月中飞箭夜鸣雕。","呼鹰走狗清时乐，斩将搴旗旧日劳。","白面内官催赐酒，汉庭不数霍嫖姚。"]},{"t":"寄京口鹤林寺长老了即休","f":"七言律诗","c":["白头不出城南寺，枯坐蒲团笑客忙。","过暑葛衣浑破碎，逢秋竹院愈荒凉。","空山云湿龙归钵，古屋松低鹤在床。","遥忆题诗旧游处，夜深东壁月苍苍。"]},{"t":"三衢马太守昂夫索题烂柯山石桥","f":"七言律诗","c":["洞口龙眠紫气多，登临聊和《采芝歌》。","烂柯仙子何年去，鞭石神人此地过。","乌鹊横空秋有影，银河垂地水无波。","遥知题柱凌云客，天近应闻织女梭。"]},{"t":"寄参政许可用","f":"七言律诗","c":["紫髯参政黑头公，日日鸣珂近九重。","花底听莺黄阁散，御前剖竹紫泥封。","都将笔下文章润，散作人间雨露浓。","未信吟诗趋幕府，霜寒翠袖倚芙蓉。"]},{"t":"送佥事王君实之淮东","f":"七言律诗","c":["使君腊月扬州去，东阁梅开雪压枝。","淮上有官皆避马，竹西无处不题诗。","春风杨柳平沙路，夜月琼花后土祠。","从此公馀多胜览，好传佳句远人知。"]},{"t":"度闽关二首 其一","f":"五言古诗","c":["晓度分水岭，身在云雾中。","手扣天上关，声落山下风。","雷霆走涧壑，神人过虚空。","既讶奔丰隆，亦可招祝融。","顷刻开万象，赤乌飞岭东。"]},{"t":"度闽关二首 其二","f":"五言古诗","c":["白云下千峰，尽入怀袖里。","振衣度闽关，洒作山下水。","仰登天无梯，俯视井无底。","古来守关人，豪杰存有几。","寒食百草青，春风吹不起。"]},{"t":"过岭至崇安方命棹之建溪","f":"五言古诗","c":["人生天地间，驰马历大块。","行乐须及时，流光逝难再。","役役功名羁，历历山水迈。","伟哉东南区，奇险闽粤最。","车书四海同，风气一岭界。","肩舆度层霄，手棹下急濑。","四山抱回流，环合如束带。","玉井莲叶飘，仰高天作盖。","倏驰丹峰前，却在紫岭背。","微云间烟霞，疏雨洒松桧。","深林樵牧归，落日山鬼会。","雪瀑挂冰帘，林风响天籁。","石梯驾仙岩，往往遗骨在。","瑶草石上生，丹药市中卖。","巍巍考亭祠，过客祠下拜。","溪水自成文，上接洙泗派。","唤渡云门僧，貌古清可爱。","手把青松枝，趺坐溪石罅。","悬崖虹栈危，插竹渔网晒。","山高人蚁旋，下视舟一芥。","轻舫类飞鳅，宛转乱石隘。","峥嵘龙角尖，磊砢鼋首癞。","槎牙激颓波，出没如水怪。","万古槌地雷，三峡泻泙湃。","峰峦争送迎，奔走万马快。","箭过耳生风，开口不暇咳。","峭壁起冲流，恍若巨鳌戴。","山有旧题名，岁久字刻坏。","岂无姓名存，彷佛年月载。","览此前人踪，徒为后人慨。","天气易寒暄，光阴倏明晦。","浩荡三日程，应接千万态。","会登天柱峰，一览宇宙大。","少吐胸中豪，神游八方外。","题诗赠山灵，清气留胜概。"]},{"t":"游吴山紫阳庵","f":"七言律诗","c":["天风吹我登鳌峰，大山小山石玲珑。","赤霞日烘紫玛瑙，白露夜滴青芙蓉。","飘绡云起穿石屋，石上凉风吹紫竹。","挂冠何日赋《归来》，煮茗篝灯洞中宿。"]},{"t":"快雪轩","f":"七言古诗","c":["吴刚粉月成琼屑，洒向人间沃春热。","门外青山不得青，刮地东风翻挞末。","梨花云湿飞难起，晓来化作湘江水。","娟娟美人耐高寒，对此心开几千里。","山阴夜冷沙棠小，归来狂兴犹孤悄。","古春吹到矮茅茨，香浮茗椀滋诗脾。"]},{"t":"明皇击梧图","f":"七言古诗","c":["华清池头凉思动，绿桐击去朝阳凤。","阿环起学飞燕轻，笑唤三郎作供奉。","羯腔打彻《西凉州》，锦茵蹴踏双鸳钩。","彩鸾吟细朱樱破，一叶忽飘天下秋。","愁声换出铎铃语，三十六宫散秋雨。","曲江宫晓清露寒，零乱瑶阶逐风舞。"]},{"t":"秋夜京口","f":"七言律诗","c":["铁瓮城头刻漏迟，凉霜如雪扑帘飞。","雁声到地梦回枕，月色满船人捣衣。","塞北将军犹索战，江南游子苦思归。","呼鹰腰箭纵围猎，苜蓿秋深马正肥。"]},{"t":"同曹克明清明日登北固山次韵 其二","f":"七言律诗","c":["三月二日风日暖，千家万家桃杏开。","白日少年骑马过，红雨满城排面来。","共君且须饮一斗，处世不必歌《七哀》。","孙刘事业今何在，百年狠石生莓苔。"]},{"t":"和参政王继学海南初还韵","f":"七言律诗","c":["飘零南北与东西，倦鸟投林未许栖。","灯下冷风山鬼到，岭南春雨竹鸡啼。","炎天海国瘴烟合，深夜蛮乡客语低。","昔日持书乌府上，五花骢马凿霜蹄。"]},{"t":"游崇禧寺有感","f":"七言律诗","c":["紫翠云中出雨堂，老僧挥泪忆先皇。","赤阑相映苔花落，翠辇不来山路荒。","此日山河消王气，旧时草木识天香。","夜深行殿无人到，应有山云护御床。"]},{"t":"偕廉公亮游钟山","f":"七言律诗","c":["十里松风吹酒醒，马头云气碧崚嶒。","空山落叶时闻雨，古塔疏林夜见灯。","胜地难逢今日会，旧游却记向年曾。","使君五老峰前去，应有新诗寄病僧。"]},{"t":"同吴郎饮道院","f":"七言律诗","c":["三月江南飞柳花，松间童子脸如霞。","旋酤采石仙人酒，来访山阴道士家。","落日下城人影散，东风吹马帽檐斜。","吴郎今夜孤舟渡，回首江心月半沙。"]},{"t":"忆观驾春蒐二首 其二","f":"七言律诗","c":["日奏云间紫凤箫，春随天上赭黄袍。","仗前虎将千斤斧，架上鹰儿五色绦。","猎士开弓黄犬疾，宫官击鼓紫驼高。","侍游亦有中书令，七宝雕盘看绿毛。"]},{"t":"京城春日","f":"七言绝句","c":["燕姬白马青丝缰，短鞭窄袖银镫光。","御沟饮马重回首，贪看杨花飞过墙。"]},{"t":"燕山客舍","f":"七言绝句","c":["落日西山闻禁钟，梦回远客在卢龙。","江南飞尽千株雪，孤负梅花过一冬。"]},{"t":"彭城杂咏四首 其一","f":"七言绝句","c":["城下黄河去不回，四山依旧翠屏开。","无人会得登临意，独上将军戏马台。"]},{"t":"彭城杂咏四首 其三","f":"七言绝句","c":["黄河三面绕孤城，独倚危阑眼倍明。","柳絮飞飞三月暮，楼头犹有卖花声。"]},{"t":"与弟别渡淮二首 其二","f":"七言绝句","c":["东南风送渡淮船，过雁声哀水拍川。","落日淡霞收未尽，又随明月荡秋天。"]},{"t":"清凉亭衰柳","f":"七言绝句","c":["清凉亭上几株霜，脱叶难遮夕照光。","依旧明年二三月，小童山下看鹅黄。"]},{"t":"句容道中遇雪","f":"七言绝句","c":["何处吴姬压酒家，短衣匹马路盘斜。","东风不识陈宫恨，一路吹开玉树花。"]},{"t":"和全子仁","f":"七言绝句","c":["毗陵公子醉昏昏，白面迎风散酒痕。","几度小红楼畔月，有人吟倚掩重门。"]},{"t":"题画","f":"曲","c":["绿树阴藏野寺，白云影落溪船。","遮却青山一半，只疑僧舍茶烟。"]},{"t":"题四时宫人图四首 其一","f":"七言古诗","c":["紫宫风暖百花香，玉人端坐七宝床。","凤凰小架悬夜月，一女侍镜观浓妆。","背后一女冠乌帽，茶色宫袍靴色皂。","手持团扇不动尘，一掬香弯立清晓。","一女浅步腰半驼，小扇轻扑花间蛾。","淡阴桐树一女立，手抱胡床眼转波。","床头细锁悬金钟，白鹤双飞花影重。","词人见此神恍惚，巫山梦里曾相逢。"]},{"t":"题四时宫人图四首 其二","f":"七言古诗","c":["金猊吐烟清昼长，美人坐倚白玉床。","蓝衫一女髻垂耳，手持方扇立坐傍。","一女最小不会妆，高眉短发耀漆光。","玉纤绿笋握金剪，柳下轻挽宫人裳。","金盘玉瓮左右列，红桃碧藕冰雪凉。","冰壶之傍立一女，背后随以双白羊。","手拱金瓶泻水忙，酒翅洒雪惊鸳鸯。","鸳鸯得水自双浴，美人抱膝空断肠。"]},{"t":"题四时宫人图四首 其三","f":"七言古诗","c":["盆池露冷荷半枯，碧波风细双游鱼。","美人坐此碧玉椅，屏山方案碧蟾蜍。","椅后二女执缨立，案前二女娇滴滴。","大女手扶小女腰，小女娇倚大女膝。","凉风入树落翠槐，秋深不见羊车来。","金铃响处吠黄犬，美人笑托芙蓉腮。"]},{"t":"题四时宫人图四首 其四","f":"七言古诗","c":["锦屏三面围绣床，沈香椅上凤褥光。","美人端坐袖双手，临眉半蹙愁夜长。","椅后一女摇白羽，一女执缨更回顾。","一女乌帽金缕衣，玉指纤纤携小女。","小女手挽大女腰，笑看孔雀双翠翘。","可怜美人独自坐，翠竹雪响风前梢。"]},{"t":"过高邮射阳湖杂咏九首 其二","f":"五言绝句","c":["秋风吹白波，秋雨鸣败荷。","平湖三十里，过客感秋多。"]},{"t":"过高邮射阳湖杂咏九首 其五","f":"五言绝句","c":["白鹭爱秋水，独立仍自行。","得鱼固偶尔，惊飞亦常情。"]},{"t":"竹枝词","f":"七言绝句","c":["湖上美人弹玉筝，小莺飞度绿窗楞。","沈郎虽病多情在，倦倚屏山不厌听。"]},{"t":"西湖绝句六首 其一","f":"七言绝句","c":["涌金门外上湖船，狂客风流忆往年。","十八女儿摇艇子，隔船笑掷买花钱。"]},{"t":"西湖绝句六首 其二","f":"七言绝句","c":["少年豪饮醉忘归，不觉湖船旋旋移。","水面夜凉银烛小，越娘低唱月生眉。"]},{"t":"西湖绝句六首 其三","f":"七言绝句","c":["紫骝骄蹋落花泥，二月江城雨过时。","拂晓市河春水满，小船多半载吴姬。"]},{"t":"西湖绝句六首 其四","f":"七言绝句","c":["惜春曾向吴船宿，酒渴吴姬夜破橙。","蓦听郎君呼小字，转头含笑背银灯。"]},{"t":"西湖绝句六首 其五","f":"七言绝句","c":["待得郎君半醉时，笑将纨扇索题诗。","小红帘卷春波绿，度水杨花落砚池。"]},{"t":"西湖绝句六首 其六","f":"七言绝句","c":["垂柳阴阴苏小家，满湖飞燕趁杨花。","繁华一去风流减，今日横堤几树鸦。"]},{"t":"次韵王侍郎游湖","f":"七言律诗","c":["绮席新凉舞袖偏，赏心输与使君专。","螺杯注酒摇红浪，綵扇题诗染绿烟。","一镜湖光开晓日，万家花气涨晴天。","涌金门外春如海，画舫笙歌步步仙。"]},{"t":"纪事","f":"七言律诗","c":["当年铁马游沙漠，万里归来会二龙。","周氏君臣空守信，汉家兄弟不相容。","祇知奉玺传三让，岂料游魂隔九重。","天上武皇亦洒泪，世间骨肉可相逢。"]},{"t":"虾助诗","f":"七言律诗","c":["层涛濡沬缀虾行，水母含秋孕地灵。","海气冻成红玉脆，天风寒结紫云腥。","霞衣褪色脂流滑，琼缕烹香酒力醒。","疑是楚江萍实老，误随潮汐落沧溟。"]},{"t":"尾声・若道是成就了洞房中惜玉怜香愿，媒合了翠馆内清风皓月筵，六片","f":"曲","c":["儿香皮做烟眷。","茶コ架边，蔷薇洞前，管教你到底团圆不离了半步儿远。"]}]};